INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Adjective-Review.html','general','「きれい」はどちらのタイプ？','["い形容詞", "な形容動詞", "両方", "どちらでもない"]'::jsonb,1,'きれい=na形容動詞(例外). 見た目はiで終わるが語幹. きれいな部屋(修飾), きれいに(副詞), きれいで(て形). 同様: きらい(な)=嫌い。','medium',NULL,'{"general"}',794494132);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Adjective-Review.html','general','「大きい」の過去否定形は？','["大きいくなかった", "大きなかった", "大きくなかった", "大きじゃなかった"]'::jsonb,2,'い形容詞過去否定=〜くなかった. 大きい→大きく+なかった=大きくなかった. 同様: 高くなかった、安くなかった。','medium',NULL,'{"general"}',15859171);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Adjective-Review.html','general','「静か」を副詞にする時は？','["静かく", "静かに", "静かで", "静かだ"]'::jsonb,1,'な形容動詞の副詞=〜に. 静かに話す=bicara dengan tenang. い形容詞の副詞=〜く: 大きく開ける。','medium',NULL,'{"general"}',1897522643);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Adjective-Review.html','general','「いい」の否定形は？','["いいくない", "よくない", "よくない ✅", "いいじゃない"]'::jsonb,2,'いい→よ〜に変わる(否定以外も全部). よくない(否定), よかった(過去), よくなかった(過去否定), よくて(て形), よく(副詞)。','medium',NULL,'{"general"}',999975435);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Adjective-Review.html','general','「大きくて重い」の「くて」は？','["な形のて形", "い形のて形", "動詞のて形", "助詞"]'::jsonb,1,'い形容詞のて形=〜くて. 大きい→大きくて. な形のて形=〜で: 静かで. 動詞のて形=〜て/んで/いて等。','medium',NULL,'{"general"}',1570007334);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Adjective-Review.html','general','「便利な駅」のように名詞を修飾する「な」は？','["い形容詞のな", "な形容動詞が名詞を修飾する時に必要", "助動詞", "接続詞"]'::jsonb,1,'な形容動詞+N=〜な+N. 便利な駅, 静かな場所, きれいな花. い形容詞はなしでそのまま: 大きい駅.','medium',NULL,'{"general"}',665893196);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Adjective-Review.html','general','「部屋を静かにする」の意味は？','["部屋が静かになる", "部屋を静かな状態にする(意図的)", "静かになりたい", "静かに入る"]'::jsonb,1,'〜にする=membuat jadi ~(意図的変化). 部屋を静かにする=membuat kamar jadi tenang. 〜になる=自然に変化する。','medium',NULL,'{"general"}',463775882);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Counter-Words-Advanced.html','general','「鉛筆3本」の読み方は？','["えんぴつさんほん", "えんぴつさんぼん", "えんぴつさんぽん", "えんぴつみっぽん"]'::jsonb,1,'3本=さんぼん(濁音化). 1本=いっぽん, 3本=さんぼん, 6本=ろっぽん, 8本=はっぽん. 〜本は細長いものを数える。','medium',NULL,'{"general"}',196756276);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Counter-Words-Advanced.html','general','「猫2匹」の読み方は？','["ねこにひき", "ねこにぴき", "ねこにびき", "ねこふたひき"]'::jsonb,2,'2匹=にひき→にびき(? 実は「にひき」が正しい). 変化: 1匹=いっぴき, 3匹=さんびき, 6匹=ろっぴき, 8匹=はっぴき.','medium',NULL,'{"general"}',54028460);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Counter-Words-Advanced.html','general','「コーヒー1杯」の読み方は？','["コーヒーいちはい", "コーヒーいっぱい", "コーヒーひとはい", "コーヒーいちぱい"]'::jsonb,1,'1杯=いっぱい(促音+半濁音化). 3杯=さんばい, 6杯=ろっぱい, 8杯=はっぱい。','medium',NULL,'{"general"}',228690503);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Counter-Words-Advanced.html','general','「手紙2通」の読み方は？','["てがみにつう", "てがみふたつう", "てがみにとう", "てがみにとお"]'::jsonb,0,'2通=につう. 〜通(つう)=surat, email, dokumen. 手紙2通=2 lembar surat。','medium',NULL,'{"general"}',1972322544);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Counter-Words-Advanced.html','general','「馬3頭」と「猫3匹」の違いは？','["同じ", "頭は大きい動物、匹は小さい動物に使う", "頭は野生、匹はペット", "どちらでも使える"]'::jsonb,1,'頭(とう)=hewan besar(馬・牛・象・キリン). 匹(ひき)=hewan kecil(猫・犬・魚・虫). サイズで使い分ける。','medium',NULL,'{"general"}',514562086);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Counter-Words-Advanced.html','general','「本を2冊」の「冊」は何を数える？','["本のページ", "本や雑誌などの冊子", "本の著者", "本の価格"]'::jsonb,1,'〜冊(さつ)=buku, majalah, pamflet. 1冊=いっさつ. 教科書2冊=2 buku teks. 雑誌3冊=3 majalah。','medium',NULL,'{"general"}',1069217286);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Frasa-Praktis-Harian.html','expression','Bagaimana menanyakan harga suatu barang?','["おいしいですか", "いくらですか", "どこですか", "なんですか"]'::jsonb,1,'いくらですか (ikura desu ka) berarti ''berapa harganya?''. Frasa ini bisa dipakai langsung sambil menunjuk barang, atau ditambah nama barang di depannya: これはいくらですか.','medium',NULL,'{"expression"}',47952133);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Frasa-Praktis-Harian.html','expression','Apa yang diucapkan SEBELUM makan?','["ごちそうさま", "いただきます", "おいしい", "おねがいします"]'::jsonb,1,'いただきます (itadakimasu) diucapkan sebelum makan sebagai ungkapan rasa syukur atas makanan, bukan sekadar ''selamat makan'' — mengandung makna menghargai proses makanan sampai ke meja.','medium',NULL,'{"expression"}',629848858);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Frasa-Praktis-Harian.html','expression','''お会計をお願いします'' artinya?','["Tolong menunya", "Tolong bonnya (bayar)", "Tolong airnya", "Enak sekali"]'::jsonb,1,'お会計をお願いします (okaikei o onegaishimasu) berarti ''tolong hitung tagihannya'', dipakai saat meminta bon di restoran. Ungkapan ini sopan dan umum digunakan di seluruh Jepang.','medium',NULL,'{"expression"}',391429462);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Frasa-Praktis-Harian.html','expression','Bagaimana menanyakan letak stasiun?','["駅はどこですか", "駅はなんですか", "駅はいくらですか", "駅はいつですか"]'::jsonb,0,'駅はどこですか (eki wa doko desu ka) berarti ''di mana stasiun?''. Pola ini bisa diganti kata benda lain untuk menanyakan lokasi apa pun: トイレはどこですか (di mana toilet?).','medium',NULL,'{"expression"}',1459942730);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Frasa-Praktis-Harian.html','expression','''まっすぐ行ってください'' artinya?','["Belok kanan", "Belok kiri", "Lurus terus", "Berhenti"]'::jsonb,2,'まっすぐ (massugu) berarti lurus, sehingga kalimat ini berarti ''silakan jalan lurus''. Kata arah lain yang penting: 右=kanan, 左=kiri, sering muncul bersama dalam petunjuk jalan.','medium',NULL,'{"expression"}',1410511389);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Frasa-Praktis-Harian.html','expression','Bagaimana mengatakan ''Saya tidak mengerti''?','["わかります", "わかりません", "わかりました", "しりません"]'::jsonb,1,'わかりません (wakarimasen) berarti ''saya tidak mengerti/tidak tahu''. Frasa dasar ini penting dikuasai karena sering dipakai untuk memberi tahu lawan bicara agar menjelaskan dengan cara lain.','medium',NULL,'{"expression"}',1905196352);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Frasa-Praktis-Harian.html','expression','Frasa untuk minta lawan bicara mengulang?','["ゆっくり話してください", "もう一度お願いします", "助けてください", "大丈夫です"]'::jsonb,1,'もう一度お願いします (mou ichido onegaishimasu) berarti ''tolong sekali lagi''. Frasa ini sopan dan bisa dipakai dalam berbagai situasi, dari percakapan sehari-hari hingga telepon bisnis.','medium',NULL,'{"expression"}',973434757);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Frasa-Praktis-Harian.html','expression','Saat memperkenalkan asal negara, ''____から来ました''','["に", "で", "から", "を"]'::jsonb,2,'〜から来ました (kara kimashita) berarti ''datang dari…''. Pola ini dipakai setelah menyebutkan nama negara/kota asal, misalnya インドネシアから来ました (saya datang dari Indonesia).','medium',NULL,'{"expression"}',112774616);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Frasa-Praktis-Harian.html','expression','''助けてください'' digunakan saat?','["Memesan makanan", "Butuh pertolongan darurat", "Berterima kasih", "Berbelanja"]'::jsonb,1,'助けてください (tasukete kudasai) berarti ''tolong saya'' — dipakai dalam situasi darurat atau saat benar-benar membutuhkan bantuan segera, bukan untuk permintaan bantuan sehari-hari yang ringan.','medium',NULL,'{"expression"}',489427838);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Frasa-Praktis-Harian.html','expression','Bagaimana menanyakan ''Bisa bayar pakai kartu?''','["カードで払えますか", "現金で払います", "いくらですか", "袋をください"]'::jsonb,0,'カードで払えますか (kaado de haraemasu ka) berarti ''bisakah bayar dengan kartu?''. Partikel で menunjukkan alat pembayaran, dan 払えます adalah bentuk potensial dari 払う (membayar).','medium',NULL,'{"expression"}',536660717);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Giving-Receiving.html','general','「友達が本をくれた」の意味は？','["私が友達に本をあげた", "友達が私に本をくれた(私が受け取った)", "私が友達から本をもらった", "全部同じ"]'::jsonb,1,'くれる=orang lain memberi ke pembicara (私). 友達が本をくれた=teman memberiku buku. くれるの主語は常に他者。','medium',NULL,'{"general"}',1720813097);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Giving-Receiving.html','general','「先生にほめてもらった」の意味は？','["先生が私をほめた(先生視点)", "私は先生にほめてもらった(私が受け取った行為)", "私が先生をほめた", "先生が他の人をほめた"]'::jsonb,1,'てもらう=menerima tindakan dari orang lain. 先生にほめてもらった=saya menerima pujian dari guru(sudut pandang penerima).','medium',NULL,'{"general"}',958950259);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Giving-Receiving.html','general','「友達に教えてあげた」の意味は？','["友達が私に教えた", "私が友達のために教えた", "友達が誰かに教えた", "全部同じ"]'::jsonb,1,'てあげる=melakukan tindakan untuk orang lain. 友達に教えてあげた=saya mengajari teman(demi teman). 視点: 私が施す。','medium',NULL,'{"general"}',840723080);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Giving-Receiving.html','general','「先生がくださる」は何の敬語？','["あげる", "もらう", "くれる", "する"]'::jsonb,2,'くださる=尊敬語 untuk くれる. 先生がくださる=guru (dengan hormat) memberikan. 対: いただく=謙譲語 untuk もらう。','medium',NULL,'{"general"}',1994672071);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Giving-Receiving.html','general','「いただく」は何の謙譲語？','["あげる", "もらう", "くれる", "さしあげる"]'::jsonb,1,'いただく=謙譲語 untuk もらう. 先生に説明していただいた=guru berkenan menjelaskan(sangat sopan). 逆: さしあげる=あげるの謙譲語。','medium',NULL,'{"general"}',1282320528);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Giving-Receiving.html','general','「先生に説明してもらう」と「先生に説明していただく」の違いは？','["同じ意味", "もらう=普通、いただく=より敬語的", "いただく=普通", "どちらも使えない"]'::jsonb,1,'もらう=普通のもらう(標準敬語). いただく=より丁寧な謙譲語. 先生・上司相手にはいただくの方が適切。','medium',NULL,'{"general"}',1198868974);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Giving-Receiving.html','general','「友達に本を（　）た」に入るのは？(私→友達)','["くれ", "もらっ", "あげ", "さしあげ"]'::jsonb,2,'私→友達 = あげる. 私が友達に本をあげた=saya memberi buku ke teman. くれる=他者→私, もらう=私が受け取る。','medium',NULL,'{"general"}',1571886194);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conditional.html','grammar','「右に曲がると駅がある」の「と」の用法は？','["仮定", "自動的な結果・事実", "一回の出来事", "アドバイス"]'::jsonb,1,'〜と=otomatis/pasti. 右に曲がる→駅がある は自然な結果. 道案内・事実・メカニズムに使う。×命令・依頼には使えない。','medium',NULL,'{"grammar"}',402044640);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conditional.html','grammar','「着いたら連絡して」でたらを使う理由は？','["習慣を表す", "一回の出来事・その後の行動に適切", "条件一般", "アドバイス"]'::jsonb,1,'たら=setelah kejadian satu kali terjadi. 着いたら連絡して=setelah tiba, hubungi. 依頼・指示にも使える。×と は依頼に使えない。','medium',NULL,'{"grammar"}',1580235363);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conditional.html','grammar','「〜なら」の特徴は？','["自動的な結果", "相手の情報・意図を受けてアドバイス", "過去の習慣", "仮定の後悔"]'::jsonb,1,'なら=merespons info lawan bicara. 「日本語を学ぶ」という情報を受けて「なら〜すべきだ」とアドバイス。文脈依存の表現。','medium',NULL,'{"grammar"}',16253583);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conditional.html','grammar','「もっと勉強すればよかった」の意味は？','["勉強した", "もっと勉強するべきだった(後悔)", "勉強しなくてよかった", "これから勉強する"]'::jsonb,1,'〜ばよかった=seandainya ~ (penyesalan). もっと勉強すればよかった=seandainya belajar lebih banyak. 過去への後悔。','medium',NULL,'{"grammar"}',977236421);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conditional.html','grammar','「雨が降っても行きます」の意味は？','["雨が降ったら行く", "雨が降るかもしれないが関係なく行く", "雨が降らなければ行く", "雨が降ったから行かない"]'::jsonb,1,'〜ても=meskipun ~; walaupun. 雨が降っても行く=tetap pergi meskipun hujan. 逆接条件を表す。','medium',NULL,'{"grammar"}',1279535267);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conditional.html','grammar','「〜と」が使えない場面は？','["道案内", "依頼・命令・意志", "自然現象", "事実"]'::jsonb,1,'〜と は依頼・命令・意志表現と一緒に使えない. ×右に曲がると連絡してください. ✅右に曲がったら連絡してください。','medium',NULL,'{"grammar"}',1775872167);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conjunctions.html','grammar','「その上」の意味は？','["逆接", "さらに〜も(累加)", "つまり", "だから"]'::jsonb,1,'その上=lebih lagi; di atas itu(累加). 雨が降っている。その上、風も強い=Sudah hujan, bahkan anginnya pun kencang.','medium',NULL,'{"grammar"}',1753080129);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conjunctions.html','grammar','「とはいえ」の意味は？','["だから", "〜は認めるが(逆接)", "つまり", "さらに"]'::jsonb,1,'とはいえ=walaupun demikian; meski begitu(逆接). 忙しい。とはいえ休みも必要だ=Memang sibuk. Tapi istirahat juga perlu.','medium',NULL,'{"grammar"}',854314959);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conjunctions.html','grammar','「むしろ」の意味は？','["逆接", "どちらかといえば〜の方(対比・修正)", "つまり", "だから"]'::jsonb,1,'むしろ=justru; lebih tepatnya. 難しいというよりむしろ複雑だ=Bukan sulit, lebih tepatnya rumit. 言い直し・修正の表現。','medium',NULL,'{"grammar"}',813275170);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conjunctions.html','grammar','「したがって」の意味は？','["逆接", "〜の結果として(論理的帰結)", "つまり", "さらに"]'::jsonb,1,'したがって=oleh karena itu; dengan demikian(論理的結果). 証拠がある。したがって有罪だ=Ada bukti. Oleh karena itu bersalah.','medium',NULL,'{"grammar"}',1678179514);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conjunctions.html','grammar','「すなわち」の意味は？','["逆接", "言い換え・定義(yaitu)", "累加", "結果"]'::jsonb,1,'すなわち=yaitu; dengan kata lain(言い換え). 民主主義、すなわち国民が主権を持つ制度=Demokrasi, yaitu sistem dimana rakyat memegang kedaulatan.','medium',NULL,'{"grammar"}',900727135);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Conjunctions.html','grammar','「もっとも」の用法は？','["強い同意", "認めつつ留保・但し書きを加える", "強い否定", "累加"]'::jsonb,1,'もっとも=memang; tapi; namun demikian(留保). 合格した。もっとも、運もよかったが=Lulus sih. Tapi keberuntungan juga berperan.','medium',NULL,'{"grammar"}',1486191535);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Honorific-Deep.html','grammar','「先生がいらっしゃいます」の「いらっしゃる」は何の敬語？','["謙譲語", "尊敬語", "丁寧語", "普通語"]'::jsonb,1,'いらっしゃる=尊敬語 untuk いる/行く/来る. 先生が主語→先生の行動を高める→尊敬語. 謙譲語は自分の行動を低める表現。','medium',NULL,'{"grammar"}',1718646737);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Honorific-Deep.html','grammar','「私が参ります」の「参る」は何の敬語？','["尊敬語", "謙譲語", "丁寧語", "普通語"]'::jsonb,1,'参る(まいる)=謙譲語 untuk 行く/来る. 自分が主語→自分を低める→謙譲語. 先生に対して使う時も自分側に使う。','medium',NULL,'{"grammar"}',1288284766);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Honorific-Deep.html','grammar','「先生が申しました」の間違いは？','["丁寧すぎる", "申す=謙譲語なので先生には使えない", "敬語ではない", "文法的間違い"]'::jsonb,1,'申す(もうす)=謙譲語=自分の言葉に使う. 先生の言葉には尊敬語「おっしゃる」を使う。✅先生がおっしゃいました。','medium',NULL,'{"grammar"}',23633932);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Honorific-Deep.html','grammar','「お客様が参ります」の間違いは？','["文法的間違い", "参る=謙譲語なのでお客様には使えない", "丁寧すぎる", "普通でいい"]'::jsonb,1,'参る=謙譲語=自分側の行動に使う. お客様には尊敬語「いらっしゃいます」を使う。✅お客様がいらっしゃいます。','medium',NULL,'{"grammar"}',1091713380);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Honorific-Deep.html','grammar','「弊社の田中が参ります」で弊社の社員に謙譲語を使う理由は？','["田中さんが偉いから", "ウチ(自分の会社)の人間は外部の人に対して謙譲語で話す", "丁寧だから", "間違い"]'::jsonb,1,'ウチ・ソト文化: 自社(ウチ)の人間は外部(ソト)の人の前では謙譲語で話す。「弊社の山田が参ります」=OK even if 田中さんは上司。','medium',NULL,'{"grammar"}',1813860308);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Honorific-Deep.html','grammar','「ご覧になる」と「拝見する」の違いは？','["同じ", "ご覧になる=尊敬語(相手が見る)、拝見する=謙譲語(自分が見る)", "どちらも謙譲", "どちらも尊敬"]'::jsonb,1,'ご覧になる=尊敬語. 先生がご覧になる=guru(yang dihormati) melihat. 拝見する=謙譲語. 私が拝見する=saya melihat(merendahkan diri).','medium',NULL,'{"grammar"}',917367454);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Izin-Kewajiban.html','grammar','Bagaimana meminta izin ''Bolehkah saya memotret?''','["写真を撮ってはいけませんか", "写真を撮ってもいいですか", "写真を撮らなければなりません", "写真を撮らなくてもいいです"]'::jsonb,1,'写真を撮ってもいいですか。 Pola ～てもいいですか dipakai untuk meminta izin secara sopan. Bentuknya: kata kerja bentuk-て + もいいですか. Kesalahan umum adalah memakai bentuk kamus (撮るてもいい) — harus bentuk-て dulu (撮って).','medium',NULL,'{"grammar"}',1208461193);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Izin-Kewajiban.html','grammar','''ここでタバコを吸ってはいけません'' artinya?','["Boleh merokok di sini", "Tidak boleh merokok di sini", "Harus merokok di sini", "Tidak perlu merokok"]'::jsonb,1,'Artinya ''dilarang merokok di sini''. Pola ～てはいけません menyatakan larangan tegas, sering dipakai pada aturan tempat umum atau instruksi resmi. Ini kebalikan dari ～てもいい (boleh) yang menyatakan izin.','medium',NULL,'{"grammar"}',1625640367);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Izin-Kewajiban.html','grammar','Pola untuk menyatakan KEWAJIBAN (harus):','["～てもいい", "～てはいけない", "～なければならない", "～なくてもいい"]'::jsonb,2,'～なければならない menyatakan kewajiban (harus melakukan). Dibentuk dari bentuk negatif (ない-form) dengan mengganti ない menjadi なければならない. Contoh: 行く → 行かない → 行かなければならない (harus pergi).','medium',NULL,'{"grammar"}',1532552297);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Izin-Kewajiban.html','grammar','''明日は来なくてもいいです'' artinya?','["Besok harus datang", "Besok tidak boleh datang", "Besok tidak perlu datang", "Besok boleh datang"]'::jsonb,2,'Artinya ''besok tidak perlu datang''. Pola ～なくてもいい menyatakan bahwa sesuatu tidak wajib dilakukan. Perhatikan bedanya dengan ～てはいけない (dilarang) — ''tidak perlu'' berbeda dengan ''tidak boleh''.','medium',NULL,'{"grammar"}',1237237427);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Izin-Kewajiban.html','grammar','Bentuk ''harus pergi'' dari 行く adalah?','["行ってもいい", "行ってはいけない", "行かなければならない", "行かなくてもいい"]'::jsonb,2,'行かなければならない. Langkahnya: 行く → bentuk negatif 行かない → buang い → tambah ければならない. Bentuk ini sering muncul di JLPT N4 dan digunakan dalam situasi formal maupun tulisan.','medium',NULL,'{"grammar"}',1753740593);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Izin-Kewajiban.html','grammar','Bentuk kasual dari ～なければならない adalah?','["～なきゃ", "～てもいい", "～ちゃだめ", "～ています"]'::jsonb,0,'Bentuk kasualnya adalah ～なきゃ atau ～ないと, misalnya 行かなきゃ (harus pergi). Bentuk ini sangat umum dalam percakapan sehari-hari, tetapi sebaiknya dihindari dalam situasi formal atau saat berbicara dengan atasan.','medium',NULL,'{"grammar"}',1751971713);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Izin-Kewajiban.html','grammar','Bentuk kasual dari ～てはいけない adalah?','["～なきゃ", "～ちゃだめ", "～てもいい", "～たい"]'::jsonb,1,'Bentuk kasualnya adalah ～ちゃだめ atau ～ちゃいけない, misalnya 食べちゃだめ (jangan dimakan). Bentuk ini terdengar akrab dan sering dipakai orang tua kepada anak atau antar teman dekat.','medium',NULL,'{"grammar"}',1929879152);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Izin-Kewajiban.html','grammar','''急がなくてもいいです'' artinya?','["Harus buru-buru", "Tidak boleh buru-buru", "Tidak perlu buru-buru", "Boleh buru-buru"]'::jsonb,2,'Artinya ''tidak perlu terburu-buru''. Terbentuk dari 急ぐ (terburu-buru) → 急がない → 急がなくてもいい. Ungkapan ini sering dipakai untuk menenangkan lawan bicara agar tidak merasa tertekan oleh waktu.','medium',NULL,'{"grammar"}',325014373);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Izin-Kewajiban.html','grammar','Manakah yang berarti ''boleh makan''?','["食べてもいい", "食べてはいけない", "食べなければならない", "食べなくてもいい"]'::jsonb,0,'食べてもいい berarti ''boleh makan''. Pola ～てもいい menyatakan izin. Perhatikan bentuk-て dari 食べる adalah 食べて, bukan 食べるて — kesalahan pembentukan bentuk-て adalah kesalahan paling umum pemula.','medium',NULL,'{"grammar"}',442806151);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Izin-Kewajiban.html','grammar','Untuk memberi izin, jawaban yang tepat adalah:','["いけません", "はい、いいですよ", "なりません", "だめです"]'::jsonb,1,'はい、いいですよ atau どうぞ dipakai untuk memberikan izin. どうぞ terdengar lebih ramah dan mempersilakan. Jika ingin menolak dengan sopan, biasanya digunakan すみません、ちょっと… tanpa mengatakan ''tidak'' secara langsung.','medium',NULL,'{"grammar"}',165567063);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Keinginan.html','grammar','Bagaimana mengubah 食べます menjadi ''ingin makan''?','["食べない", "食べたい", "食べた", "食べて"]'::jsonb,1,'食べたい. Caranya: buang ます dari bentuk ます, lalu tambahkan たい. Pola ～たい hanya digunakan untuk menyatakan keinginan diri sendiri, bukan keinginan orang lain.','medium',NULL,'{"grammar"}',1398428202);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Keinginan.html','grammar','Untuk ''ingin MEMILIKI benda'', pola yang tepat:','["名詞 + たい", "名詞 + が欲しい", "動詞 + 欲しい", "名詞 + ます"]'::jsonb,1,'Kata benda + が欲しい, misalnya 車が欲しい (ingin punya mobil). Perhatikan partikelnya が, bukan を. Sedangkan ～たい dipakai untuk keinginan melakukan aksi (kata kerja).','medium',NULL,'{"grammar"}',782877139);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Keinginan.html','grammar','''日本に行きたいです'' artinya?','["Saya pergi ke Jepang", "Saya ingin pergi ke Jepang", "Saya tidak ke Jepang", "Saya sudah ke Jepang"]'::jsonb,1,'Artinya ''saya ingin pergi ke Jepang''. Terbentuk dari 行きます + たい = 行きたい. Menambahkan です di akhir membuatnya menjadi bentuk sopan yang cocok untuk percakapan formal.','medium',NULL,'{"grammar"}',2031359181);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Keinginan.html','grammar','Bentuk negatif dari 食べたい adalah?','["食べたくない", "食べない", "食べたback", "食べません"]'::jsonb,0,'食べたくない (tidak ingin makan). Karena ～たい berkonjugasi seperti kata sifat-i, akhiran い berubah menjadi くない untuk bentuk negatif — sama seperti 高い → 高くない.','medium',NULL,'{"grammar"}',1089542532);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Keinginan.html','grammar','Manakah yang BENAR untuk ''ingin mobil baru''?','["新しい車を食べたい", "新しい車が欲しい", "新しい車します", "新しい車たい"]'::jsonb,1,'新しい車が欲しい. Untuk keinginan memiliki benda, gunakan pola ''kata benda + が欲しい''. Kesalahan umum adalah memakai partikel を atau menggunakan ～たい yang seharusnya untuk kata kerja.','medium',NULL,'{"grammar"}',1572876342);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Keinginan.html','grammar','''何が欲しいですか'' artinya?','["Kamu mau melakukan apa?", "Kamu ingin apa? (benda)", "Kamu makan apa?", "Kamu pergi ke mana?"]'::jsonb,1,'Artinya ''kamu ingin (punya) apa?''. 欲しい dipakai untuk menanyakan keinginan memiliki suatu benda. Jika ingin menanyakan aksi yang ingin dilakukan, gunakan 何がしたいですか.','medium',NULL,'{"grammar"}',491977405);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Keinginan.html','grammar','たい dan 欲しい berubah mengikuti pola kata...','["Kerja", "Sifat-i", "Sifat-na", "Benda"]'::jsonb,1,'Keduanya berkonjugasi mengikuti pola kata sifat-i. Contohnya bentuk negatif menjadi ～くない (食べたくない、欲しくない) dan bentuk lampau menjadi ～かった (食べたかった、欲しかった).','medium',NULL,'{"grammar"}',2096438877);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Keinginan.html','grammar','Bentuk lampau ''ingin makan'' (食べたい):','["食べたい", "食べたかった", "食べました", "食べたくない"]'::jsonb,1,'食べたかった (tadinya ingin makan). Karena ～たい berkonjugasi seperti kata sifat-i, bentuk lampaunya mengubah い menjadi かった — sama seperti 高い → 高かった.','medium',NULL,'{"grammar"}',1843127691);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Keinginan.html','grammar','''寿司が食べたいです'' menggunakan partikel が karena...','["Salah, harus を", "Menekankan objek keinginan", "Wajib selalu が", "Menunjukkan tempat"]'::jsonb,1,'Dengan たい, objek boleh を atau が. が menekankan keinginan terhadap objek itu.','medium',NULL,'{"grammar"}',1395389931);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Keinginan.html','grammar','Bagaimana mengatakan ''Saya ingin (punya) waktu''?','["時間を行きたい", "時間が欲しいです", "時間を食べたい", "時間します"]'::jsonb,1,'時間が欲しいです. Karena 時間 (waktu) adalah kata benda, digunakan pola が欲しい, bukan ～たい. Ungkapan ini sering dipakai saat merasa sibuk dan membutuhkan waktu luang.','medium',NULL,'{"grammar"}',1538744666);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Lanjut.html','grammar','「〜ならではの」の意味は？','["〜に限らない", "〜にしかない独自性", "〜のような", "〜に反する"]'::jsonb,1,'ならでは=khas ~; hanya ada pada ~. 日本ならではの文化=budaya yang hanya ada di Jepang. 唯一性の表現。','hard','N1','{"grammar", "n1"}',2133067617);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Lanjut.html','grammar','「〜ずにはおかない」の意味は？','["しなくてもいい", "強い必然で〜せずにはいられない", "したい", "普通にする"]'::jsonb,1,'ずにはおかない=pasti akan ~; tidak bisa tidak ~. 感動させずにはおかない=pasti mengharukan.','hard','N1','{"grammar", "n1"}',1850644507);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Lanjut.html','grammar','「〜をよそに」の意味は？','["〜と一緒に", "〜を無視して・気にせず", "〜のために", "〜に従って"]'::jsonb,1,'をよそに=tidak peduli ~; mengabaikan ~. 心配をよそに=tidak peduli kekhawatiran orang lain.','hard','N1','{"grammar", "n1"}',1949017617);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Lanjut.html','grammar','「〜を皮切りに」の意味は？','["最後に〜した", "〜を最初として始まる", "〜のために", "〜にもかかわらず"]'::jsonb,1,'を皮切りに=dengan ~ sebagai awal. 東京を皮切りに全国でコンサート=mulai dari Tokyo, konser di seluruh negeri.','hard','N1','{"grammar", "n1"}',1212290348);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Lanjut.html','grammar','「〜てやまない」の用法は？','["やめる", "感情が尽きることなく続く", "できない", "しなければならない"]'::jsonb,1,'てやまない=tidak berhenti ~(感情継続). 願ってやまない=terus mendoakan tanpa henti.','hard','N1','{"grammar", "n1"}',281353015);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Lanjut.html','grammar','「〜に越したことはない」の意味は？','["〜は最悪", "〜が一番良い(婉曲的推奨)", "〜は普通", "〜より悪い"]'::jsonb,1,'に越したことはない=tidak ada yang lebih baik dari ~. 健康に越したことはない=tidak ada yang lebih baik dari kesehatan.','hard','N1','{"grammar", "n1"}',334370021);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Lanjut.html','grammar','「〜ばかりに」の用法は？','["〜が原因でよい結果", "その一点だけが原因で悪い結果(後悔)", "〜ばかりやっている", "〜が好き"]'::jsonb,1,'ばかりに=justru gara-gara ~(一点のみ). 余計なことを言ったばかりに=justru gara-gara berkata berlebihan.','hard','N1','{"grammar", "n1"}',1974253669);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Lanjut.html','grammar','「いかんによらず」の意味は？','["〜によって変わる", "〜に関係なく", "〜のせいで", "〜によると"]'::jsonb,1,'いかんによらず=terlepas dari ~. 結果いかんによらず=terlepas dari hasilnya. フォーマルな表現。','hard','N1','{"grammar", "n1"}',1412361328);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Review.html','grammar','「〜にほかならない」の意味は？','["〜ではない", "まさしく〜だ・それ以外の何でもない", "〜かもしれない", "〜だった"]'::jsonb,1,'にほかならない=tidak lain adalah ~; persis ~. 努力の結果にほかならない=tidak lain adalah hasil kerja keras. 強い断言・フォーマル書き言葉。','hard','N1','{"grammar", "n1"}',1799838970);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Review.html','grammar','「〜ずじまい」の意味は？','["した", "結局できなかった・しないままで終わった", "するつもり", "するべき"]'::jsonb,1,'ずじまい=akhirnya tidak ~(後悔). 結局会わずじまいになった=akhirnya tidak jadi bertemu. 「〜ないまま終わった」の後悔ニュアンス。','hard','N1','{"grammar", "n1"}',706868545);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Review.html','grammar','「〜ともなると」の意味は？','["〜になる前", "〜という地位・状況になれば当然の結果がある", "〜と一緒に", "〜だから"]'::jsonb,1,'ともなると=kalau sudah menjadi ~. 部長ともなると責任も重い=kalau sudah jadi manajer, tanggung jawabnya berat. 地位・役割の上昇に伴う必然。','hard','N1','{"grammar", "n1"}',1538641492);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N1-Review.html','grammar','「〜をよそに」と「〜にもかかわらず」の違いは？','["同じ", "をよそに=無視・無関心のニュアンス、にもかかわらず=逆接のみ", "どちらも同じ", "どちらも無関心"]'::jsonb,1,'をよそに=tidak peduli ~(無視・軽視). にもかかわらず=meskipun ~(逆接). 周囲をよそに=mengabaikan sekitar(積極的無視). より強い無関心ニュアンスがをよそに。','hard','N1','{"grammar", "n1"}',1260899225);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Advanced.html','grammar','「〜を余儀なくされる」の意味は？','["自分で選ぶ", "外部要因で強制的に〜させられる", "したくてする", "自由に決める"]'::jsonb,1,'余儀なくされる=terpaksa ~(faktor luar). 台風で中止を余儀なくされた=akibat topan, terpaksa dibatalkan。','hard','N2','{"grammar", "n2"}',1610249186);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Advanced.html','grammar','「〜もさることながら」の意味は？','["〜は関係ない", "〜はもちろん、さらに〜も(累加強調)", "〜だけが大切", "〜を除いて"]'::jsonb,1,'もさることながら=tidak hanya ~. 技術もさることながら経験も=tidak hanya skill, pengalaman juga penting.','hard','N2','{"grammar", "n2"}',523087761);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Advanced.html','grammar','「〜ずにはいられない」の意味は？','["しない", "感情を抑えられず〜してしまう", "する予定", "しなければならない"]'::jsonb,1,'ずにはいられない=tidak bisa tidak ~; tidak tahan. 笑わずにはいられない=tidak bisa tidak tertawa.','hard','N2','{"grammar", "n2"}',342916579);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Advanced.html','grammar','「〜に即して」の意味は？','["〜に反して", "実際の事実・状況に沿って", "〜の代わりに", "〜のために"]'::jsonb,1,'に即して=berdasarkan kenyataan; sesuai dengan. 事実に即して判断=menilai berdasarkan fakta.','hard','N2','{"grammar", "n2"}',1219962713);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Advanced.html','grammar','「〜をめぐって」の意味は？','["〜のまわりを回って", "〜を中心に議論・対立が起きる", "〜のために", "〜を決める"]'::jsonb,1,'をめぐって=seputar ~; mengenai ~(sering kontroversial). その問題をめぐって議論=berdebat seputar masalah itu.','hard','N2','{"grammar", "n2"}',1573762922);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Advanced.html','grammar','「〜と相まって」の意味は？','["〜だけで", "複数の要素が組み合わさって相乗効果", "〜に反して", "〜の代わりに"]'::jsonb,1,'と相まって=berpadu dengan ~. 努力と才能と相まって成功=sukses berkat perpaduan usaha dan bakat.','hard','N2','{"grammar", "n2"}',1851429419);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Lanjut.html','grammar','「〜にもかかわらず」の意味は？','["〜だから", "〜にもかかわらず=meskipun(逆接)", "〜のために", "〜によって"]'::jsonb,1,'にもかかわらず=meskipun ~; walaupun ~. 試合は雨にもかかわらず続いた=pertandingan berlanjut meskipun hujan。','hard','N2','{"grammar", "n2"}',788091644);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Lanjut.html','grammar','「〜末に」はどんな状況？','["すぐに", "長いプロセスの後の結果", "理由", "逆接"]'::jsonb,1,'〜末に(すえに)=setelah panjang ~. 議論の末に=setelah panjang diskusi. 長期間・努力・苦難の後の結果を示す。','hard','N2','{"grammar", "n2"}',327136218);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Lanjut.html','grammar','「〜かねる」の意味は？','["できる", "難しくて・気が引けてできない", "したい", "わからない"]'::jsonb,1,'かねる=tidak bisa ~(心理的に難しい). お受けしかねます=tidak bisa menerima. 丁寧な断り。否定的な可能。','hard','N2','{"grammar", "n2"}',2015488449);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Lanjut.html','grammar','「〜をきっかけに」の意味は？','["〜を理由に批判", "〜が出発点・転換点となって", "〜の結果として", "〜にもかかわらず"]'::jsonb,1,'をきっかけに=dengan ~ sebagai pemicu/awal mula. 失敗をきっかけに変わった=mulai berubah dengan kegagalan sebagai pemicu.','hard','N2','{"grammar", "n2"}',1777096713);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Lanjut.html','grammar','「〜とともに」の主な意味は？','["逆接", "同時変化・一緒に", "理由", "対比"]'::jsonb,1,'とともに=bersamaan dengan ~; seiring ~. 時代の変化とともに=seiring perubahan zaman. 変化の同時性を示す。','hard','N2','{"grammar", "n2"}',751044839);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Lanjut.html','grammar','「〜次第で」はどんな意味？','["〜した後で", "〜によって結果が変わる", "〜のために", "〜にもかかわらず"]'::jsonb,1,'次第で=tergantung pada ~. 努力次第で=tergantung usaha. 結果が条件によって変わることを示す。','hard','N2','{"grammar", "n2"}',479544999);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Lanjut.html','grammar','「〜ものの」の用法は？','["理由", "〜は認めるがしかし(逆接)", "強調", "並列"]'::jsonb,1,'ものの=walaupun ~; memang benar ~ tapi. 努力したものの結果が出なかった=sudah berusaha tapi tidak ada hasilnya。','hard','N2','{"grammar", "n2"}',1176612050);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Lanjut.html','grammar','「〜かたわら」の意味は？','["〜の後で", "〜と並行して・〜しながら", "〜のために", "〜に反して"]'::jsonb,1,'かたわら=di samping ~; sambil ~(並行). 仕事のかたわら勉強する=belajar sambil bekerja. 二つの活動が同時進行。','hard','N2','{"grammar", "n2"}',1401369948);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Review.html','grammar','「にもかかわらず」の意味は？','["だから", "〜にもかかわらず = meskipun, walaupun (kontras dengan kondisi sebelumnya)", "〜のために", "〜として"]'::jsonb,1,'にもかかわらず=meskipun; walaupun. 雨にもかかわらず、試合は行われた=Meski hujan, pertandingan tetap berlangsung. Menyatakan kontras kuat antara kondisi dan hasil.','hard','N2','{"grammar", "n2"}',106820588);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Review.html','grammar','「わけがない」と「わけにはいかない」の違いは？','["同じ", "わけがない=tidak mungkin(可能性の否定)、わけにはいかない=tidak bisa karena alasan sosial/moral(できない理由)", "どちらも同じ意味", "わけがないの方が丁寧"]'::jsonb,1,'わけがない=tidak mungkin secara logis(あの人が嘘をつくわけがない). わけにはいかない=tidak bisa melakukan karena alasan sosial/tanggung jawab(約束を破るわけにはいかない)。用途が全く違う。','hard','N2','{"grammar", "n2"}',717265782);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Review.html','grammar','「べきだ」の用法として正しいのは？','["過去の後悔のみ", "V辞書形+べきだ = seharusnya ~; menyatakan kewajiban/nasihat kuat", "疑問文のみ", "否定形は存在しない"]'::jsonb,1,'べきだ=seharusnya ~; sebaiknya ~. もっと勉強するべきだ=Seharusnya lebih giat belajar. Menyatakan kewajiban moral/nasihat kuat berdasarkan pendapat pembicara. Bentuk negatif: べきではない。','hard','N2','{"grammar", "n2"}',647623019);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Review.html','grammar','「に基づいて」の意味は？','["に関して(mengenai)", "berdasarkan ~; berlandaskan ~", "にとって(bagi)", "について(tentang)"]'::jsonb,1,'に基づいて=berdasarkan ~; berlandaskan ~. 事実に基づいて、報告する=Melaporkan berdasarkan fakta. Sering dipakai untuk laporan formal, penelitian, atau keputusan yang berlandaskan sumber/data tertentu.','hard','N2','{"grammar", "n2"}',1566467108);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Review.html','grammar','「つつ」の文法的用法は？','["原因を表す", "V(stem)+つつ = sambil ~ (dengan nuansa kontras/menyesal, mirip ながら tapi lebih formal)", "結果を表す", "命令形"]'::jsonb,1,'つつ=sambil ~; sementara ~ (kontras). 迷いつつも、決断した=Meski ragu, tetap memutuskan. Mirip ながら tapi lebih formal, sering dipakai dengan nuansa kontras batin (melakukan sesuatu meski ada keraguan).','hard','N2','{"grammar", "n2"}',1397570946);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N2-Review.html','grammar','「にすぎない」の意味は？','["lebih dari ~", "hanya ~; tidak lebih dari ~ (meremehkan/membatasi)", "sangat ~", "tidak pernah ~"]'::jsonb,1,'にすぎない=hanya ~; tidak lebih dari ~. これは一例にすぎない=Ini hanya satu contoh saja. Dipakai untuk membatasi/meremehkan sesuatu, menegaskan bahwa itu tidak lebih besar/penting dari yang disebutkan.','hard','N2','{"grammar", "n2"}',1482799086);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Lanjut.html','grammar','「〜たとえ〜ても」の意味は？','["〜だから", "たとえどんな状況でも〜", "〜の時", "普通なら"]'::jsonb,1,'たとえ〜ても=seandainya ~; meskipun ~. たとえ失敗しても諦めない=seandainya gagal pun tidak menyerah.','medium','N3','{"grammar", "n3"}',1802566204);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Lanjut.html','grammar','「〜ばよかった」の感情は？','["喜び", "後悔(そうすればよかった)", "怒り", "感謝"]'::jsonb,1,'ばよかった=seandainya ~ (penyesalan). もっと勉強すればよかった=seandainya belajar lebih banyak.','medium','N3','{"grammar", "n3"}',266725362);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Lanjut.html','grammar','「〜だけでなく〜も」の意味は？','["〜だけ", "〜のほかに〜も(追加)", "〜ではなく", "〜より"]'::jsonb,1,'だけでなく〜も=tidak hanya ~, tapi ~ juga. 彼は頭がいいだけでなく、優しくもある=tidak hanya pintar, tapi juga baik hati.','medium','N3','{"grammar", "n3"}',1762990101);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Lanjut.html','grammar','「〜上に」の意味は？','["〜の前に", "〜に加えて・さらに(累加)", "〜の後に", "〜と逆に"]'::jsonb,1,'〜上に=ditambah lagi ~; tidak hanya ~, bahkan ~. 彼は忙しい上に体調も悪い=tidak hanya sibuk, kondisi badannya juga buruk.','medium','N3','{"grammar", "n3"}',2129890976);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Lanjut.html','grammar','「〜わけにはいかない」の意味は？','["してもいい", "してはいけない・できない(社会的・道義的に)", "したい", "わからない"]'::jsonb,1,'わけにはいかない=tidak bisa ~ (karena kewajiban moral/sosial). 約束を破るわけにはいかない=tidak bisa mengingkari janji.','medium','N3','{"grammar", "n3"}',1743712267);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Lanjut.html','grammar','「〜かのように」の用法は？','["事実", "まるで〜みたいに(比喩・仮定)", "理由", "逆接"]'::jsonb,1,'かのように=seolah-olah ~; seperti. まるで夢かのように=seolah-olah seperti mimpi. 比喩的な表現。','medium','N3','{"grammar", "n3"}',688034596);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Lanjut.html','grammar','「〜においては」と「〜では」の違いは？','["同じ", "においては=より格式・フォーマル", "では=より格式", "どちらも同じ文脈"]'::jsonb,1,'においては=より書き言葉的・フォーマル. 現代社会においては=dalam masyarakat modern (formal). では=より日常的. ビジネス文書はにおいてが多い。','medium','N3','{"grammar", "n3"}',400069176);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Review.html','grammar','「〜ておく」の意味は？','["してしまった", "後のために前もって〜する", "してみる", "してくる"]'::jsonb,1,'ておく=melakukan sebelumnya untuk persiapan. 予約しておく=memesan terlebih dahulu. 前もって行動するニュアンス。','medium','N3','{"grammar", "n3"}',1067012526);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Review.html','grammar','「〜ようになる」と「〜ようにする」の違いは？','["同じ", "ようになる=変化の結果、ようにする=意図的な努力", "どちらも意図的", "どちらも結果"]'::jsonb,1,'ようになる=menjadi bisa/terjadi perubahan(自然な変化). ようにする=berusaha untuk ~(意図的努力). 話せるようになった vs 話せるようにする。','medium','N3','{"grammar", "n3"}',2145125808);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Review.html','grammar','「〜はずだ」の意味は？','["驚き", "論理的に〜であるべきだ・当然", "希望", "過去"]'::jsonb,1,'はずだ=seharusnya ~; mestinya. 根拠に基づく推測. 彼は来るはずだ=dia seharusnya datang(berdasar alasan logis). 驚きにも使う: はずがない。','medium','N3','{"grammar", "n3"}',1881961386);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Review.html','grammar','「〜わけではない」の意味は？','["そうだ", "〜という意味/わけではない(部分否定)", "絶対違う", "同意する"]'::jsonb,1,'わけではない=bukan berarti ~(部分否定). 全部嫌いなわけではない=bukan berarti membenci semuanya. 完全否定ではなく部分否定。','medium','N3','{"grammar", "n3"}',368792307);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Review.html','grammar','「〜ば〜ほど」の用法は？','["逆接", "程度が増すにつれて結果も増す", "条件", "時間"]'::jsonb,1,'ば〜ほど=semakin ~, semakin ~. 練習すればするほど上手になる=semakin banyak berlatih, semakin mahir. 比例関係を表す。','medium','N3','{"grammar", "n3"}',1745684630);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N3-Review.html','grammar','「〜ことにする」と「〜ことになる」の違いは？','["同じ", "ことにする=自分の決定、ことになる=外部・状況による決定", "どちらも外部", "どちらも自分"]'::jsonb,1,'ことにする=keputusan sendiri. ことになる=diputuskan(dari luar/situasi). 転職することにした(自分)vs することになった(情況)。','medium','N3','{"grammar", "n3"}',398321334);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N4-Review.html','grammar','「〜てあげる」の意味は？','["もらう", "自分が相手のために〜してやる(与える)", "される", "頼む"]'::jsonb,1,'てあげる=melakukan sesuatu untuk orang lain. 手伝ってあげた=saya membantu (untuk dia). てもらう=menerima kebaikan. てくれる=orang lain melakukan untuk saya。','easy','N4','{"grammar", "n4"}',1958081320);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N4-Review.html','grammar','「〜させる」(使役)の意味は？','["される(受身)", "誰かに〜をするよう仕向ける(使役)", "自分がする", "禁止"]'::jsonb,1,'させる=kausatif; menyuruh/membiarkan. 子供に野菜を食べさせる=menyuruh anak makan sayuran. させてもらう=meminta izin untuk ~。','easy','N4','{"grammar", "n4"}',1050627757);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N4-Review.html','grammar','「〜れる/られる(受身)」の意味は？','["自分がする", "他の人に〜される", "させる", "できる"]'::jsonb,1,'受身=pasif. 先生に褒められた=dipuji oleh guru. が/に+受身. 迷惑の受身もある: 雨に降られた=kehujanan(tidak menyenangkan)。','easy','N4','{"grammar", "n4"}',143171137);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N4-Review.html','grammar','「〜たことがある」の意味は？','["これからする", "過去に〜した経験がある", "したい", "しなかった"]'::jsonb,1,'たことがある=pernah ~(pengalaman masa lalu). 富士山に登ったことがある=pernah mendaki Fuji. 一度もない=belum pernah sama sekali。','easy','N4','{"grammar", "n4"}',733292486);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N4-Review.html','grammar','「〜のに」の意味と気持ちは？','["理由", "期待に反した結果への残念・驚き", "目的", "条件"]'::jsonb,1,'のに=padahal; walaupun(失望・不満の気持ち). 頑張ったのに失敗した=padahal sudah berusaha tapi gagal. ため・ように(目的)との区別が重要。','easy','N4','{"grammar", "n4"}',1111040951);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N4-Review.html','grammar','「〜ために」と「〜ように」の違いは？','["同じ", "ために=意志的目的(動詞辞書形)、ように=自然な変化や無意志動詞の目的", "どちらも同じ", "ために=否定"]'::jsonb,1,'ために=tujuan intentional. 合格するために勉強する. ように=tujuan/agar bisa. 合格できるように勉強する(可能形+ように)。自分の意志がない目標にはように。','easy','N4','{"grammar", "n4"}',263481966);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N5-Review.html','grammar','「を」はどんな時に使う？','["存在場所", "動詞の直接目的語(〜を食べる)", "手段・方法", "時間"]'::jsonb,1,'を=objek langsung verba transitif. ご飯を食べる=makan nasi. 映画を見る=nonton film. を は他動詞とセットで使う。','easy','N5','{"grammar", "n5"}',749920807);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N5-Review.html','grammar','「に」と「で」の場所の違いは？','["同じ", "に=存在場所(いる/ある)、で=行動が行われる場所", "に=行動、で=存在", "どちらも行動"]'::jsonb,1,'机にある(存在:に) vs 図書館で勉強する(行動:で). に=where something IS / で=where action HAPPENS. これは非常に重要な区別!','easy','N5','{"grammar", "n5"}',1802088578);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N5-Review.html','grammar','「〜てもいい」の意味は？','["〜してはいけない", "〜することが許可されている(許可)", "〜したい", "〜しなければならない"]'::jsonb,1,'〜てもいい=diizinkan; boleh. 食べてもいいですか？=Boleh makan? 返事: いいですよ(boleh) / いけません(tidak boleh)。','easy','N5','{"grammar", "n5"}',7623433);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N5-Review.html','grammar','「〜たい」の使い方で正しいのは？','["他人の希望に使う", "自分の希望を言う時に使う(第一人称)", "命令に使う", "事実を述べる"]'::jsonb,1,'たい=ingin ~(自分の願望). 私は食べたい=Saya ingin makan. 他人の希望: 〜たがっている/〜たそうだ を使う。','easy','N5','{"grammar", "n5"}',2124432719);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-N5-Review.html','grammar','「は」と「が」の基本的な違いは？','["同じ", "は=既知の話題、が=新情報・識別", "は=質問、が=答え", "どちらも質問"]'::jsonb,1,'は=topik(既知/文脈で分かっている). が=新情報・識別. 誰が来た？→田中さんが来た. 話題として田中さんは〜と言う場合はは。','easy','N5','{"grammar", "n5"}',782486013);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Nagara.html','grammar','Bagaimana membentuk ～ながら dari 食べる?','["食べるながら", "食べながら", "食べてながら", "食べたながら"]'::jsonb,1,'食べながら. Caranya: ubah ke bentuk ます (食べます), buang ます, lalu tambahkan ながら. Pola ini menyatakan dua aksi yang dilakukan bersamaan oleh orang yang sama.','medium',NULL,'{"grammar"}',1072105642);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Nagara.html','grammar','Aturan penting ～ながら adalah...','["Subjek kedua aksi harus SAMA", "Subjek boleh berbeda", "Hanya untuk kata sifat", "Harus bentuk lampau"]'::jsonb,0,'Kedua aksi harus dilakukan oleh subjek yang sama. Kalimat seperti ''弟が音楽を聞きながら私が勉強します'' salah karena subjeknya berbeda. Untuk subjek berbeda, gunakan pola lain seperti ～ている間に.','medium',NULL,'{"grammar"}',602387755);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Nagara.html','grammar','Dalam "音楽を聞きながら勉強します", aksi UTAMA-nya adalah?','["Mendengarkan musik", "Belajar", "Keduanya sama", "Tidak ada"]'::jsonb,1,'勉強します (belajar) adalah aksi utama karena berada di akhir kalimat. Dalam pola ～ながら, aksi sebelum ながら adalah aksi sampingan, sedangkan aksi di akhir kalimat merupakan fokus utamanya.','medium',NULL,'{"grammar"}',824872756);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Nagara.html','grammar','～ながら bisa dipakai pada...','["Kata kerja saja", "Kata sifat saja", "Kata benda saja", "Semua jenis kata"]'::jsonb,0,'～ながら hanya bisa dipakai pada kata kerja, bukan kata benda atau kata sifat. Kata kerja tersebut juga harus berupa aksi yang bisa berlangsung dalam durasi tertentu, bukan aksi sesaat.','medium',NULL,'{"grammar"}',1674336082);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Nagara.html','grammar','Manakah kalimat yang BENAR?','["妹が歌いながら、私は勉強します", "音楽を聞きながら勉強します", "高いながら買います", "学生ながら勉強します"]'::jsonb,1,'Kalimat yang benar harus memenuhi tiga syarat: subjeknya satu, menggunakan kata kerja (bukan kata benda/sifat), dan kedua aksi berlangsung bersamaan. Pelanggaran salah satu syarat membuat kalimat menjadi tidak alami.','medium',NULL,'{"grammar"}',406513859);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Nagara.html','grammar','"テレビを見ながらご飯を食べます" artinya?','["Menonton TV setelah makan", "Makan sambil menonton TV", "Menonton TV sebelum makan", "Tidak menonton sambil makan"]'::jsonb,1,'Artinya ''makan sambil menonton TV''. Aksi utamanya adalah 食べます (makan) karena berada di akhir, sedangkan 見ながら (sambil menonton) adalah aksi sampingan yang menyertainya.','medium',NULL,'{"grammar"}',1687614033);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Nagara.html','grammar','Bentuk ながら dari 歩く adalah?','["歩くながら", "歩きながら", "歩いてながら", "歩かながら"]'::jsonb,1,'歩きながら. Prosesnya: 歩く → 歩きます → buang ます → 歩き + ながら. Contoh pemakaian: 歩きながら話す (berbicara sambil berjalan).','medium',NULL,'{"grammar"}',2129015236);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Nagara.html','grammar','"歩きながらスマホを見ないでください" artinya?','["Lihat HP sambil jalan", "Jangan lihat HP sambil berjalan", "Berjalanlah sambil lihat HP", "Jangan berjalan"]'::jsonb,1,'Artinya ''jangan melihat ponsel sambil berjalan''. 見ないでください adalah bentuk larangan sopan. Kalimat ini sering ditemui sebagai peringatan di stasiun atau tempat umum di Jepang.','medium',NULL,'{"grammar"}',1296805263);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Nagara.html','grammar','Jika ingin menekankan "mendengarkan musik" sebagai aksi utama:','["音楽を聞きながら勉強します", "勉強しながら音楽を聞きます", "音楽と勉強します", "勉強と音楽を聞きます"]'::jsonb,1,'勉強しながら音楽を聞きます. Karena aksi utama selalu diletakkan di akhir kalimat, menukar posisi kedua kata kerja akan mengubah fokus makna kalimat tersebut.','medium',NULL,'{"grammar"}',260237720);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Nagara.html','grammar','Bentuk ながら dari 見る adalah?','["見るながら", "見ながら", "見てながら", "見らながら"]'::jsonb,1,'見ながら. Prosesnya: 見る → 見ます → buang ます → 見 + ながら. Contoh: テレビを見ながら (sambil menonton TV).','medium',NULL,'{"grammar"}',961556206);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Perbandingan.html','grammar','''車は自転車___速いです'' (Mobil lebih cepat dari sepeda). Isi yang tepat:','["より", "ほど", "から", "まで"]'::jsonb,0,'より (yori) = daripada, untuk perbandingan positif. AはBより速い = A lebih cepat dari B.','medium',NULL,'{"grammar"}',1173056157);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Perbandingan.html','grammar','Apa arti 一番 (ichiban)?','["Pertama kali", "Paling / nomor satu", "Sebentar", "Bersama"]'::jsonb,1,'一番 (ichiban) berarti nomor satu/paling, dipakai untuk menyatakan superlatif (tingkat paling tinggi) dalam suatu kelompok. Contoh: これが一番好きです (ini yang paling saya suka).','medium',NULL,'{"grammar"}',1171705282);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Perbandingan.html','grammar','''富士山は日本___一番高い山です''. Partikel yang tepat:','["で", "に", "を", "が"]'::jsonb,0,'で menunjukkan lingkup/ruang lingkup perbandingan. 日本で一番高い山 berarti ''gunung tertinggi di Jepang'', menunjukkan bahwa perbandingan dilakukan dalam cakupan negara Jepang.','medium',NULL,'{"grammar"}',20185774);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Perbandingan.html','grammar','''今日は昨日___寒くないです'' (tidak sedingin kemarin). Isi:','["より", "ほど", "から", "でも"]'::jsonb,1,'ほど (hodo) dalam kalimat negatif menyatakan ''tidak se-...''. Pola AはBほど〜ない berarti A tidak se-~ seperti B. Kalimat ini berarti ''hari ini tidak sedingin kemarin''.','medium',NULL,'{"grammar"}',1560366965);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Perbandingan.html','grammar','Untuk bertanya ''mana yang lebih kamu suka?'' antara 2 hal:','["何が好きですか", "どちらが好きですか", "いつ好きですか", "どこが好きですか"]'::jsonb,1,'どちら (dochira) = yang mana (dari dua). どちらが好きですか = mana yang lebih disuka.','medium',NULL,'{"grammar"}',1460923990);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Perbandingan.html','grammar','より dipakai dalam kalimat...','["Negatif saja", "Positif (perbandingan lebih)", "Pertanyaan saja", "Perintah"]'::jsonb,1,'より dipakai untuk perbandingan positif, menyatakan bahwa satu hal melebihi hal lain dalam suatu aspek. Pola dasarnya: A は B より 〜です, dengan B sebagai patokan perbandingan.','medium',NULL,'{"grammar"}',403338957);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Perbandingan.html','grammar','''私___弟より背が高い'' (menekankan ''saya''). Isi:','["のほうが", "ほど", "でも", "しか"]'::jsonb,0,'～のほうが menekankan subjek yang lebih unggul dalam perbandingan. 私のほうが弟より背が高い berarti ''sayalah yang lebih tinggi dibanding adik laki-laki'', dengan penekanan pada pihak yang dibandingkan.','medium',NULL,'{"grammar"}',1059247219);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Perbandingan.html','grammar','''果物の中で何が一番好きですか'' artinya?','["Apakah kamu suka buah?", "Dari semua buah, mana yang paling disuka?", "Berapa buah yang kamu punya?", "Kapan makan buah?"]'::jsonb,1,'Kalimat ini berarti ''dari antara buah-buahan, mana yang paling kamu suka?''. Pola 〜の中で何が一番〜 dipakai untuk bertanya pilihan terbaik dari suatu kelompok/kategori.','medium',NULL,'{"grammar"}',1431767549);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Perbandingan.html','grammar','Manakah pola untuk menyatakan ''paling''?','["より", "ほど", "一番", "どちら"]'::jsonb,2,'一番 (ichiban) dipakai untuk menyatakan superlatif/paling. Berbeda dengan より yang membandingkan dua hal, 一番 menunjukkan posisi teratas dalam suatu kelompok atau kategori.','medium',NULL,'{"grammar"}',99208273);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Perbandingan.html','grammar','''大阪は東京ほど大きくないです'' artinya?','["Osaka lebih besar dari Tokyo", "Osaka tidak sebesar Tokyo", "Osaka sama besar dengan Tokyo", "Tokyo tidak sebesar Osaka"]'::jsonb,1,'Kalimat ini berarti ''Osaka tidak sebesar Tokyo''. Pola AはBほど〜ない menyatakan bahwa A berada di bawah B dalam suatu aspek, tanpa menyebutkan secara langsung seberapa jauh perbedaannya.','medium',NULL,'{"grammar"}',54456953);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sentence-Patterns.html','grammar','「〜ざるを得ない」の意味は？','["〜しない", "外部要因でしたくないけどしなければならない", "〜したい", "〜するかもしれない"]'::jsonb,1,'ざるを得ない=terpaksa harus ~. 状況上、同意せざるを得ない=karena situasi, terpaksa harus setuju. 否定形+を得ない の構造。','medium',NULL,'{"grammar"}',869751322);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sentence-Patterns.html','grammar','「〜かねない」の意味は？','["絶対しない", "悪いことが起こる可能性がある", "必ずする", "したい"]'::jsonb,1,'かねない=bisa jadi ~(negatif). このままでは失敗しかねない=kalau begini terus, bisa-bisa gagal. ネガティブな可能性を示す。','medium',NULL,'{"grammar"}',1646133707);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sentence-Patterns.html','grammar','「〜に過ぎない」の意味は？','["〜以上だ", "それだけで・たった〜だ(過小)", "大切な〜だ", "〜かもしれない"]'::jsonb,1,'に過ぎない=tidak lebih dari ~; hanya. これは意見に過ぎない=ini hanya pendapat. 価値・重要性を下げる表現。','medium',NULL,'{"grammar"}',810640423);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sentence-Patterns.html','grammar','「〜ならまだしも」の意味は？','["〜は問題ない", "〜なら許せるが(実際は許せない状況)", "〜はよい", "〜だったら"]'::jsonb,1,'ならまだしも=kalau ~ masih bisa diterima, tapi(実際はそうでない). 一度ならまだしも三度は=sekali masih oke, tapi tiga kali sudah keterlaluan。','medium',NULL,'{"grammar"}',469273487);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sonkeigo-Kenjougo.html','grammar','Sonkeigo dipakai untuk tindakan siapa?','["Diri sendiri", "Orang lain (yang dihormati)", "Keduanya", "Benda"]'::jsonb,1,'尊敬語 (sonkeigo) dipakai untuk tindakan ORANG LAIN, khususnya atasan atau pelanggan, dengan cara meninggikan mereka. Menggunakan sonkeigo untuk tindakan diri sendiri adalah kesalahan yang terdengar sombong.','medium',NULL,'{"grammar"}',278003202);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sonkeigo-Kenjougo.html','grammar','Kenjougo dipakai untuk tindakan siapa?','["Diri sendiri", "Orang lain", "Atasan", "Pelanggan"]'::jsonb,0,'謙譲語 (kenjougo) dipakai untuk tindakan DIRI SENDIRI dengan cara merendahkan diri, sehingga secara tidak langsung meninggikan lawan bicara. Ini adalah pasangan dari sonkeigo dalam sistem keigo bahasa Jepang.','medium',NULL,'{"grammar"}',182329513);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sonkeigo-Kenjougo.html','grammar','Sonkeigo dari 食べる adalah?','["いただく", "召し上がる", "食べられる", "お食べする"]'::jsonb,1,'召し上がる (meshiagaru) adalah sonkeigo untuk makan dan minum. Contoh: どうぞ召し上がってください (silakan dinikmati). Bentuk ini sering dipakai di restoran atau saat menjamu tamu.','medium',NULL,'{"grammar"}',1695741432);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sonkeigo-Kenjougo.html','grammar','Kenjougo dari 行く adalah?','["いらっしゃる", "参る", "行かれる", "お行きになる"]'::jsonb,1,'参る (mairu) atau 伺う (ukagau) adalah kenjougo untuk pergi. 伺う terdengar lebih sopan dan sering dipakai saat akan mengunjungi tempat atasan atau klien.','medium',NULL,'{"grammar"}',1319806766);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sonkeigo-Kenjougo.html','grammar','"社長がいらっしゃいます" — いらっしゃる di sini adalah?','["Kenjougo", "Sonkeigo", "Bahasa biasa", "Bahasa kasar"]'::jsonb,1,'いらっしゃる adalah sonkeigo yang meninggikan direktur (orang lain). Kata ini serbaguna karena bisa berarti いる (ada)、行く (pergi)、maupun 来る (datang) tergantung konteksnya.','medium',NULL,'{"grammar"}',1698043502);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sonkeigo-Kenjougo.html','grammar','Kesalahan FATAL dalam keigo adalah?','["Terlalu sopan", "Memakai sonkeigo untuk diri sendiri", "Memakai kenjougo untuk diri sendiri", "Memakai bentuk ます"]'::jsonb,1,'Menggunakan sonkeigo untuk tindakan diri sendiri, karena itu berarti meninggikan diri sendiri dan terdengar sangat sombong. Contoh salah: 私が召し上がります — seharusnya 私がいただきます.','medium',NULL,'{"grammar"}',1332786416);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sonkeigo-Kenjougo.html','grammar','Sonkeigo dari 言う adalah?','["申す", "おっしゃる", "言われる", "お言いする"]'::jsonb,1,'おっしゃる (ossharu) adalah sonkeigo untuk berbicara atau berkata. Contoh: 先生がおっしゃいました (Bapak/Ibu guru berkata). Kenjougo-nya adalah 申す atau 申し上げる.','medium',NULL,'{"grammar"}',1282914203);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sonkeigo-Kenjougo.html','grammar','Pola "お + ます形 + する" adalah?','["Sonkeigo", "Kenjougo", "Bahasa biasa", "Bentuk pasif"]'::jsonb,1,'Pola お＋ます形＋する adalah kenjougo yang merendahkan diri, misalnya お持ちします (saya yang membawakan). Sedangkan pola sonkeigo-nya adalah お＋ます形＋になる, misalnya お持ちになる.','medium',NULL,'{"grammar"}',294316078);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sonkeigo-Kenjougo.html','grammar','Kenjougo dari 見る adalah?','["ご覧になる", "拝見する", "見られる", "お見になる"]'::jsonb,1,'拝見する (haiken suru) adalah kenjougo untuk melihat. Contoh: 資料を拝見しました (saya sudah melihat dokumennya). Sonkeigo untuk melihat adalah ご覧になる.','medium',NULL,'{"grammar"}',1818173733);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sonkeigo-Kenjougo.html','grammar','"お食事を召し上がりましたか" ditujukan kepada?','["Diri sendiri", "Orang yang dihormati (pasien/tamu)", "Teman akrab", "Anak kecil"]'::jsonb,1,'Kalimat ini ditujukan kepada orang lain yang dihormati, karena 召し上がる adalah sonkeigo. Jika ingin membicarakan diri sendiri, seharusnya digunakan kenjougo: いただきました.','medium',NULL,'{"grammar"}',1289650057);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sugiru.html','grammar','Bagaimana membentuk "makan terlalu banyak" dari 食べる?','["食べるすぎる", "食べすぎる", "食べたすぎる", "食べてすぎる"]'::jsonb,1,'食べすぎる. Caranya: ubah ke bentuk ます (食べます), buang ます, lalu tambahkan すぎる. Pola ini menyatakan sesuatu yang melebihi batas wajar dan umumnya bernuansa negatif.','medium',NULL,'{"grammar"}',752995792);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sugiru.html','grammar','Bagaimana membentuk "terlalu mahal" dari 高い?','["高いすぎる", "高すぎる", "高くすぎる", "高かすぎる"]'::jsonb,1,'高すぎる. Untuk kata sifat-i, buang akhiran い lalu tambahkan すぎる. Ungkapan ini menyiratkan bahwa harganya di luar batas kewajaran, bukan sekadar mahal.','medium',NULL,'{"grammar"}',1081846198);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sugiru.html','grammar','～すぎる memiliki nuansa...','["Positif (pujian)", "Negatif (melewati batas wajar)", "Netral", "Formal"]'::jsonb,1,'～すぎる hampir selalu negatif — menandakan sesuatu melewati batas yang wajar.','medium',NULL,'{"grammar"}',310643806);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sugiru.html','grammar','Apa perbedaan とても高い dan 高すぎる?','["Tidak ada beda", "とても=sangat (netral), すぎる=terlalu (negatif)", "とても lebih negatif", "すぎる lebih sopan"]'::jsonb,1,'とても高い bersifat netral (sangat mahal, tapi mungkin tetap dibeli), sedangkan 高すぎる mengandung nuansa negatif bahwa harganya melewati batas wajar sehingga menjadi masalah. Pemilihan keduanya menunjukkan sikap pembicara.','medium',NULL,'{"grammar"}',907561529);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sugiru.html','grammar','"昨日、飲みすぎました" artinya?','["Kemarin saya sangat suka minum", "Kemarin saya minum terlalu banyak", "Kemarin saya tidak minum", "Kemarin saya ingin minum"]'::jsonb,1,'Artinya ''kemarin saya minum terlalu banyak'', dengan nuansa penyesalan. Pola ～すぎる sering digunakan untuk mengungkapkan bahwa sesuatu dilakukan berlebihan dan berdampak kurang baik.','medium',NULL,'{"grammar"}',1419024834);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sugiru.html','grammar','Bentuk すぎる dari kata sifat-na 静か adalah?','["静かなすぎる", "静かすぎる", "静かいすぎる", "静かにすぎる"]'::jsonb,1,'静かすぎる. Untuk kata sifat-na, すぎる langsung ditempelkan tanpa perlu menghapus apa pun (tidak perlu な). Contoh lain: 便利すぎる (terlalu praktis).','medium',NULL,'{"grammar"}',1668707553);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sugiru.html','grammar','Bentuk すぎる dari いい (bagus) adalah?','["いすぎる", "いいすぎる", "よすぎる", "よいすぎる"]'::jsonb,2,'よすぎる. Kata sifat いい adalah pengecualian karena berkonjugasi dari bentuk asal よい. Aturan yang sama berlaku pada bentuk lain seperti よくない dan よかった.','medium',NULL,'{"grammar"}',856517812);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sugiru.html','grammar','"働きすぎです" — すぎ di sini berfungsi sebagai?','["Kata kerja", "Kata benda", "Kata sifat", "Partikel"]'::jsonb,1,'～すぎ tanpa る berfungsi sebagai kata benda, sehingga 働きすぎ berarti ''kerja berlebihan'' sebagai suatu kondisi. Bentuk ini sering muncul dalam pembahasan sosial seperti 食べすぎ atau 飲みすぎ.','medium',NULL,'{"grammar"}',143172122);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sugiru.html','grammar','Bagaimana mengatakan "jangan makan terlalu banyak"?','["食べすぎます", "食べすぎないで", "食べすぎました", "食べすぎです"]'::jsonb,1,'食べすぎないで. Karena すぎる berkonjugasi sebagai ru-verb, bentuk negatifnya adalah すぎない, lalu ditambah で untuk membentuk larangan yang lembut.','medium',NULL,'{"grammar"}',117465445);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Sugiru.html','grammar','すぎる berkonjugasi seperti kata kerja kelompok...','["1 (u-verb)", "2 (ru-verb)", "3 (tidak beraturan)", "Tidak berkonjugasi"]'::jsonb,1,'すぎる termasuk ru-verb (kata kerja kelompok 2), sehingga konjugasinya menjadi すぎます、すぎました、すぎない. Memahami ini penting agar bisa membentuk kalimat lampau maupun negatif dengan benar.','medium',NULL,'{"grammar"}',166569616);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Teiru.html','grammar','Bagaimana membentuk ～ている dari 食べる?','["食べるている", "食べている", "食べteいる", "食べます"]'::jsonb,1,'食べている. Caranya: ubah ke bentuk て (食べて) lalu tambahkan いる. Pola ini bisa berarti aksi sedang berlangsung, kebiasaan, atau keadaan hasil — tergantung jenis kata kerjanya.','medium',NULL,'{"grammar"}',374081028);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Teiru.html','grammar','''結婚しています'' artinya?','["Sedang menikah (upacara)", "Sudah menikah (statusnya)", "Akan menikah", "Tidak menikah"]'::jsonb,1,'結婚する = kata kerja sesaat. + ている = keadaan hasil: sudah/berstatus menikah.','medium',NULL,'{"grammar"}',1889297378);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Teiru.html','grammar','''今、ご飯を食べています'' termasuk makna...','["Keadaan hasil", "Aksi sedang berlangsung", "Kebiasaan", "Perintah"]'::jsonb,1,'Ini menunjukkan aksi yang sedang berlangsung, ditandai kata 今 (sekarang) dan kata kerja durasi. Pola ～ている memiliki beberapa makna, sehingga kata keterangan waktu membantu menentukan maknanya.','medium',NULL,'{"grammar"}',1165596257);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Teiru.html','grammar','''東京に住んでいます'' artinya?','["Sedang pindah ke Tokyo", "Tinggal (menetap) di Tokyo", "Pernah ke Tokyo", "Akan ke Tokyo"]'::jsonb,1,'Artinya ''tinggal di Tokyo'' sebagai keadaan menetap, bukan ''sedang dalam proses tinggal''. Kata kerja seperti 住む、結婚する、知る menyatakan keadaan hasil ketika digabung dengan ～ている.','medium',NULL,'{"grammar"}',2137212414);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Teiru.html','grammar','''毎朝、ジョギングをしています'' termasuk makna...','["Sedang berlangsung sekarang", "Keadaan hasil", "Kebiasaan/rutinitas", "Larangan"]'::jsonb,2,'Ini menunjukkan kebiasaan atau rutinitas, ditandai kata 毎朝 (setiap pagi). Pola ～ている dengan kata keterangan frekuensi menyatakan aktivitas yang dilakukan berulang secara teratur.','medium',NULL,'{"grammar"}',1097820242);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Teiru.html','grammar','''窓が開いています'' artinya?','["Jendela sedang membuka sendiri", "Jendela dalam keadaan terbuka", "Seseorang sedang membuka jendela", "Jendela akan dibuka"]'::jsonb,1,'Artinya ''jendela dalam keadaan terbuka''. Karena 開く adalah kata kerja sesaat, penambahan ～ている menyatakan keadaan hasil dari aksi tersebut, bukan proses yang sedang berlangsung.','medium',NULL,'{"grammar"}',605352043);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Teiru.html','grammar','Bentuk kasual/sehari-hari dari 食べている adalah?','["食べてる", "食べた", "食べます", "食べません"]'::jsonb,0,'食べてる — huruf い sering dihilangkan dalam percakapan sehari-hari. Bentuk ini sangat umum dalam percakapan santai, tetapi sebaiknya tetap menggunakan bentuk lengkap dalam situasi formal atau tulisan.','medium',NULL,'{"grammar"}',691358527);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Teiru.html','grammar','''知っています'' artinya?','["Sedang berusaha tahu", "Tahu (sudah tahu)", "Tidak tahu", "Ingin tahu"]'::jsonb,1,'Artinya ''(sudah) tahu'', menyatakan keadaan hasil karena 知る adalah kata kerja sesaat. Yang menarik, bentuk negatifnya bukan 知っていません melainkan 知りません — ini pengecualian yang sering diujikan.','medium',NULL,'{"grammar"}',1156576081);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Teiru.html','grammar','Kata kerja mana yang + ている menghasilkan ''sedang berlangsung''?','["結婚する", "知る", "読む", "死ぬ"]'::jsonb,2,'読む (membaca) punya durasi → 読んでいる = sedang membaca. Yang lain kata kerja sesaat.','medium',NULL,'{"grammar"}',1677595958);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Teiru.html','grammar','Bentuk sopan dari ～ている adalah?','["～ています", "～てる", "～てある", "～ておく"]'::jsonb,0,'～ています adalah bentuk sopan (masu-form) dari ～ている. Bentuk ini digunakan dalam percakapan formal, dengan orang yang baru dikenal, atau dalam situasi kerja.','medium',NULL,'{"grammar"}',644987093);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Tsumori.html','grammar','Bagaimana membentuk "berniat pergi" dari 行く?','["行きつもり", "行くつもりです", "行ってつもり", "行きたいつもり"]'::jsonb,1,'行くつもりです. Pola: kata kerja bentuk kamus + つもりです. つもり menyatakan niat yang sudah dipikirkan matang-matang, bukan sekadar keinginan sesaat.','medium',NULL,'{"grammar"}',949860465);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Tsumori.html','grammar','Bentuk NEGATIF "berniat tidak pergi" adalah?','["行くつもりじゃない", "行かないつもりです", "行きませんつもり", "行くつもりません"]'::jsonb,1,'行かないつもりです. Untuk menyatakan niat negatif, gunakan bentuk ない dari kata kerja diikuti つもり. Pola ini menunjukkan keputusan untuk TIDAK melakukan sesuatu, bukan sekadar ketidakpastian.','medium',NULL,'{"grammar"}',702521708);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Tsumori.html','grammar','Urutan tingkat KEPASTIAN dari rendah ke tinggi:','["予定 < つもり < たい", "たい < つもり < 予定", "つもり < たい < 予定", "semuanya sama"]'::jsonb,1,'たい (ingin) < つもり (niat) < 予定 (rencana tetap). たい hanya menyatakan keinginan tanpa kepastian, つもり menunjukkan niat yang sudah dipikirkan, sedangkan 予定 menyatakan rencana yang sudah pasti/terjadwal.','medium',NULL,'{"grammar"}',34736182);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Tsumori.html','grammar','"日本に行くつもりです" artinya?','["Ingin ke Jepang", "Berniat ke Jepang", "Sudah ke Jepang", "Harus ke Jepang"]'::jsonb,1,'Artinya ''saya berniat pergi ke Jepang''. つもり menyiratkan bahwa keputusan ini sudah dipikirkan dengan matang, berbeda dengan 行きたいです yang hanya menyatakan keinginan tanpa kepastian rencana.','medium',NULL,'{"grammar"}',389017927);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Tsumori.html','grammar','Perbedaan つもり dan 予定?','["Tidak ada", "つもり=niat pribadi, 予定=sudah terjadwal", "つもり lebih pasti", "予定 = keinginan"]'::jsonb,1,'つもり adalah niat pribadi yang bisa berubah, sedangkan 予定 adalah rencana yang sudah lebih pasti/terjadwal, seperti janji temu atau jadwal resmi. 予定 terdengar lebih formal dan mengikat.','medium',NULL,'{"grammar"}',1160019764);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Tsumori.html','grammar','つもり dipakai dengan kata kerja bentuk...','["ます", "kamus (jisho)", "て", "た"]'::jsonb,1,'つもり dipakai setelah kata kerja bentuk kamus (bentuk dasar), contoh: 行くつもり (berniat pergi), 見るつもり (berniat menonton). Untuk niat negatif, gunakan bentuk ない + つもり.','medium',NULL,'{"grammar"}',333295470);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Tsumori.html','grammar','"今日は何もしないつもりです" artinya?','["Hari ini akan sibuk", "Hari ini berniat tidak melakukan apa-apa", "Hari ini ingin bekerja", "Hari ini harus istirahat"]'::jsonb,1,'Artinya ''hari ini saya berniat tidak melakukan apa-apa''. しない (bentuk negatif dari する) + つもり menunjukkan niat yang sudah diputuskan untuk beristirahat total hari itu.','medium',NULL,'{"grammar"}',1158599203);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Tsumori.html','grammar','Manakah yang menyatakan KEINGINAN, bukan niat?','["行くつもりです", "行きたいです", "行く予定です", "行かないつもりです"]'::jsonb,1,'～たい menyatakan keinginan (ingin melakukan sesuatu), berbeda dengan つもり yang menyatakan niat/keputusan yang sudah dipikirkan matang. たい lebih bersifat emosional/spontan.','medium',NULL,'{"grammar"}',724730787);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Tsumori.html','grammar','"来年、勉強するつもりです" — kata kerja する dalam bentuk?','["ます", "kamus", "ない", "て"]'::jsonb,1,'する di sini adalah bentuk kamus (bentuk dasar), dipakai langsung sebelum つもり sesuai aturan pembentukan pola ini. Artinya kalimat tersebut berarti ''tahun depan saya berniat belajar''.','medium',NULL,'{"grammar"}',69835835);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Grammar-Tsumori.html','grammar','Kapan つもり paling tepat dipakai?','["Mengajak orang lain", "Menyatakan niat yang sudah dipikirkan", "Menyatakan kewajiban", "Meminta izin"]'::jsonb,1,'つもり paling tepat dipakai untuk menyatakan niat atau rencana pribadi yang sudah dipikirkan, tetapi belum tentu bersifat resmi/terjadwal seperti 予定. Cocok untuk rencana informal jangka pendek maupun panjang.','medium',NULL,'{"grammar"}',20332791);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('I-Adjective.html','general','「大きい」の否定形は？','["大きいない", "大きくない", "大きじゃない", "大きでない"]'::jsonb,1,'I-adj否定=〜くない. 大きい→大きく+ない=大きくない. い取ってく+ない. 例: 高い→高くない, 安い→安くない。','medium',NULL,'{"general"}',2039444092);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('I-Adjective.html','general','「いい」の過去否定形は？','["いいくなかった", "よくなかった", "いいじゃなかった", "いかった"]'::jsonb,1,'いい/よい=例外. 現在形だけ「いい」、活用は全部「よ」. いい→よかった(過去)/よくない(否定)/よくなかった(過去否定)。','medium',NULL,'{"general"}',246307765);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('I-Adjective.html','general','「おいしい」のて形は？','["おいしいで", "おいしで", "おいしくて", "おいしいくて"]'::jsonb,2,'I-adj te-form=〜くて. おいしい→おいし+くて=おいしくて. Na-adj te-form=〜で: 好きで、静かで。','medium',NULL,'{"general"}',384481055);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('I-Adjective.html','general','「大きい部屋」のように名詞修飾する時は？','["大きな部屋", "大きい部屋(そのまま)", "大きく部屋", "大きで部屋"]'::jsonb,1,'I-adjは名詞をそのまま修飾: 大きい部屋(NG: 大きな). Na-adj: 静かな部屋(な必要). きれいな=na形容動詞の例外。','medium',NULL,'{"general"}',1161739332);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('I-Adjective.html','general','「上手くなりたい」の「くなる」は？','["状態の変化", "I-adjの変化形(〜くなる=menjadi ~)", "な形容動詞の変化", "動詞の変化"]'::jsonb,1,'I-adj+くなる=menjadi ~. 上手くなる=menjadi mahir. Na-adj+になる: 元気になる=menjadi sehat。','medium',NULL,'{"general"}',545972117);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('I-Adjective.html','general','「高い」の副詞形は？','["高に", "高く", "高で", "高いく"]'::jsonb,1,'I-adj adverb=〜く. 高く=dengan tinggi. 高く飛ぶ=terbang tinggi. Na-adj adverb=〜に: 静かに=dengan tenang。','medium',NULL,'{"general"}',1579397424);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Idiom-Bisnis.html','general','「腹を割って話す」の意味は？','["お腹の話をする", "本音で率直に話し合う", "怒って話す", "秘密を話す"]'::jsonb,1,'腹を割る=membelah perut(比喩)=jujur dari hati ke hati. 腹=hati/pikiran(慣用的). 社長と腹を割って話す=bicara jujur dengan CEO。','medium',NULL,'{"general"}',1548361955);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Idiom-Bisnis.html','general','「板挟みになる」の意味は？','["板に挟まれる", "二つの立場の間で身動きできない状態", "板を使う", "板の仕事をする"]'::jsonb,1,'板挟み=terjepit. 上司と部下の板挟みに=terjepit antara atasan dan bawahan. 両側から要求され動けない状態。','medium',NULL,'{"general"}',1526028488);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Idiom-Bisnis.html','general','「先手を打つ」の反対語的表現は？','["先手を打つ", "後手に回る", "一枚上手", "梯子を外される"]'::jsonb,1,'後手に回る=selalu bereaksi(reaktif), tidak pernah proaktif. 先手=langkah pertama(proaktif). 後手=langkah kedua(reaktif). ビジネスでは先手が重要。','medium',NULL,'{"general"}',1754413533);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Idiom-Bisnis.html','general','「梯子を外される」の意味は？','["はしごを使う", "約束した支援・協力を突然やめられる", "梯子を作る", "高い所に登る"]'::jsonb,1,'梯子を外される=dikhianati; ditinggalkan tanpa dukungan. 梯子=tangga. 上ったら梯子を外される=naik lalu tangganya dicabut. 裏切り・支援撤回の比喩。','medium',NULL,'{"general"}',1526702733);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Idiom-Bisnis.html','general','「お茶を濁す」の意味は？','["お茶を作る", "はっきりした返答をせず曖昧にごまかす", "茶道をする", "お茶を飲む"]'::jsonb,1,'お茶を濁す=mengambang; mengelak dengan jawaban tidak jelas. 「検討します」と言ってお茶を濁す=mengelak dengan ''akan dipertimbangkan''.','medium',NULL,'{"general"}',975812408);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('JLPT-Strategy-Guide.html','general','JLPT読解で最初にすべきことは？','["テキストを最初から全部読む", "設問を先に読んでから必要情報を探す", "全選択肢を読む", "翻訳する"]'::jsonb,1,'読解攻略: 設問先読みが最重要! 何が聞かれているか把握してからテキストを読む。全部読む必要はない—必要な情報を探す。','medium',NULL,'{"general"}',1585433998);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('JLPT-Strategy-Guide.html','general','聴解で「でも、やっぱり〜」の後は特に注意すべき理由は？','["文法的に重要", "最初の意見が変更される場合が多く、変更後が正解になりやすい", "関係ない", "難しいから"]'::jsonb,1,'でも・やっぱり・実は=意見変更のシグナル. 会話では最初の発言が後で変わることが多い. 変更後の内容が正解になりやすい。','medium',NULL,'{"general"}',432474217);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('JLPT-Strategy-Guide.html','general','JLPT N1の合格ラインは？','["100/180点以上+各セクション最低点", "70点以上", "全問正解", "50%以上"]'::jsonb,0,'N1合格: 100/180点以上 AND 各セクションで最低点クリア. セクション別基準もある(言語知識・読解・聴解それぞれ). 総合点だけでなく各セクションも重要。','medium',NULL,'{"general"}',702720674);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('JLPT-Strategy-Guide.html','general','N2合格に必要な学習期間の目安は？','["1-2ヶ月", "3-4ヶ月", "10-12ヶ月", "3年"]'::jsonb,2,'N2は約10-12ヶ月の集中学習が目安(N3取得後から). 1日2〜2.5時間. 語彙6000語・Grammar N2全て・Reading・Listeningが必要。','medium',NULL,'{"general"}',662084136);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('JLPT-Strategy-Guide.html','general','JLPT言語知識で1問にかける最大時間の目安は？','["5分", "30秒", "10分", "1時間"]'::jsonb,1,'言語知識: 1問最大30秒が目安. 分からなければ印をつけてスキップ→最後に戻る. 時間切れが最大の失点要因の一つ。','medium',NULL,'{"general"}',1628650646);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Japanese-Culture-Guide.html','general','「ホンネ」と「タテマエ」の意味は？','["挨拶の種類", "本音=本当の気持ち、建前=社会的・公的な態度", "敬語のレベル", "季節の挨拶"]'::jsonb,1,'ホンネ(本音)=perasaan/pikiran sesungguhnya. タテマエ(建前)=sikap/pernyataan publik. 「結構です」=iya(社交辞令) OR いいえ(本音) — 文脈で判断必須。','medium',NULL,'{"general"}',731990892);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Japanese-Culture-Guide.html','general','「ウチ」と「ソト」の概念とは？','["家の中と外", "自分のグループ(内)と外部の人(外)で言葉遣いを変える文化", "場所の概念", "時間の概念"]'::jsonb,1,'ウチ=自分たちのグループ. ソト=外部の人. 家族・同僚・顧客など関係によって使う言葉(特に敬語)が変わる。「うちの部長」など。','medium',NULL,'{"general"}',1727187166);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Japanese-Culture-Guide.html','general','名刺交換のマナーで正しいのは？','["片手で渡す", "両手で渡し・受け取り、すぐに読む", "ポケットにすぐ入れる", "机に伏せて置く"]'::jsonb,1,'名刺=顔の代わり. 両手で丁寧に渡す・受け取る. すぐ読んで内容を確認. 会議中は机の上に並べておく. ×たたむ・書き込む・落とす。','medium',NULL,'{"general"}',1319945847);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Japanese-Culture-Guide.html','general','「いただきます」の意味は？','["単なる習慣", "食材や作ってくれた人への感謝+命をいただくという謙虚さ", "注文するとき言う", "食べ終わった時言う"]'::jsonb,1,'いただきます=「いただく(もらう)」+「ます」. 食べ物の命・農家・料理人への感謝と謙虚さを表す。宗教的背景もある日本独自の文化。','medium',NULL,'{"general"}',497212206);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Japanese-Culture-Guide.html','general','お辞儀で45度が使われる場面は？','["普通の挨拶", "深いお詫び・謝罪の場面", "友達への挨拶", "子どもへの挨拶"]'::jsonb,1,'45°のお辞儀=深い謝罪・誠意を表す。15°=普通の挨拶, 30°=感謝・丁寧な挨拶, 45°=謝罪・深い敬意, 90°=超まれな最大謝罪。','medium',NULL,'{"general"}',1785440733);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Japanese-Numbers-Guide.html','general','「4」の日本語で避けるべき読み方は？','["よん", "し", "よっつ", "よ"]'::jsonb,1,'し=shi=死(kematian). だから病院・部屋番号・階数で4を避けることが多い. 代わりに「よん」を使う。','medium',NULL,'{"general"}',118253729);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Japanese-Numbers-Guide.html','general','「20日」の読み方は？','["にじゅうにち", "はつか", "ふたじゅうにち", "にじゅうか"]'::jsonb,1,'20日=はつか(例外). 1日=ついたち, 2日=ふつか, 14日=じゅうよっか. 特別な読み方を持つ日付がある。','medium',NULL,'{"general"}',2098413333);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Japanese-Numbers-Guide.html','general','「3分」の読み方は？','["さんふん", "さんぶん", "さんぷん", "みんぷん"]'::jsonb,2,'3分=さんぷん(半濁音化). 1分=いっぷん, 3分=さんぷん, 6分=ろっぷん, 8分=はっぷん. 分は変化が多い!','medium',NULL,'{"general"}',1809970476);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Japanese-Numbers-Guide.html','general','「8」が縁起が良い理由は？','["8人の神様", "八=末広がり(下に広がる=繁栄)", "8は発音がいい", "理由なし"]'::jsonb,1,'八(はち)=末広がり(suechebiro). 字の形が下に広がっている=繁栄・発展を象徴. 中国でも8は幸運の数字。','medium',NULL,'{"general"}',361173072);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Japanese-Numbers-Guide.html','general','「7時」の読み方として正しいのは？','["しちじのみ", "しちじ・なじのどちらでも", "ななじのみ", "しじ"]'::jsonb,1,'7時=しちじ または なじ. しち→し(死)に聞こえるため、なじ を好む人も多い. 文脈で使い分ける。','medium',NULL,'{"general"}',642927827);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Byouin.html','conversation','具合が悪いことを伝える言い方はどれか。','["具合が悪いです", "元気です", "忙しいです", "眠いです"]'::jsonb,0,'「具合が悪いです」(kondisi tidak enak badan)で体調不良を伝える。','medium',NULL,'{"conversation"}',900136630);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Byouin.html','conversation','熱があることを伝える言い方はどれか。','["熱があります", "熱がないです", "元気です", "寒いです"]'::jsonb,0,'「熱があります」(saya demam)で症状を伝える基本表現。','medium',NULL,'{"conversation"}',1550375459);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Byouin.html','conversation','痛い場所を伝えるときの言い方はどれか。','["ここが痛いです", "ここが安いです", "ここが遠いです", "ここが高いです"]'::jsonb,0,'「ここが痛いです」(di sini sakit)で患部を指して伝える。','medium',NULL,'{"conversation"}',2022656669);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Byouin.html','conversation','初診で受付に出すものはどれか。','["保険証", "予約", "処方箋", "症状"]'::jsonb,0,'初診では「保険証」(kartu asuransi)を受付に提示する。','medium',NULL,'{"conversation"}',1593499308);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Byouin.html','conversation','診察の予約を取りたいときの言い方はどれか。','["予約したいです", "予約しました", "予約ですか", "予約します"]'::jsonb,0,'「〜たいです」(ingin…)で希望を伝え、予約を申し込む。','medium',NULL,'{"conversation"}',267711519);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Byouin.html','conversation','薬局で処方箋を渡すときに言う言葉はどれか。','["これをお願いします", "これはいくらですか", "これはだれのですか", "これは何ですか"]'::jsonb,0,'「これをお願いします」(tolong ini)で処方箋を渡し薬を頼む。','medium',NULL,'{"conversation"}',709087894);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Byouin.html','conversation','医者に症状の期間を伝える言い方はどれか。','["三日前から具合が悪いです", "三日前は元気でした", "三日前に行きました", "三日前は休みでした"]'::jsonb,0,'「〜前から」(sejak…yang lalu)で症状が始まった時期を伝える。','medium',NULL,'{"conversation"}',1531142427);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Byouin.html','conversation','診察が終わったときに医者が言う言葉はどれか。','["お大事に", "いらっしゃいませ", "ただいま", "おかえりなさい"]'::jsonb,0,'「お大事に」(semoga lekas sembuh)は診察後の丁寧な締めくくりの言葉。','medium',NULL,'{"conversation"}',1627914552);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Byouin.html','conversation','薬の飲み方を尋ねる言い方はどれか。','["一日に何回飲みますか", "いくらですか", "どこで買いますか", "いつ休みですか"]'::jsonb,0,'「一日に何回」(berapa kali sehari)で服用回数を確認する。','medium',NULL,'{"conversation"}',564172957);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Byouin.html','conversation','「アレルギーはありますか」と聞かれたときに答える言い方はどれか。','["いいえ、ありません", "はい、痛いです", "はい、忙しいです", "いいえ、元気です"]'::jsonb,0,'アレルギーの有無は「はい/いいえ、あります/ありません」で答える。','medium',NULL,'{"conversation"}',292508994);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Denwa.html','conversation','電話に出るときの第一声はどれか。','["もしもし", "いただきます", "ただいま", "おやすみ"]'::jsonb,0,'「もしもし」(halo) adalah sapaan standar saat menjawab telepon dalam percakapan biasa. Dalam konteks bisnis, biasanya diikuti dengan menyebutkan nama perusahaan dan nama diri sendiri.','medium',NULL,'{"conversation"}',1403658227);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Denwa.html','conversation','相手を待たせるときの丁寧な言い方はどれか。','["少々お待ちください", "早くして", "だめです", "知りません"]'::jsonb,0,'「少々お待ちください」(mohon tunggu sebentar) adalah ungkapan sopan saat perlu menahan lawan bicara di telepon, misalnya saat mencari informasi atau menyambungkan ke orang lain.','medium',NULL,'{"conversation"}',1429778441);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Denwa.html','conversation','名前を尋ねる丁寧な言い方はどれか。','["お名前をお願いします", "名前", "だれ", "何"]'::jsonb,0,'「お名前をお願いします」(boleh tahu nama?) adalah cara sopan menanyakan nama penelepon, sering dipakai di awal percakapan telepon formal atau bisnis.','medium',NULL,'{"conversation"}',107118245);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Denwa.html','conversation','伝言を頼むときの言い方はどれか。','["伝言をお願いできますか", "伝言", "伝えろ", "知らない"]'::jsonb,0,'「伝言をお願いできますか」(bisa titip pesan?) dipakai saat orang yang dituju sedang tidak ada, dan penelepon ingin meninggalkan pesan untuk disampaikan kembali.','medium',NULL,'{"conversation"}',1799368681);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Denwa.html','conversation','相手が不在のとき言う言葉はどれか。','["ただ今おりません", "います", "来ます", "知りません"]'::jsonb,0,'「ただ今おりません」(sedang tidak ada) adalah ungkapan sopan (menggunakan kenjougo おる) untuk memberi tahu bahwa orang yang dicari sedang tidak di tempat, umum dipakai dalam konteks bisnis.','medium',NULL,'{"conversation"}',725451784);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Denwa.html','conversation','電話を切るときの丁寧な言葉はどれか。','["失礼します", "さようなら", "おやすみ", "こんにちは"]'::jsonb,0,'「失礼します」(permisi) dipakai untuk menutup telepon dengan sopan. Kata yang sama juga dipakai saat masuk/keluar ruangan, menunjukkan fleksibilitas ungkapan ini dalam berbagai konteks perpisahan.','medium',NULL,'{"conversation"}',906393595);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Denwa.html','conversation','かけ直すことを伝える言い方はどれか。','["また後でかけ直します", "もう電話しない", "知らない", "だめ"]'::jsonb,0,'「かけ直します」(saya telepon lagi) dipakai saat ingin memberi tahu bahwa akan menelepon kembali di lain waktu, biasanya karena situasi yang kurang tepat untuk melanjutkan percakapan.','medium',NULL,'{"conversation"}',1468523828);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Denwa.html','conversation','聞き取れないとき丁寧に確認する言い方はどれか。','["もう一度お願いします", "うるさい", "早く", "だめ"]'::jsonb,0,'「もう一度お願いします」(tolong ulangi) juga berlaku dalam konteks telepon saat suara kurang jelas atau koneksi terputus-putus, sama seperti dalam percakapan tatap muka.','medium',NULL,'{"conversation"}',690256397);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Denwa.html','conversation','電話番号を確認する言い方はどれか。','["お電話番号をお願いします", "番号", "電話", "だれ"]'::jsonb,0,'「お電話番号をお願いします」(boleh minta nomornya?) dipakai untuk mengonfirmasi nomor telepon lawan bicara, penting dalam konteks bisnis untuk keperluan menghubungi kembali.','medium',NULL,'{"conversation"}',561053075);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Denwa.html','conversation','間違い電話のときの対応はどれか。','["失礼しました、番号をお確かめください", "怒る", "切るだけ", "無視"]'::jsonb,0,'「失礼しました」(maaf) adalah respons sopan saat menyadari telah salah sambung. Ungkapan singkat ini menunjukkan permintaan maaf tanpa perlu penjelasan panjang.','medium',NULL,'{"conversation"}',1312082272);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Eki.html','conversation','切符を買いたいときの言い方はどれか。','["東京までの切符をください", "切符", "東京", "ください切符"]'::jsonb,0,'「〜までの切符をください」(minta tiket sampai…) menyebutkan tujuan sebelum meminta tiket, pola standar saat membeli tiket kereta di loket atau mesin otomatis.','medium',NULL,'{"conversation"}',707059804);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Eki.html','conversation','何番線か尋ねる言い方はどれか。','["何番線ですか", "いくらですか", "何時ですか", "だれですか"]'::jsonb,0,'「何番線ですか」(peron nomor berapa?) dipakai untuk menanyakan nomor peron kereta yang dituju, penting terutama di stasiun besar dengan banyak jalur.','medium',NULL,'{"conversation"}',615282649);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Eki.html','conversation','「乗り換え」の意味はどれか。','["ganti kereta/transit", "turun", "tiket", "peron"]'::jsonb,0,'乗り換え berarti transit/berganti kereta. Pola 「〜で乗り換えます」menunjukkan di stasiun mana penumpang harus turun dan naik kereta lain untuk melanjutkan perjalanan.','medium',NULL,'{"conversation"}',1460843362);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Eki.html','conversation','次の電車の時刻を尋ねる言い方はどれか。','["次の電車は何時ですか", "次", "電車", "何"]'::jsonb,0,'「次の電車は何時ですか」(kereta berikutnya jam berapa?) adalah pertanyaan umum di stasiun untuk mengetahui jadwal kereta selanjutnya, terutama jika kereta yang diinginkan baru saja berangkat.','medium',NULL,'{"conversation"}',125298870);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Eki.html','conversation','「急行」と「各駅停車」の違いはどれか。','["急行は速く主要駅のみ停車", "同じ", "各駅が速い", "急行は遅い"]'::jsonb,0,'急行 (ekspres) hanya berhenti di stasiun-stasiun utama sehingga lebih cepat, sedangkan 各駅停車 berhenti di semua stasiun. Memahami perbedaan ini penting agar tidak salah naik kereta dan melewatkan stasiun tujuan.','medium',NULL,'{"conversation"}',1304758545);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Eki.html','conversation','料金を尋ねる言い方はどれか。','["料金はいくらですか", "料金", "いくら料金", "だれ"]'::jsonb,0,'「料金はいくらですか」(tarifnya berapa?) dipakai untuk menanyakan ongkos perjalanan kereta, biasanya dijawab dengan menyebutkan nominal dalam yen sesuai jarak tempuh.','medium',NULL,'{"conversation"}',1194389116);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Eki.html','conversation','改札(kaisatsu)で必要なものはどれか。','["切符またはICカード", "パスポート", "財布のみ", "何もいらない"]'::jsonb,0,'改札 adalah gerbang tiket yang harus dilewati untuk masuk/keluar peron. Yang diperlukan adalah tiket kertas atau kartu IC (seperti Suica/Pasmo) yang ditap atau dimasukkan ke mesin.','medium',NULL,'{"conversation"}',1954430449);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Eki.html','conversation','道に迷ったとき駅員に尋ねる言い方はどれか。','["すみません、〜線はどこですか", "うるさい", "早く", "知らない"]'::jsonb,0,'「すみません、〜線はどこですか」(di mana jalur…?) dipakai untuk bertanya kepada petugas stasiun saat bingung mencari jalur yang benar di stasiun besar dengan banyak jalur.','medium',NULL,'{"conversation"}',1233300519);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Eki.html','conversation','電車が遅れているときのアナウンス語はどれか。','["遅れ(keterlambatan)", "出発", "到着", "満員"]'::jsonb,0,'遅れ berarti keterlambatan. Pengumuman 「電車が遅れています」sering terdengar di stasiun saat ada gangguan operasional, memberi tahu penumpang bahwa kereta tidak datang tepat waktu.','medium',NULL,'{"conversation"}',318812446);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Eki.html','conversation','目的の駅で降りる準備を表す言い方はどれか。','["次で降ります", "乗ります", "待ちます", "戻ります"]'::jsonb,0,'「次で降ります」(turun di berikutnya) memberi tahu bahwa penumpang akan turun di stasiun selanjutnya, berguna saat memberi tahu orang di sekitar atau petugas kereta yang padat.','medium',NULL,'{"conversation"}',714842581);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Jikoshoukai.html','conversation','初対面の相手に最初に言う挨拶はどれか。','["はじめまして", "おやすみ", "ただいま", "いただきます"]'::jsonb,0,'「はじめまして」adalah salam khusus untuk pertemuan pertama kali, berbeda dari salam harian seperti こんにちは. Ungkapan ini menandai awal sebuah perkenalan dan selalu diikuti dengan menyebutkan nama diri.','medium',NULL,'{"conversation"}',542336834);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Jikoshoukai.html','conversation','名前を伝えるときの自然な言い方はどれか。','["わたしは田中です", "田中する", "田中ください", "田中ですか"]'::jsonb,0,'「わたしは〜です」(nama saya…) adalah pola paling dasar dan sopan untuk menyebutkan nama. Pola ini bisa diperluas dengan menambahkan asal, pekerjaan, atau hobi setelahnya dalam rangkaian perkenalan diri.','medium',NULL,'{"conversation"}',332388013);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Jikoshoukai.html','conversation','「ご出身はどちらですか」への答えはどれか。','["インドネシアです", "元気です", "そうです", "わかりません"]'::jsonb,0,'出身 berarti asal daerah/kampung halaman. Jawaban yang tepat menggunakan pola 「〜出身です」atau「〜から来ました」, misalnya インドネシア出身です (saya berasal dari Indonesia).','medium',NULL,'{"conversation"}',1576965213);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Jikoshoukai.html','conversation','自己紹介の結びとして適切なのはどれか。','["どうぞよろしくお願いします", "さようなら", "おやすみなさい", "いただきます"]'::jsonb,0,'「どうぞよろしくお願いします」(mohon kerja samanya) adalah kalimat penutup standar dalam perkenalan diri di Jepang. Ungkapan ini menyiratkan harapan untuk hubungan baik ke depannya, baik dalam konteks kerja maupun pertemanan.','medium',NULL,'{"conversation"}',1884030365);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Jikoshoukai.html','conversation','「どうぞよろしく」と言われたときの返事はどれか。','["こちらこそ、よろしくお願いします", "いいえ", "けっこうです", "だめです"]'::jsonb,0,'「こちらこそ」(saya juga/justru saya) adalah balasan yang sopan dan natural, menyiratkan bahwa harapan yang sama juga berlaku dari pihak yang menjawab. Ini menciptakan kesan saling menghormati sejak awal perkenalan.','medium',NULL,'{"conversation"}',1078624040);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Jikoshoukai.html','conversation','仕事を尋ねる質問はどれか。','["お仕事は何ですか", "元気ですか", "何時ですか", "いくらですか"]'::jsonb,0,'「お仕事は何ですか」(pekerjaan apa?) adalah cara sopan menanyakan profesi seseorang. Menambahkan お di depan 仕事 membuat pertanyaan terdengar lebih halus dibanding hanya 仕事は何ですか.','medium',NULL,'{"conversation"}',1245245204);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Jikoshoukai.html','conversation','趣味を伝える言い方はどれか。','["趣味は音楽です", "趣味します", "趣味ください", "趣味ですか"]'::jsonb,0,'「趣味は〜です」(hobi saya…) adalah pola dasar untuk memperkenalkan hobi, biasa dipakai setelah menyebutkan nama dan pekerjaan dalam rangkaian perkenalan diri yang lebih lengkap.','medium',NULL,'{"conversation"}',1414232169);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Jikoshoukai.html','conversation','部屋を出るときの丁寧な言葉はどれか。','["失礼します", "いただきます", "ただいま", "おかえり"]'::jsonb,0,'「失礼します」(permisi) adalah ungkapan serbaguna yang dipakai saat masuk/keluar ruangan, mengakhiri telepon, atau berpamitan dari pertemuan. Kata ini menunjukkan kesadaran akan sopan santun terhadap ruang orang lain.','medium',NULL,'{"conversation"}',1649088173);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Jikoshoukai.html','conversation','相手の名前を聞き取れなかったときの言い方はどれか。','["もう一度お願いします", "だめです", "知りません", "いいです"]'::jsonb,0,'「もう一度お願いします」(tolong ulangi) adalah cara sopan meminta pengulangan tanpa terkesan tidak sopan. Bisa ditambah 「すみません」di depannya untuk kesan lebih halus: すみません、もう一度お願いします.','medium',NULL,'{"conversation"}',944891864);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Jikoshoukai.html','conversation','自己紹介で避けたほうがよいのはどれか。','["いきなりタメ口で話す", "丁寧語を使う", "笑顔で話す", "名前を言う"]'::jsonb,0,'Bahasa kasual/tameguchi sebaiknya dihindari saat perkenalan pertama, terutama dengan orang yang baru dikenal atau lebih senior. Menggunakan bahasa sopan (丁寧語) di awal perkenalan menciptakan kesan pertama yang baik dan aman diperbaiki nanti jika hubungan menjadi akrab.','medium',NULL,'{"conversation"}',78342767);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Kaimono.html','conversation','値段を尋ねるときの言い方はどれか。','["これはいくらですか", "これは何ですか", "これはどこですか", "これはだれですか"]'::jsonb,0,'「いくらですか」(berapa harganya?) adalah pertanyaan paling umum dan langsung untuk menanyakan harga. Bisa ditambah kata benda di depannya seperti これはいくらですか (ini berapa harganya?).','medium',NULL,'{"conversation"}',808488049);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Kaimono.html','conversation','商品を買いたいときの言い方はどれか。','["これをください", "これをします", "これをですか", "これをいます"]'::jsonb,0,'「〜をください」(minta/tolong…) adalah pola dasar untuk meminta atau membeli sesuatu di toko. Pola ini lebih sopan dibanding perintah langsung dan sangat umum digunakan dalam transaksi sehari-hari.','medium',NULL,'{"conversation"}',2048811808);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Kaimono.html','conversation','「袋はいりますか」への断り方はどれか。','["いいえ、けっこうです", "はい、そうです", "わかりません", "高いです"]'::jsonb,0,'「けっこうです」(tidak usah, terima kasih) adalah cara menolak dengan sopan tanpa terkesan kasar. 「いりません」juga bisa dipakai tapi terdengar sedikit lebih langsung/tegas dibanding けっこうです.','medium',NULL,'{"conversation"}',629133652);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Kaimono.html','conversation','支払い方法を伝える言い方はどれか。','["カードでお願いします", "カードします", "カードですか", "カードください"]'::jsonb,0,'「カードでお願いします」(dengan kartu) menggunakan partikel で untuk menunjukkan alat/metode pembayaran. Pola yang sama berlaku untuk 現金でお願いします (dengan tunai).','medium',NULL,'{"conversation"}',122870548);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Kaimono.html','conversation','「高い」の反対の意味の語はどれか。','["安い", "大きい", "新しい", "多い"]'::jsonb,0,'安い(murah) adalah lawan kata dari 高い(mahal). Kedua kata sifat-i ini adalah pasangan dasar yang sering muncul bersamaan dalam percakapan tentang harga dan tawar-menawar.','medium',NULL,'{"conversation"}',944610474);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Kaimono.html','conversation','店員の「いらっしゃいませ」の意味はどれか。','["ようこそ(いらっしゃい)", "さようなら", "ありがとう", "ごめんなさい"]'::jsonb,0,'「いらっしゃいませ」(selamat datang) adalah sapaan khas pelayan toko/restoran saat pelanggan masuk. Kata ini tidak memerlukan balasan khusus dari pelanggan — cukup dianggap sebagai sapaan formal satu arah.','medium',NULL,'{"conversation"}',1363563827);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Kaimono.html','conversation','数量を伝える言い方で正しいのはどれか。','["みっつください", "みっつします", "みっつですか", "みっついます"]'::jsonb,0,'Angka dalam bahasa Jepang untuk benda umum memakai hitungan asli Jepang seperti ひとつ・ふたつ・みっつ, bukan angka Tionghoa-Jepang biasa. 「みっつください」berarti ''minta 3 buah''.','medium',NULL,'{"conversation"}',26245707);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Kaimono.html','conversation','「ありがとうございました」に対する店員の返事はどれか。','["またお越しくださいませ", "いくらですか", "高いです", "だめです"]'::jsonb,0,'「またお越しください」(datang lagi ya) adalah ungkapan sopan pelayan toko saat mengantar pelanggan pergi. Ungkapan ini menunjukkan harapan pelanggan akan kembali berbelanja di kemudian hari.','medium',NULL,'{"conversation"}',1644557837);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Kaimono.html','conversation','試着したいときの言い方はどれか。','["試着してもいいですか", "試着します", "試着ください", "試着ですか"]'::jsonb,0,'「〜てもいいですか」(bolehkah…?) adalah pola meminta izin yang bisa dipakai untuk berbagai situasi, termasuk mencoba pakaian: 試着してもいいですか (bolehkah saya coba pakai?).','medium',NULL,'{"conversation"}',133290321);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Kaimono.html','conversation','支払いで現金を使うことを表す語はどれか。','["現金", "カード", "袋", "レジ"]'::jsonb,0,'現金 (tunai) adalah lawan dari カード (kartu) dalam konteks pembayaran. Kedua istilah ini sering muncul saat kasir bertanya metode pembayaran di レジ (kasir/meja bayar).','medium',NULL,'{"conversation"}',1325279359);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Konbini.html','conversation','店員に「温めますか」と聞かれたときに希望を伝える答えはどれか。','["はい、お願いします", "はい、そうです", "いいえ、痛いです", "いいえ、忙しいです"]'::jsonb,0,'「はい、お願いします」(ya, tolong)で温めを頼む自然な返事。','medium',NULL,'{"conversation"}',773543901);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Konbini.html','conversation','レジ袋が必要なときの言い方はどれか。','["袋をお願いします", "袋はいらないです", "袋は高いです", "袋はどこですか"]'::jsonb,0,'「袋をお願いします」(tolong kantongnya)で必要と伝える。','medium',NULL,'{"conversation"}',847973098);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Konbini.html','conversation','お箸が欲しいときの言い方はどれか。','["お箸をつけてください", "お箸は結構です", "お箸はいくらですか", "お箸はだれのですか"]'::jsonb,0,'「〜をつけてください」(tolong sertakan…)で追加を頼む。','medium',NULL,'{"conversation"}',1010967845);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Konbini.html','conversation','ポイントカードを持っていないときの答えはどれか。','["持っていません", "持っています", "わかりません", "知りません"]'::jsonb,0,'「持っていません」(tidak punya)で率直に答えれば十分。','medium',NULL,'{"conversation"}',1655337318);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Konbini.html','conversation','公共料金を払いたいときの言い方はどれか。','["これを払いたいです", "これをください", "これは何ですか", "これはいくらですか"]'::jsonb,0,'「払いたいです」(ingin membayar)で用件を伝える。','medium',NULL,'{"conversation"}',228642234);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Konbini.html','conversation','支払い方法をカードにしたいときの言い方はどれか。','["カードでお願いします", "カードはだめです", "カードはどこですか", "カードは高いです"]'::jsonb,0,'「〜でお願いします」(dengan…)で支払い方法を指定する。','medium',NULL,'{"conversation"}',1066876838);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Konbini.html','conversation','トイレを借りたいときの丁寧な言い方はどれか。','["トイレを借りてもいいですか", "トイレは高いですか", "トイレはだれのですか", "トイレは何ですか"]'::jsonb,0,'「〜てもいいですか」(bolehkah…?)で許可を求める丁寧な聞き方。','medium',NULL,'{"conversation"}',1883216225);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Konbini.html','conversation','宅配便を送りたいときに伝える言い方はどれか。','["荷物を送りたいです", "荷物を買いたいです", "荷物はいくらですか", "荷物はどこですか"]'::jsonb,0,'「送りたいです」(ingin mengirim)で宅配便の依頼を伝える。','medium',NULL,'{"conversation"}',1608456361);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Konbini.html','conversation','小銭が足りないときに両替を頼む言い方はどれか。','["両替をお願いします", "両替はだめです", "両替は高いです", "両替はどこですか"]'::jsonb,0,'「両替をお願いします」(tolong tukar uang)で頼む。','medium',NULL,'{"conversation"}',1936701116);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Konbini.html','conversation','レシートが不要なときの言い方はどれか。','["レシートは結構です", "レシートをください", "レシートは高いです", "レシートはどこですか"]'::jsonb,0,'「結構です」(tidak usah)で丁寧に断る表現。','medium',NULL,'{"conversation"}',746692965);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Michi-Annai.html','conversation','知らない場所を尋ねるときの切り出しはどれか。','["すみません、駅はどこですか", "こんばんは", "いただきます", "おやすみ"]'::jsonb,0,'「すみません、〜はどこですか」(permisi, di mana…?) adalah pembuka standar untuk bertanya arah kepada orang asing di jalan. Kata すみません penting sebagai pembuka sopan sebelum mengajukan pertanyaan.','medium',NULL,'{"conversation"}',2037477585);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Michi-Annai.html','conversation','「まっすぐ行ってください」の意味はどれか。','["lurus terus", "belok kanan", "berhenti", "kembali"]'::jsonb,0,'まっすぐ berarti lurus, dan 「行ってください」berarti ''silakan pergi/jalan''. Kalimat ini adalah instruksi arah paling dasar yang sering muncul dalam petunjuk jalan sederhana.','medium',NULL,'{"conversation"}',1791288354);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Michi-Annai.html','conversation','「次の信号を右に曲がってください」の「右」はどれか。','["kanan", "kiri", "depan", "belakang"]'::jsonb,0,'右 berarti kanan, sedangkan 左 berarti kiri. Kalimat lengkapnya berarti ''di lampu lalu lintas berikutnya, silakan belok kanan'' — pola umum dalam memberi arah menggunakan penanda lokasi seperti lampu lalu lintas.','medium',NULL,'{"conversation"}',803398996);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Michi-Annai.html','conversation','距離を尋ねる言い方はどれか。','["ここから遠いですか", "何時ですか", "いくらですか", "だれですか"]'::jsonb,0,'「遠いですか」(jauh?) adalah pertanyaan sederhana untuk mengetahui apakah tujuan masih jauh. Lawan katanya adalah 近い (dekat), yang sering muncul dalam jawaban seperti いいえ、近いです.','medium',NULL,'{"conversation"}',1863787961);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Michi-Annai.html','conversation','道を教えてもらったお礼はどれか。','["ありがとうございます", "さようなら", "いただきます", "はじめまして"]'::jsonb,0,'Setelah diberi tahu arah jalan, ucapan terima kasih yang tepat adalah 「ありがとうございます」. Ini menunjukkan sopan santun dasar setelah menerima bantuan dari orang asing di jalan.','medium',NULL,'{"conversation"}',1565079847);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Michi-Annai.html','conversation','「駅の近くです」の「近く」の意味はどれか。','["dekat", "jauh", "dalam", "atas"]'::jsonb,0,'近く berarti dekat/di sekitar. Kalimat 「駅の近くです」berarti ''dekat stasiun'', pola yang sama bisa dipakai untuk lokasi lain seperti 「コンビニの近く」(dekat minimarket).','medium',NULL,'{"conversation"}',599379082);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Michi-Annai.html','conversation','分からないとき丁寧に聞き返す言い方はどれか。','["もう一度お願いします", "だめです", "知りません", "いいです"]'::jsonb,0,'「もう一度お願いします」(tolong ulangi) dipakai saat tidak menangkap penjelasan arah dengan jelas. Ungkapan ini sopan dan tidak akan membuat orang yang menjelaskan merasa tersinggung.','medium',NULL,'{"conversation"}',1160320979);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Michi-Annai.html','conversation','「歩いて10分ぐらいです」の意味はどれか。','["sekitar 10 menit jalan kaki", "10 jam", "10 km naik mobil", "tidak tahu"]'::jsonb,0,'Kalimat ini berarti ''sekitar 10 menit jalan kaki''. Pola 歩いて〜分ぐらい adalah cara umum menyampaikan estimasi waktu tempuh berjalan kaki menuju suatu tempat.','medium',NULL,'{"conversation"}',455570275);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Michi-Annai.html','conversation','目印(patokan)を尋ねる言い方はどれか。','["近くに何がありますか", "いくらですか", "何時ですか", "だれですか"]'::jsonb,0,'「近くに何がありますか」(ada apa di dekatnya?) dipakai untuk menanyakan penanda/landmark di sekitar tujuan, membantu memastikan lokasi yang benar tanpa harus mengandalkan alamat detail.','medium',NULL,'{"conversation"}',953429764);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Michi-Annai.html','conversation','道案内で「渡ってください」が使われる場所はどれか。','["横断歩道・橋", "部屋の中", "椅子", "机"]'::jsonb,0,'渡る berarti menyeberang, biasanya dipakai untuk instruksi melewati zebra cross atau jembatan. 「渡ってください」berarti ''silakan menyeberang'', bagian umum dari petunjuk arah yang melibatkan penyeberangan jalan.','medium',NULL,'{"conversation"}',1989232379);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Restoran.html','conversation','店員を呼んで注文したいときの言い方はどれか。','["すみません、注文お願いします", "さようなら", "ただいま", "おやすみ"]'::jsonb,0,'「すみません」dipakai untuk memanggil perhatian pelayan, diikuti 「注文お願いします」(mau pesan). Kombinasi ini adalah cara standar dan sopan untuk memulai proses pemesanan di restoran Jepang.','medium',NULL,'{"conversation"}',1489324780);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Restoran.html','conversation','店員におすすめを尋ねる言い方はどれか。','["おすすめは何ですか", "いくらですか", "どこですか", "だれですか"]'::jsonb,0,'「おすすめは何ですか」(rekomendasinya apa?) adalah pertanyaan umum saat bingung memilih menu. Pelayan biasanya akan menjawab dengan menyebutkan menu andalan atau yang sedang populer hari itu.','medium',NULL,'{"conversation"}',259551309);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Restoran.html','conversation','料理を一つ頼むときの言い方はどれか。','["これを一つください", "これを一つします", "これを一つですか", "これ一ついます"]'::jsonb,0,'「〜を一つください」(minta satu…) menggabungkan nama makanan dengan angka hitungan untuk memesan jumlah tertentu. Pola ini bisa disesuaikan jumlahnya: 二つ (dua), 三つ (tiga), dan seterusnya.','medium',NULL,'{"conversation"}',1103448858);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Restoran.html','conversation','食事の前に言う言葉はどれか。','["いただきます", "ごちそうさま", "さようなら", "はじめまして"]'::jsonb,0,'「いただきます」diucapkan sebelum makan sebagai ungkapan rasa syukur atas makanan yang akan disantap — bukan sekadar ''selamat makan'', tapi mengandung makna menghargai sumber makanan tersebut.','medium',NULL,'{"conversation"}',1442602937);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Restoran.html','conversation','食事の後に言う言葉はどれか。','["ごちそうさまでした", "いただきます", "いらっしゃいませ", "おはよう"]'::jsonb,0,'「ごちそうさま(でした)」diucapkan setelah selesai makan sebagai ucapan terima kasih atas hidangan yang telah disajikan. Ungkapan ini adalah pasangan dari いただきます yang diucapkan sebelum makan.','medium',NULL,'{"conversation"}',363448721);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Restoran.html','conversation','「お会計」の意味はどれか。','["支払い(tagihan)", "入口", "予約", "注文"]'::jsonb,0,'お会計 berarti tagihan/proses pembayaran setelah makan. 「お会計お願いします」adalah cara meminta bon/nota untuk membayar, sering digunakan di restoran Jepang saat hendak pulang.','medium',NULL,'{"conversation"}',1832522763);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Restoran.html','conversation','水がほしいときの言い方はどれか。','["お水をください", "お水します", "お水ですか", "お水います"]'::jsonb,0,'「お水をください」(minta air) menggunakan pola ～をください yang sama dengan permintaan barang lainnya. Di banyak restoran Jepang, air putih biasanya disediakan gratis tanpa perlu diminta.','medium',NULL,'{"conversation"}',1727481135);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Restoran.html','conversation','料理がおいしいと伝える言い方はどれか。','["おいしいです", "たかいです", "さむいです", "ねむいです"]'::jsonb,0,'「おいしいです」(enak) adalah cara sederhana dan tulus mengungkapkan kepuasan atas rasa makanan. Ungkapan ini sering disambut baik oleh pelayan atau koki sebagai bentuk apresiasi pelanggan.','medium',NULL,'{"conversation"}',1497414465);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Restoran.html','conversation','予約があることを伝える言い方はどれか。','["予約しています", "予約ください", "予約ですか", "予約します"]'::jsonb,0,'「予約しています」(sudah reservasi) diucapkan saat check-in di restoran yang mengharuskan pemesanan tempat sebelumnya. Biasanya diikuti dengan menyebutkan nama pemesan.','medium',NULL,'{"conversation"}',294574249);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Restoran.html','conversation','注文を変えたいときの丁寧な言い方はどれか。','["すみません、変更してもいいですか", "変える", "だめです", "知りません"]'::jsonb,0,'「変更してもいいですか」(boleh ubah?) menggunakan pola izin ～てもいい yang sama seperti permintaan sopan lainnya, cocok dipakai saat ingin mengganti pesanan sebelum makanan disiapkan.','medium',NULL,'{"conversation"}',130903957);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Shokuba.html','conversation','同僚に会ったときの一般的な挨拶はどれか。','["お疲れ様です", "いただきます", "ごちそうさま", "おやすみ"]'::jsonb,0,'「お疲れ様です」(terima kasih atas kerja kerasnya)は職場の基本挨拶。','medium',NULL,'{"conversation"}',761453509);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Shokuba.html','conversation','新しい仕事を頼まれたときの丁寧な返事はどれか。','["はい、よろしくお願いします", "はい、そうです", "いいえ、だめです", "知りません"]'::jsonb,0,'「よろしくお願いします」(mohon bantuannya)は依頼を受けたときの丁寧な返事。','medium',NULL,'{"conversation"}',1679533647);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Shokuba.html','conversation','休憩を取りたいときの言い方はどれか。','["休憩してもいいですか", "休憩はだめです", "休憩は高いです", "休憩はどこですか"]'::jsonb,0,'「〜てもいいですか」(bolehkah…?)で許可を求める丁寧な表現。','medium',NULL,'{"conversation"}',327467484);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Shokuba.html','conversation','シフトを確認したいときの言い方はどれか。','["シフトを確認してもいいですか", "シフトはいくらですか", "シフトはだれですか", "シフトは何ですか"]'::jsonb,0,'「確認してもいいですか」(boleh saya cek?)でシフトの確認を丁寧に頼む。','medium',NULL,'{"conversation"}',1840537613);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Shokuba.html','conversation','上司に報告するときの切り出しはどれか。','["ご報告があります", "さようなら", "おやすみなさい", "いただきます"]'::jsonb,0,'「ご報告があります」(ada laporan)は報告を切り出す丁寧な言い方。','medium',NULL,'{"conversation"}',1122093513);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Shokuba.html','conversation','残業を頼まれて引き受けるときの言い方はどれか。','["わかりました、やります", "知りません", "だめです", "いいです"]'::jsonb,0,'「わかりました」(mengerti)で指示を受け入れる基本の返事。','medium',NULL,'{"conversation"}',1602871236);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Shokuba.html','conversation','有給休暇を申請したいときの言い方はどれか。','["有給休暇を取りたいです", "有給休暇はいくらですか", "有給休暇はだれのですか", "有給休暇はどこですか"]'::jsonb,0,'「〜たいです」(ingin…)で有給休暇の希望を伝える。','medium',NULL,'{"conversation"}',1623479984);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Shokuba.html','conversation','引き継ぎを受けるときに確認する言い方はどれか。','["もう一度説明してもらえますか", "説明はいりません", "知っています", "わかりません"]'::jsonb,0,'「もう一度説明してもらえますか」(bisa dijelaskan sekali lagi?)で丁寧に確認する。','medium',NULL,'{"conversation"}',1766941717);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Shokuba.html','conversation','先に帰るときに同僚に言う言葉はどれか。','["お先に失礼します", "ただいま", "いってきます", "おかえりなさい"]'::jsonb,0,'「お先に失礼します」(permisi pulang duluan)は退勤時の丁寧な挨拶。','medium',NULL,'{"conversation"}',366026711);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Shokuba.html','conversation','ミスを謝るときの丁寧な言い方はどれか。','["申し訳ございません", "ありがとうございます", "おめでとうございます", "こんにちは"]'::jsonb,0,'「申し訳ございません」(mohon maaf sebesar-besarnya)はミスを謝る最も丁寧な表現。','medium',NULL,'{"conversation"}',546084226);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Yakusoku.html','conversation','会う時間を提案する言い方はどれか。','["何時に会いましょうか", "何時ですか", "いつですか", "どこですか"]'::jsonb,0,'「〜ましょうか」(bagaimana kalau kita…?)で提案する丁寧な表現。','medium',NULL,'{"conversation"}',631145800);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Yakusoku.html','conversation','都合を尋ねる言い方はどれか。','["ご都合はいかがですか", "元気ですか", "忙しいですか", "暇ですか"]'::jsonb,0,'「ご都合はいかがですか」(bagaimana jadwal Anda?)は丁寧な確認の仕方。','medium',NULL,'{"conversation"}',1847201547);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Yakusoku.html','conversation','その日は空いていることを伝える言い方はどれか。','["その日は空いています", "その日は忙しいです", "その日は休みです", "その日はだめです"]'::jsonb,0,'「空いています」(kosong/luang)で予定がないことを伝える。','medium',NULL,'{"conversation"}',1774099823);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Yakusoku.html','conversation','予定を変更したいときの言い方はどれか。','["予定を変更してもいいですか", "予定はいくらですか", "予定はだれですか", "予定はどこですか"]'::jsonb,0,'「〜てもいいですか」(bolehkah…?)で丁寧に変更を申し出る。','medium',NULL,'{"conversation"}',1926386255);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Yakusoku.html','conversation','約束をキャンセルしたいときの丁寧な言い方はどれか。','["すみません、キャンセルしてもいいですか", "キャンセルします", "だめです", "知りません"]'::jsonb,0,'「すみません」を添えて丁寧にキャンセルを申し出る。','medium',NULL,'{"conversation"}',353176229);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Yakusoku.html','conversation','待ち合わせ場所を確認する言い方はどれか。','["場所はどこですか", "時間はいつですか", "名前は何ですか", "値段はいくらですか"]'::jsonb,0,'「場所はどこですか」(tempatnya di mana?)で待ち合わせ場所を確認する。','medium',NULL,'{"conversation"}',1385765269);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Yakusoku.html','conversation','集合時間を伝える言い方はどれか。','["10時に集合しましょう", "10時は忙しいです", "10時はだめです", "10時はいくらですか"]'::jsonb,0,'「〜に集合しましょう」(mari berkumpul jam…)で集合時間を提案する。','medium',NULL,'{"conversation"}',743129834);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Yakusoku.html','conversation','遅れそうなときに連絡する言い方はどれか。','["少し遅れます、すみません", "もう着きました", "時間通りです", "早いです"]'::jsonb,0,'「遅れます」(akan terlambat)と一言連絡するのがマナー。','medium',NULL,'{"conversation"}',1211609154);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Yakusoku.html','conversation','会う約束を楽しみにしていると伝える言い方はどれか。','["楽しみにしています", "忙しいです", "疲れました", "眠いです"]'::jsonb,0,'「楽しみにしています」(menantikan dengan senang)は約束前の前向きな一言。','medium',NULL,'{"conversation"}',915043745);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kaiwa-Yakusoku.html','conversation','相手の予定に合わせると伝える言い方はどれか。','["いつでも大丈夫です", "いつもだめです", "いつも忙しいです", "いつも遅いです"]'::jsonb,0,'「いつでも大丈夫です」(kapan saja tidak masalah)で柔軟に合わせる意思を伝える。','medium',NULL,'{"conversation"}',1662141213);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Contoh-N2.html','general','「〜だけあって」の文は？','["予想外", "〜だけの理由がある・当然そうだ", "〜できない", "失望した"]'::jsonb,1,'だけあって=pantas saja ~; ada alasannya. プロだけあって上手い=pantas saja profesional, memang bagus. 予想通りの結果。','hard','N2','{"general", "n2"}',1805136762);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Contoh-N2.html','general','「〜た上で」の使い方は？','["〜する前に", "〜した後で・〜の結果を踏まえて", "〜しないで", "〜しながら"]'::jsonb,1,'〜た上で=setelah melakukan ~. 確認した上で返事する=setelah konfirmasi, baru balas. 順序を示す。','hard','N2','{"general", "n2"}',1884647816);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Contoh-N2.html','general','「〜からには」の意味は？','["〜する前に", "〜した以上は・〜だから当然(決意)", "〜しないために", "〜するかもしれない"]'::jsonb,1,'からには=karena sudah ~; mengingat ~(決意). 引き受けたからには最後までやる=karena sudah menerima, kerjakan sampai akhir。','hard','N2','{"general", "n2"}',1989311513);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Contoh-N2.html','general','「〜どころか」の意味は？','["〜だから", "〜はとんでもない・むしろ逆", "〜のために", "〜のように"]'::jsonb,1,'どころか=jauh dari ~; bukan ~, malah. 上手どころかまだ基本もできない=jauh dari mahir, dasar saja belum bisa。','hard','N2','{"general", "n2"}',110775748);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Contoh-N3.html','general','「〜にもかかわらず」はどんな文で使う？','["理由", "予想と反対の結果(逆接)", "目的", "条件"]'::jsonb,1,'にもかかわらず=meskipun ~. 忙しいにもかかわらず手伝う=meskipun sibuk, membantu. 期待・予想と反対の内容が続く。','medium','N3','{"general", "n3"}',1268690010);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Contoh-N3.html','general','「〜ためには」の意味は？','["〜のせいで", "〜の目的を達成するために必要な条件", "〜だから", "〜にもかかわらず"]'::jsonb,1,'〜ためには=untuk ~(目的+必要条件). 合格するためには努力が必要=untuk lulus, usaha diperlukan. 目的達成の条件を示す。','medium','N3','{"general", "n3"}',1536649358);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Contoh-N3.html','general','「〜に褒められた」の文法は？','["使役形", "受身形(〜される)", "可能形", "て形"]'::jsonb,1,'〜られた=受身(pasif). 先生に褒められた=dipuji oleh guru. 〜に=oleh siapa. 受身は第三者の行動が自分に影響する時に使う。','medium','N3','{"general", "n3"}',1835285800);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Contoh-N3.html','general','「〜と言われています」の意味は？','["自分が言う", "一般的にそう言われている・社会的な認識", "命令", "疑問"]'::jsonb,1,'〜と言われている=dikatakan bahwa ~; umumnya dipercaya. 「むずかしいと言われています」=dikatakan sulit. 客観的・社会的認識の表現。','medium','N3','{"general", "n3"}',990957553);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Kompleks.html','general','「昨日買った本」の「昨日買った」は？','["副詞", "名詞を修飾する関係節", "主節", "述語"]'::jsonb,1,'昨日買った=klausa relatif yang memodifikasi 本. 動詞+た+名詞=klausa relatif masa lalu dalam bahasa Jepang.','medium',NULL,'{"general"}',1469225845);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Kompleks.html','general','「彼が来ることを知った」の「〜こと」の役割は？','["形容詞", "副詞", "名詞節(動詞の目的語)", "条件節"]'::jsonb,2,'〜こと=klausa nominal. 「彼が来ること」全体が動詞「知った」の目的語になる。','medium',NULL,'{"general"}',113732306);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Kompleks.html','general','「見た」の前は「こと」と「の」どちら？','["こと", "の", "どちらでも", "どちらでもない"]'::jsonb,1,'知覚動詞(見る・聞く・感じる)の前は「の」。彼が来るのを見た(O)。×彼が来ることを見た(X)。','medium',NULL,'{"general"}',680331088);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Kompleks.html','general','「忙しくても」の文法は？','["条件", "譲歩(〜ても=逆接条件)", "理由", "時間"]'::jsonb,1,'〜ても=meskipun ~; 譲歩節. 忙しくても来てください=meskipun sibuk, tolong datang.','medium',NULL,'{"general"}',1921392985);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Kompleks.html','general','「雨なので」と「雨だから」の違いは？','["全く同じ", "のでは客観的理由、からは主観的/話し言葉的", "からは格式的", "のでは否定的"]'::jsonb,1,'〜ので=alasan objektif(lebih formal). 〜から=alasan subjektif/口語的. ビジネス/フォーマルでは「ので」が適切。','medium',NULL,'{"general"}',202298554);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Kompleks.html','general','複文で従属節の主語に使う助詞は？','["は", "も", "が", "を"]'::jsonb,2,'複文の従属節では「が」を使う。私は[彼が書いた]本を読んだ。主節=「は」、従属節=「が」が基本。','medium',NULL,'{"general"}',2005253601);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Kompleks.html','general','「勉強すれば合格できる」の条件形は？','["すれば=恒常条件", "すれば=仮定条件(〜ば形)", "すると=時間", "したら=完了後"]'::jsonb,1,'〜ば=仮定条件. 勉強すれば=kalau belajar. 普遍的条件・アドバイスに使う。','medium',NULL,'{"general"}',1940382725);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Kompleks.html','general','「〜てから」と「〜た後で」の違いは？','["全く同じ", "てからは直接連続、た後では間隔あり", "た後では直接", "どちらも同じ"]'::jsonb,1,'〜てから=langsung setelah ~(直接連続). 〜た後で=setelah ~ (間隔があってもよい). 食べてから寝る vs 食べた後で運動する.','medium',NULL,'{"general"}',455719278);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Kompleks.html','general','「彼が来るのが待ち遠しい」の「〜のが」は？','["関係節", "名詞節が主語", "副詞節", "条件節"]'::jsonb,1,'〜のが=名詞節+が(主語). 「彼が来るの」全体が主語になり、「待ち遠しい」の主語として機能する。','medium',NULL,'{"general"}',2065239546);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Kompleks.html','general','「〜ことはない」の意味は？','["〜したほうがいい", "〜する必要はない", "〜してはいけない", "〜できない"]'::jsonb,1,'〜ことはない=tidak perlu ~; tidak harus ~. 例:心配することはない=tidak perlu khawatir.','medium',NULL,'{"general"}',1799217707);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk-N2.html','general','「〜次第」の意味は？','["〜した後でいつか", "〜するとすぐに・〜したらすぐ", "〜したくない", "〜かもしれない"]'::jsonb,1,'〜次第(しだい)=segera setelah ~. 会議が終わり次第=segera setelah rapat selesai. 「〜したらすぐ」の丁寧・ビジネス版。','hard','N2','{"general", "n2"}',768216092);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk-N2.html','general','「〜を踏まえた上で」の意味は？','["〜を無視して", "〜を根拠・参考にして", "〜に反して", "〜のために"]'::jsonb,1,'〜を踏まえた上で=berdasarkan ~; setelah mempertimbangkan ~. 研究結果を踏まえた上で=berdasarkan hasil penelitian. 意思決定の根拠を示す。','hard','N2','{"general", "n2"}',1993453607);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk-N2.html','general','「〜の末に」の意味は？','["〜する前に", "長い〜の後にやっと", "すぐに", "〜のために"]'::jsonb,1,'〜の末に(すえに)=setelah panjang ~; akhirnya setelah. 長年の研究の末に=setelah penelitian bertahun-tahun. 努力・苦労の後の結果に使う。','hard','N2','{"general", "n2"}',2112545955);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk-N2.html','general','「〜にあたって」の意味は？','["〜の後に", "〜という重要な場面・機会に", "〜の前に", "〜と同時に"]'::jsonb,1,'〜にあたって=pada saat ~; dalam rangka ~(重要場面). 解決するにあたって=dalam rangka menyelesaikan. 改まった・重要な場面に使う。','hard','N2','{"general", "n2"}',899108985);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk.html','general','「安いし、おいしいし」の「〜し」の役割は？','["条件", "理由を並列に列挙", "時間の順序", "逆接"]'::jsonb,1,'〜し=daftar alasan paralel. 安い+おいしい+その他の理由を並べる。文末に判断・評価が来る。','medium',NULL,'{"general"}',1940691288);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk.html','general','「春になると花が咲く」の「〜と」で使えない後件は？','["自然現象", "意志・命令・依頼", "習慣", "発見"]'::jsonb,1,'〜と=後件に意志・命令・依頼が来てはいけない。×来ると行きましょう(NG)→〜たら/ばを使う。','medium',NULL,'{"general"}',1388348735);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk.html','general','「〜から」と「〜ので」の違いは？','["同じ", "から=口語的/主観的、ので=書き言葉的/客観的礼儀", "ので=口語的", "から=より丁寧"]'::jsonb,1,'〜から=口語的で直接的(自分の理由). 〜ので=客観的で丁寧(フォーマル・礼儀正しい理由). ビジネスでは「ので」が適切。','medium',NULL,'{"general"}',1455408754);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk.html','general','「帰ったら電話して」の「〜たら」の機能は？','["仮定の条件", "完了後の次の行動", "自然の法則", "前提条件"]'::jsonb,1,'〜たら=最も汎用的な条件形. 帰った(完了)+電話して(次の行動). 時間的順序にも仮定にも使える。','medium',NULL,'{"general"}',1315897501);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk.html','general','「日本に行くなら京都に寄って」の「〜なら」の特徴は？','["自然の法則", "相手の状況・発言を前提にした条件", "習慣", "発見"]'::jsonb,1,'〜なら=相手の情報・状況を受けた条件. 「日本に行く」という相手の計画を聞いてアドバイス。','medium',NULL,'{"general"}',236366838);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk.html','general','「〜て」の形の主な用法3つは？','["原因のみ", "継起(順序)・原因・手段", "条件・時間・逆接", "並列・転換・対比"]'::jsonb,1,'〜て=継起(起きて顔を洗う)・原因(転んでけがした)・手段(歩いて行く)の3つが主な用法。','medium',NULL,'{"general"}',1428227803);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kalimat-Majemuk.html','general','「春になれば花が咲く」の「〜ば」の用法は？','["特定の一回の仮定", "自然の法則・普遍的真理", "過去の条件", "前提条件"]'::jsonb,1,'〜ば=自然の法則・普遍的条件・アドバイス. 春→花は自然の帰結。勉強すれば合格できる=アドバイス。','medium',NULL,'{"general"}',901238445);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N1-Review.html','kanji','「払拭」の読み方と意味は？','["はらいぬぐい/拭く", "ふっしょく/完全に取り除く", "はいしょく/排除", "ふしょく/侵食"]'::jsonb,1,'払拭(ふっしょく)=menghapus tuntas. 不安を払拭する=menghilangkan kekhawatiran. N1頻出。払う+拭く=menghapus sampai bersih。','hard','N1','{"kanji", "n1"}',990442041);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N1-Review.html','kanji','「乖離」の意味は？','["一致", "大きなズレ・かけ離れていること", "改善", "発展"]'::jsonb,1,'乖離(かいり)=kesenjangan besar; menjauh. 理想と現実が乖離=idealisme dan kenyataan sangat berjauhan. N1重要語彙。','hard','N1','{"kanji", "n1"}',1567656006);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N1-Review.html','kanji','「逡巡」の意味は？','["決断する", "ためらう・迷う", "批判する", "急ぐ"]'::jsonb,1,'逡巡(しゅんじゅん)=ragu-ragu; bimbang. 逡巡することなく決断した=memutuskan tanpa ragu. 逡巡する=ためらう、hesitate。','hard','N1','{"kanji", "n1"}',1842043032);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N1-Review.html','kanji','「遵守する」の意味は？','["無視する", "規則・法律をきちんと守ること", "変更する", "批判する"]'::jsonb,1,'遵守(じゅんしゅ)=menaati dengan ketat; mematuhi. 法律を遵守する=menaati hukum. 「守る」より格式的・厳格な表現。','hard','N1','{"kanji", "n1"}',1434482269);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N1-Review.html','kanji','「潜在」と「顕在」の違いは？','["同じ", "潜在=隠れた力・表面に出ていない、顕在=すでに表れている", "どちらも明らか", "どちらも隠れた"]'::jsonb,1,'潜在(せんざい)=tersembunyi; laten. 顕在(けんざい)=nyata; tampak. 潜在的な才能=bakat tersembunyi. 顕在化する=menjadi terlihat/nyata。','hard','N1','{"kanji", "n1"}',15958979);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N2-Review.html','kanji','「矛盾」の読み方は？','["むじゅん", "ほうじゅん", "ぼうじゅん", "もじゅん"]'::jsonb,0,'矛盾(むじゅん)=kontradiksi; inconsistency. 矛=tombak, 盾=perisai. 矛で盾を突けるか？→kontradiksi. 矛盾する=bertentangan。','hard','N2','{"kanji", "n2"}',823174021);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N2-Review.html','kanji','「貢献する」の意味は？','["邪魔する", "役に立つ・力を尽くす", "批判する", "離れる"]'::jsonb,1,'貢献(こうけん)する=berkontribusi; berperan. 社会に貢献する=berkontribusi pada masyarakat. 会社への貢献=kontribusi pada perusahaan。','hard','N2','{"kanji", "n2"}',853853629);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N2-Review.html','kanji','「策定する」の意味は？','["壊す", "計画・方針を作り上げる", "確認する", "批判する"]'::jsonb,1,'策定(さくてい)する=merumuskan; menyusun. 計画を策定する=merumuskan rencana. 方針を策定する=merumuskan kebijakan. 政府・企業でよく使う。','hard','N2','{"kanji", "n2"}',823958908);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N2-Review.html','kanji','「担う」の読み方と意味は？','["になう/役割などを引き受ける", "かつぐ/重いものを持つ", "おこなう/行動する", "くるしむ/苦しい"]'::jsonb,0,'担う(になう)=memikul; mengemban. 重要な役割を担う=mengemban peran penting. 責任を担う=memikul tanggung jawab. 組織・社会でよく使う。','hard','N2','{"kanji", "n2"}',1821858553);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N2-Review.html','kanji','「施策」の意味は？','["計画の失敗", "具体的な政策・対策・措置", "感謝", "批判"]'::jsonb,1,'施策(しさく)=langkah kebijakan; measures. 具体的な施策=langkah konkret. 政府や企業の施策を検討する=mengkaji langkah-langkah kebijakan。','hard','N2','{"kanji", "n2"}',890423651);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N3-Review.html','kanji','「場合」の読み方は？','["じょうごう", "ばあい", "ばがい", "じょうばい"]'::jsonb,1,'場合(ばあい)=kasus; situasi; dalam hal. その場合=dalam kasus itu. 場合によっては=tergantung situasi. 最重要N3漢字の一つ。','medium','N3','{"kanji", "n3"}',531348314);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N3-Review.html','kanji','「努力」の意味は？','["記録", "頑張ること・力を尽くすこと", "目標", "変化"]'::jsonb,1,'努力(どりょく)=usaha; kerja keras. 努力する=berusaha keras. 努力が報われる=usaha terbayar. 学習で最も大切な漢字!','medium','N3','{"kanji", "n3"}',854112875);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N3-Review.html','kanji','「確認」の意味は？','["変更", "内容が正しいかどうかをチェックすること", "記録", "目標"]'::jsonb,1,'確認(かくにん)=konfirmasi; verifikasi. 確認する=mengecek/memverifikasi. ご確認ください=mohon dikonfirmasi. ビジネスで毎日使う。','medium','N3','{"kanji", "n3"}',766426763);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N3-Review.html','kanji','「発展」の意味は？','["後退", "進歩・成長すること", "変化", "記録"]'::jsonb,1,'発展(はってん)=perkembangan; kemajuan. 技術の発展=perkembangan teknologi. 発展途上国=negara berkembang. 発展する=berkembang。','medium','N3','{"kanji", "n3"}',1529390720);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N3-Review.html','kanji','「特定」の意味は？','["全部", "ある特別な一つ・特定のもの", "一般的", "同じ"]'::jsonb,1,'特定(とくてい)=spesifik; tertentu. 特定の人物=orang tertentu. 特定する=mengidentifikasi. 特定できない=tidak bisa mengidentifikasi。','medium','N3','{"kanji", "n3"}',359294493);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N4-Review.html','kanji','「必要」の読み方は？','["ひよう", "ひつよう", "ひっこう", "ひつこう"]'::jsonb,1,'必要(ひつよう)=perlu; diperlukan. 必要があります=ada keperluannya. 必要ない=tidak diperlukan. 日常会話で非常によく使う。','easy','N4','{"kanji", "n4"}',733969936);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N4-Review.html','kanji','「確認する」の意味は？','["変更する", "内容が正しいかチェックすること", "記録する", "目標を立てる"]'::jsonb,1,'確認(かくにん)する=mengecek; konfirmasi. ご確認ください=mohon dikonfirmasi. ビジネスや日常で毎日使う最重要漢字の一つ。','easy','N4','{"kanji", "n4"}',1298376739);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N4-Review.html','kanji','「提案する」の意味は？','["断る", "アイデアや計画を出すこと", "確認する", "報告する"]'::jsonb,1,'提案(ていあん)する=mengusulkan; menyarankan. 改善策を提案する=mengusulkan langkah perbaikan. ビジネスで必須。','easy','N4','{"kanji", "n4"}',1300968750);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N4-Review.html','kanji','「連絡」の意味は？','["旅行", "情報を伝えること・コンタクト", "記録", "調査"]'::jsonb,1,'連絡(れんらく)=kontak; kabar. 連絡してください=mohon dihubungi. ご連絡ありがとう=terima kasih sudah menghubungi. 最頻出N4漢字。','easy','N4','{"kanji", "n4"}',1464988403);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N4-Review.html','kanji','「相談する」の意味は？','["一人で決める", "話し合って意見や解決を求めること", "拒否する", "報告する"]'::jsonb,1,'相談(そうだん)する=berkonsultasi; membicarakan bersama. ご相談ください=silakan konsultasikan. 相談に乗る=mau mendengar dan membantu。','easy','N4','{"kanji", "n4"}',556707673);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N5-Review.html','kanji','「日本」の読み方は？','["にっぽん", "にほん", "ひもと", "じつぼん"]'::jsonb,1,'日本(にほん)=Jepang. 日(にち/ひ)=hari, matahari. 毎日(まいにち)=setiap hari. N5で最も基本的な漢字の一つ。','easy','N5','{"kanji", "n5"}',1796714310);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N5-Review.html','kanji','「水曜日」の意味は？','["Senin", "Selasa", "Rabu", "Kamis"]'::jsonb,2,'水曜日(すいようび)=Rabu. 水(すい/みず)=air. 曜日(ようび)=nama hari dalam seminggu. 7つの曜日漢字は全てN5必須。','easy','N5','{"kanji", "n5"}',1919307064);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N5-Review.html','kanji','「先生」の意味は？','["murid", "guru", "teman", "orang tua"]'::jsonb,1,'先生(せんせい)=guru; dosen. 先(せん/さき)=sebelum, depan. 生(せい/い.きる)=hidup, lahir. とても頻出の言葉。','easy','N5','{"kanji", "n5"}',846502270);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N5-Review.html','kanji','「外国」の読み方は？','["そとくに", "がいこく", "げこく", "がいごく"]'::jsonb,1,'外国(がいこく)=luar negeri. 外(がい/そと)=luar. 国(こく/くに)=negara. 外国人(がいこくじん)=orang asing。','easy','N5','{"kanji", "n5"}',1256523470);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N5-Review.html','kanji','「買う」の意味は？','["menjual", "membeli", "meminjam", "memberi"]'::jsonb,1,'買う(かう)=membeli. 買(ばい)=beli. 買い物(かいもの)=belanja. 日常会話で非常によく使う動詞。','easy','N5','{"kanji", "n5"}',1608563490);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N5-Review.html','kanji','「読む」の意味は？','["menulis", "melihat", "membaca", "mendengar"]'::jsonb,2,'読む(よむ)=membaca. 読(どく/とく)=baca. 読書(どくしょ)=membaca buku。N5必須動詞の一つ。','easy','N5','{"kanji", "n5"}',934002847);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N5-Review.html','kanji','「学校」の読み方は？','["がくこう", "がっこう", "がくえん", "しゅうこう"]'::jsonb,1,'学校(がっこう)=sekolah. 学(がく/まな.ぶ)=belajar. 校(こう)=sekolah/lembaga pendidikan. 小学校(しょうがっこう)=SD。','easy','N5','{"kanji", "n5"}',936130700);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-N5-Review.html','kanji','「四時」の意味は？','["jam satu", "jam dua", "jam tiga", "jam empat"]'::jsonb,3,'四時(よじ)=jam empat. 四(し/よん)=empat, dibaca 「よ」sebelum 時(じ). 数字の読み方の例外パターン、要暗記。','easy','N5','{"kanji", "n5"}',1284203201);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-Writing-Guide.html','kanji','漢字の筆順の基本「上から下へ」の例は？','["川(左から右)", "三(上横→中横→下横)", "人(左払い→右払い)", "日(外枠から)"]'::jsonb,1,'上から下が基本. 三=上の横から順に. ただし例外も多い. 正しい筆順で書くと文字のバランスが取れる。','medium',NULL,'{"kanji"}',1509313085);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-Writing-Guide.html','kanji','「口」のような四角いかんじはどの順で書く？','["中から外", "外枠(縦→上横)→中横→下横を閉じる", "右から左", "下から上"]'::jsonb,1,'囲む字=外から内へ. 口: 左縦→上横(右)→右縦→下横を閉じる. 田・国なども同じ原則. 内の画を入れてから下を閉じる。','medium',NULL,'{"kanji"}',1831867082);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-Writing-Guide.html','kanji','「八」のような左右払いの漢字はどの順？','["右払いから", "左払い→右払いの順", "同時", "順序なし"]'::jsonb,1,'左右払い=左から右へ. 八: 左払い→右払い. 人・入・文なども同じ. 左右対称の字は中央から. 小: 中縦→左→右。','medium',NULL,'{"kanji"}',323425239);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-Writing-Guide.html','kanji','「木」の筆順は？','["縦→横→払い", "横→縦→左払い→右払い", "払い→横→縦", "左払い→右払い→横→縦"]'::jsonb,1,'木: ①横(中央)→②縦(中央)→③左払い→④右払い. 横が先で縦が後. 本・末・林など木を含む字も同じ原則。','medium',NULL,'{"kanji"}',321005445);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kanji-Writing-Guide.html','kanji','筆順を正しく知る最大の利点は？','["テスト対策のみ", "文字のバランスが取れ・速く書け・覚えやすくなる", "関係ない", "伝統のため"]'::jsonb,1,'正しい筆順: バランスの良い文字になる+速く書ける+記憶に定着しやすい. 漢字検定(Kanji Kentei)でも筆順問題が出る。','medium',NULL,'{"kanji"}',1879529747);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Kerja-Dasar.html','general','食べる termasuk kelompok?','["Grup 1 (五段)", "Grup 2 (一段)", "Grup 3", "Bukan kata kerja"]'::jsonb,1,'食べる berakhiran -eru sehingga termasuk Grup 2 (ichidan/kata kerja -ru). Grup ini paling mudah dikonjugasi karena cukup membuang る dan menambahkan akhiran yang diinginkan.','medium',NULL,'{"general"}',360419387);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Kerja-Dasar.html','general','Bentuk ます dari 飲む adalah?','["飲ます", "飲みます", "飲むます", "飲めます"]'::jsonb,1,'飲みます. Untuk kata kerja Grup 1 (godan), akhiran -u diubah menjadi -i lalu ditambah ます. 飲む (nomu) → 飲み (nomi) → 飲みます.','medium',NULL,'{"general"}',2041402977);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Kerja-Dasar.html','general','Bentuk ます dari 食べる adalah?','["食べります", "食べます", "食べいます", "食べるます"]'::jsonb,1,'食べます. Untuk kata kerja Grup 2 (ichidan), cukup buang akhiran る lalu tambahkan ます. Ini salah satu alasan Grup 2 dianggap lebih mudah dipelajari pemula.','medium',NULL,'{"general"}',1556327261);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Kerja-Dasar.html','general','Kata kerja Grup 3 (tidak beraturan) ada berapa?','["1", "2 (する dan 来る)", "5", "Banyak"]'::jsonb,1,'Hanya ada 2: する (melakukan) dan 来る (datang). Keduanya harus dihafal terpisah karena konjugasinya tidak mengikuti pola Grup 1 maupun Grup 2 secara konsisten.','medium',NULL,'{"general"}',1779444355);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Kerja-Dasar.html','general','帰る (kaeru) termasuk kelompok?','["Grup 1 (pengecualian)", "Grup 2", "Grup 3", "Bukan kata kerja"]'::jsonb,0,'帰る adalah pengecualian penting — meski berakhiran -eru (seperti ciri Grup 2), kata ini sebenarnya termasuk Grup 1 (godan). Bentuk ますnya adalah 帰ります, bukan 帰えます.','medium',NULL,'{"general"}',177947996);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Kerja-Dasar.html','general','Bentuk ます dari 来る adalah?','["来ります", "来ます (kimasu)", "来るます", "くります"]'::jsonb,1,'来ます (kimasu). Perhatikan bahwa bunyi 来 berubah dari ''ku'' menjadi ''ki'' — salah satu ciri unik Grup 3 yang harus dihafal karena tidak mengikuti pola konjugasi biasa.','medium',NULL,'{"general"}',347613796);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Kerja-Dasar.html','general','Ciri kata kerja Grup 2 adalah?','["Berakhir -u", "Berakhir -iru atau -eru", "Berakhir -su", "Tidak beraturan"]'::jsonb,1,'Kata kerja Grup 2 (ichidan) umumnya berakhiran -iru atau -eru pada bentuk kamus, dan konjugasinya cukup dengan membuang る. Namun waspada karena ada pengecualian seperti 帰る dan 入る yang sebenarnya Grup 1.','medium',NULL,'{"general"}',726556927);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Kerja-Dasar.html','general','Bentuk ます dari 書く adalah?','["書います", "書きます", "書くます", "書けます"]'::jsonb,1,'書きます. Untuk Grup 1, akhiran -ku diubah menjadi -ki lalu ditambah ます: 書く (kaku) → 書き (kaki) → 書きます.','medium',NULL,'{"general"}',48081868);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Kerja-Dasar.html','general','する dipakai untuk membentuk kata kerja dari?','["Kata sifat", "Kata benda (勉強する)", "Kata kerja lain", "Partikel"]'::jsonb,1,'Kata benda + する membentuk kata kerja baru, contoh: 勉強する (belajar), 電話する (menelepon), 掃除する (membersihkan). Pola ini sangat produktif dalam bahasa Jepang modern.','medium',NULL,'{"general"}',34325985);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Kerja-Dasar.html','general','Mengapa penting mengenali kelompok kata kerja?','["Untuk pelafalan", "Karena menentukan cara konjugasi", "Untuk menulis kanji", "Tidak penting"]'::jsonb,1,'Kelompok kata kerja menentukan cara membentuk berbagai konjugasi seperti bentuk ます, bentuk-て, bentuk kamus negatif, dan lainnya. Tanpa mengenali kelompoknya, pembentukan kalimat akan sering salah, terutama untuk pengecualian seperti 帰る.','medium',NULL,'{"general"}',1774813788);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Sifat-Dasar.html','general','Manakah kata sifat-な?','["高い", "静か", "大きい", "新しい"]'::jsonb,1,'静か (shizuka, tenang) adalah kata sifat-な. Ciri utamanya: tidak berakhiran -i secara alami dan memerlukan partikel な saat menerangkan kata benda langsung, misalnya 静かな部屋 (kamar yang tenang).','medium',NULL,'{"general"}',1514857558);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Sifat-Dasar.html','general','Bentuk negatif dari 高い adalah?','["高くないです", "高じゃないです", "高でした", "高くでした"]'::jsonb,0,'高くないです. Untuk kata sifat-i, buang akhiran い lalu tambahkan くない. Pola ini konsisten untuk hampir semua kata sifat-i kecuali いい yang memiliki bentuk khusus (よくない).','medium',NULL,'{"general"}',1025170993);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Sifat-Dasar.html','general','Bentuk negatif dari 静か adalah?','["静かくないです", "静かじゃないです", "静かないです", "静かでした"]'::jsonb,1,'静かじゃないです (atau 静かではないです). Untuk kata sifat-な, bentuk negatifnya memakai じゃない, mirip konjugasi kata benda, bukan mengubah akhiran seperti kata sifat-i.','medium',NULL,'{"general"}',1534685568);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Sifat-Dasar.html','general','Bagaimana 静か menerangkan 部屋 (kamar)?','["静か部屋", "静かい部屋", "静かな部屋", "静かの部屋"]'::jsonb,2,'静かな部屋 (kamar yang tenang). Kata sifat-な memerlukan partikel な saat langsung menerangkan kata benda — berbeda dari kata sifat-i yang bisa langsung menempel tanpa partikel tambahan.','medium',NULL,'{"general"}',858459044);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Sifat-Dasar.html','general','綺麗 (kirei) adalah kata sifat jenis?','["Sifat-い", "Sifat-な", "Kata benda", "Kata kerja"]'::jsonb,1,'Ini jebakan umum! Meski 綺麗 berakhiran huruf い dalam romaji, sebenarnya ini adalah kata sifat-な (bukan -i). Contoh: 綺麗な花 (bunga yang cantik), bukan 綺麗い花.','medium',NULL,'{"general"}',1445455386);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Sifat-Dasar.html','general','Bentuk LAMPAU dari 高い adalah?','["高いでした", "高かったです", "高でした", "高くでした"]'::jsonb,1,'高かったです. Untuk kata sifat-i, buang い lalu tambahkan かった untuk bentuk lampau. Pola: 高い → 高かった (dulu/tadinya mahal).','medium',NULL,'{"general"}',274451464);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Sifat-Dasar.html','general','Bentuk LAMPAU dari 便利 adalah?','["便利かったです", "便利でした", "便利いでした", "便利くないです"]'::jsonb,1,'便利でした. Untuk kata sifat-な, bentuk lampaunya mirip kata benda: tambahkan でした setelah kata sifatnya. 便利 (praktis) → 便利でした (dulu praktis).','medium',NULL,'{"general"}',1059797646);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Sifat-Dasar.html','general','好き (suka) memakai partikel?','["を", "が", "に", "で"]'::jsonb,1,'好き adalah kata sifat-な yang unik karena memakai partikel が untuk objek yang disukai, bukan を. Contoh: 音楽が好きです (saya suka musik), bukan 音楽を好きです.','medium',NULL,'{"general"}',1306951064);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Sifat-Dasar.html','general','Lawan kata dari 大きい adalah?','["小さい", "高い", "安い", "新しい"]'::jsonb,0,'小さい (kecil) adalah lawan dari 大きい (besar). Kedua kata sifat-i ini adalah pasangan dasar paling umum dalam deskripsi ukuran benda atau tempat.','medium',NULL,'{"general"}',1862404918);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kata-Sifat-Dasar.html','general','"高い車" — 高い di sini menerangkan?','["Butuh な", "Langsung menerangkan benda", "Butuh の", "Salah"]'::jsonb,1,'高い langsung menerangkan 車 (mobil) tanpa perlu partikel tambahan, karena ini adalah ciri kata sifat-i — bisa langsung menempel pada kata benda yang diterangkannya (berbeda dari kata sifat-な yang butuh な).','medium',NULL,'{"general"}',1571752581);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Bisnis-Lanjut2.html','general','「いたしかねます」を使う場面は？','["同意する時", "丁寧に断る時(できない・しにくい)", "感謝する時", "質問する時"]'::jsonb,1,'いたしかねます=tidak bisa ~ (sangat sopan). いたす=謙譲語 untuk する. かねる=難しい・できない. 最も丁寧な断り方。','medium',NULL,'{"general"}',40739151);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Bisnis-Lanjut2.html','general','「前向きに検討させていただきます」の本当の意味は？','["絶対にする", "すぐ決める", "婉曲的な保留・遠回しなNO", "拒否する"]'::jsonb,2,'前向きに検討=akan dipertimbangkan secara positif. 日本ビジネスでは「即答しない・持ち帰る」婉曲表現としてよく使われる。','medium',NULL,'{"general"}',1162803344);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Bisnis-Lanjut2.html','general','「〜でございます」はどういう表現？','["普通の丁寧語", "〜です の最も丁寧な形(最敬語)", "命令形", "カジュアル"]'::jsonb,1,'でございます=bentuk paling sopan dari です. 顧客対応・公式場面で使用. 「こちらが商品でございます」。','medium',NULL,'{"general"}',895424238);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Bisnis-Lanjut2.html','general','「いかがでございましょうか」はどういう意味？','["どこですか", "どうですか(最敬語版・顧客への質問/提案)", "いつですか", "だれですか"]'::jsonb,1,'いかがでございましょうか=bagaimana (menurut Anda)? (最も丁寧). どうですか→いかがですか→いかがでございましょうか と段階が上がる。','medium',NULL,'{"general"}',294834694);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Bisnis-Lanjut2.html','general','「ご要望に沿えず」の意味は？','["要望に応えられた", "要望に応えることができなかった", "要望を聞いた", "要望を無視した"]'::jsonb,1,'ご要望に沿えず=tidak bisa memenuhi permintaan. 〜に沿う=sesuai dengan ~. 沿えず=tidak bisa memenuhi. 謝罪表現。','medium',NULL,'{"general"}',1424698798);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Email-Templates.html','general','ビジネスメールの書き出し「お世話になっております」はいつ使う？','["初めての相手", "継続的なビジネス関係の相手に毎回使う", "親友へ", "上司への報告"]'::jsonb,1,'お世話になっております=salam bisnis standar untuk hubungan berkelanjutan. 初めての相手には「はじめてご連絡差し上げます」を使う。','medium',NULL,'{"general"}',691115860);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Email-Templates.html','general','「ご検討のほどよろしくお願い申し上げます」の意味は？','["すぐ決めてください", "よく考えてみてくださいという丁寧なお願い", "断ってください", "急いでください"]'::jsonb,1,'ご検討のほど=yang mohon dipertimbangkan. 非常に丁寧な依頼表現. 決定を迫らず、相手のペースに任せる敬意ある表現。','medium',NULL,'{"general"}',468204263);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Email-Templates.html','general','お詫びメールで「ご容赦ください」の意味は？','["忘れてください", "どうかお許しください・大目に見てください", "怒ってください", "報告してください"]'::jsonb,1,'ご容赦(ごようしゃ)ください=mohon dimaafkan/diampuni. 容赦=pengampunan. 謝罪メールの結びによく使う最も丁寧な謝罪表現の一つ。','medium',NULL,'{"general"}',1906099599);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Email-Templates.html','general','「誠に申し訳ございません」と「すみません」の違いは？','["同じ", "誠に申し訳ございません=ビジネス・公式、すみません=カジュアル", "すみませんの方が丁寧", "どちらも使えない"]'::jsonb,1,'誠に申し訳ございません=sangat formal; dipakai di email bisnis/situasi serius. すみません=casual; untuk situasi ringan sehari-hari。','medium',NULL,'{"general"}',1536571918);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Email-Templates.html','general','「何かご不明な点がございましたら」の目的は？','["クレームを受ける", "相手が質問しやすいようにドアを開けておく丁寧な配慮", "終わりの挨拶", "急ぎの案件"]'::jsonb,1,'何かご不明な点がございましたら=jika ada yang kurang jelas. 相手に質問・確認しやすいよう促す. ビジネスメールの定型的な配慮表現。','medium',NULL,'{"general"}',1985839629);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Praktis.html','general','電話で相手が不在の時「ただいま席を外しております」の意味は？','["今休憩中", "今その場を離れています(不在)", "忙しい", "終業した"]'::jsonb,1,'席を外す=tidak ada di tempat; sedang pergi sebentar. よく使う丁寧表現。「ただいま外出しております」も似た意味。','medium',NULL,'{"general"}',379311287);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Praktis.html','general','丁寧に断る表現「いたしかねます」の意味は？','["できます", "できません(丁寧な断り)", "したいです", "確認します"]'::jsonb,1,'いたしかねます=tidak bisa ~ (penolakan sangat sopan). いたす=謙譲語 untuk する. 〜かねる=难以(できない).','medium',NULL,'{"general"}',1874946668);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Praktis.html','general','「前向きに検討させていただきます」は実際には？','["絶対OK", "婉曲的に「今すぐはYesと言えない」という意味", "絶対断り", "即答している"]'::jsonb,1,'前向きに検討=akan dipertimbangkan positif. 日本ビジネスでは「即断しない」「持ち帰る」婉曲的な表現としてよく使われる。','medium',NULL,'{"general"}',489474525);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Praktis.html','general','「ご迷惑をおかけし、誠に申し訳ございません」はどんな場面？','["感謝する", "何かミスや迷惑をかけた時の謝罪", "誘う", "依頼する"]'::jsonb,1,'誠に申し訳ございません=maaf yang sangat tulus. ご迷惑をおかけし=yang menyebabkan ketidaknyamanan. フォーマルな謝罪の定型文。','medium',NULL,'{"general"}',2004515389);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Praktis.html','general','「おかげさまで」の意味は？','["残念ながら", "あなたのおかげで(感謝)", "申し訳ないが", "確かに"]'::jsonb,1,'おかげさまで=berkat bantuan Anda; alhamdulillah. 謙虚さと感謝を同時に表す表現。おかげさまで無事に完了しました。','medium',NULL,'{"general"}',1596781568);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Praktis.html','general','メールの書き出し「平素よりお世話になっております」の使い方は？','["初めてのメール", "継続的なビジネス関係の相手への書き出し", "謝罪のメール", "断りのメール"]'::jsonb,1,'平素よりお世話になっております=Terima kasih selalu atas kerjasama. 継続的な取引先への標準的な書き出し。初めての場合は「はじめてご連絡いたします」。','medium',NULL,'{"general"}',39454833);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Keigo-Praktis.html','general','「ご指摘いただきありがとうございます」の「ご指摘」とは？','["ご挨拶", "指摘(問題点・改善点を示すこと)への感謝", "ご連絡", "ご質問"]'::jsonb,1,'指摘(してき)=menunjukkan masalah/poin perbaikan. ご指摘いただき=berkenan menunjukkan. 批判も感謝して受け取る日本のビジネス文化。','medium',NULL,'{"general"}',991600984);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Akademik.html','vocabulary','「仮説」の意味は？','["証明された事実", "まだ証明されていない推測・前提", "定理", "公式"]'::jsonb,1,'仮説(かせつ)=hipotesis. 仮説を立てる=membuat hipotesis. 仮説を検証する=memverifikasi hipotesis. 研究の出発点。','medium',NULL,'{"vocabulary"}',161967451);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Akademik.html','vocabulary','「考察」とは何ですか？','["実験の手順", "結果について深く分析・検討すること", "まとめ", "参考文献"]'::jsonb,1,'考察(こうさつ)=analisis mendalam; pertimbangan. 研究論文の「結果と考察」=Result & Discussion. なぜそうなったかを考える章。','medium',NULL,'{"vocabulary"}',1057391688);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Akademik.html','vocabulary','「客観的」と「主観的」の違いは？','["同じ", "客観的=個人の感情に左右されない、主観的=個人の判断・感情による", "客観的が正しい", "主観的が正しい"]'::jsonb,1,'客観的(きゃっかんてき)=objektif. 主観的(しゅかんてき)=subjektif. 学術文章では客観的な記述が求められる。','medium',NULL,'{"vocabulary"}',512954972);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Akademik.html','vocabulary','「前提」の意味は？','["結論", "議論・推論の出発点となる仮定や条件", "証拠", "例外"]'::jsonb,1,'前提(ぜんてい)=premis; asumsi dasar. 「この前提を共有した上で議論する」=berbagi premis sebelum berdebat. 論理的議論の基盤。','medium',NULL,'{"vocabulary"}',1708260332);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Akademik.html','vocabulary','「網羅的」の意味は？','["部分的", "全てをカバーしている・漏れがない", "概略的", "抽象的"]'::jsonb,1,'網羅的(もうらてき)=komprehensif; mencakup semua tanpa celah. 網羅的な文献調査=penelusuran literatur yang komprehensif。','medium',NULL,'{"vocabulary"}',1107718545);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Akademik.html','vocabulary','「相関」と「因果関係」の違いは？','["同じ", "相関=一緒に変化する傾向、因果=一方が他方の原因", "どちらも原因-結果", "どちらも無関係"]'::jsonb,1,'相関=korelasi(bergerak bersama, bukan berarti satu sebab lainnya). 因果=kausalitas(satu MENYEBABKAN yang lain). 統計では「相関は因果ではない」が重要原則。','medium',NULL,'{"vocabulary"}',1084980689);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Bisnis-N2.html','vocabulary','「稟議」の意味は？','["一人で決める", "上位者の順に承認を回すプロセス", "拒否する", "提案する"]'::jsonb,1,'稟議(りんぎ)=persetujuan hierarki Jepang. 稟議書を回す=mengedarkan dokumen persetujuan berjenjang. 日本の会社文化の核心。','hard','N2','{"vocabulary", "n2"}',1334281860);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Bisnis-N2.html','vocabulary','「根回し」とは？','["会議を開く", "正式決定前の非公式な事前調整", "報告する", "断る"]'::jsonb,1,'根回し(ねまわし)=lobi informal sebelum keputusan resmi. 日本のビジネスで非常に重要な文化的慣行。','hard','N2','{"vocabulary", "n2"}',300732705);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Bisnis-N2.html','vocabulary','「打診する」の意味は？','["決定する", "相手の意向を探る・可能性を確認する", "拒否する", "報告する"]'::jsonb,1,'打診(だしん)=menjajaki; menanyakan kemungkinan. 転職を打診された=ditanya kemungkinan pindah kerja.','hard','N2','{"vocabulary", "n2"}',1791870879);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Bisnis-N2.html','vocabulary','「裁量に任せる」の意味は？','["全部指示する", "自分で判断して決めていい", "禁止する", "相談する"]'::jsonb,1,'裁量(さいりょう)=diskresi; kewenangan memutuskan sendiri. 裁量に任せる=serahkan kebijakan padamu.','hard','N2','{"vocabulary", "n2"}',322277280);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Bisnis-N2.html','vocabulary','「周知する」の意味は？','["秘密にする", "広く知らせる・全員に伝える", "一人に伝える", "削除する"]'::jsonb,1,'周知(しゅうち)=sosialisasi; memberitahu semua pihak. 社内に周知する=sosialisasikan ke seluruh perusahaan.','hard','N2','{"vocabulary", "n2"}',144715945);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Bisnis-N2.html','vocabulary','「懸案事項」の意味は？','["解決済みの問題", "未解決のまま残っている課題", "新しい提案", "成功した案件"]'::jsonb,1,'懸案(けんあん)=pending issue; masalah yang belum terselesaikan. 懸案事項を解決する=menyelesaikan masalah yang tertunda.','hard','N2','{"vocabulary", "n2"}',778655212);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Cuaca-Musim.html','vocabulary','Apa arti 春 (haru)?','["Musim panas", "Musim semi", "Musim gugur", "Musim dingin"]'::jsonb,1,'春 (haru) berarti musim semi, musim ketika bunga sakura mekar di Jepang. Musim ini biasanya berlangsung dari Maret hingga Mei dan identik dengan suasana segar dan awal tahun ajaran baru.','medium',NULL,'{"vocabulary"}',1656979100);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Cuaca-Musim.html','vocabulary','Kata untuk "hujan" adalah?','["雪", "雨", "風", "雲"]'::jsonb,1,'雨 (ame) berarti hujan, sedangkan 雪 (yuki) berarti salju. Kedua kata ini sering dipakai bersama kata kerja 降る (turun): 雨が降る (hujan turun), 雪が降る (salju turun).','medium',NULL,'{"vocabulary"}',442317045);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Cuaca-Musim.html','vocabulary','Apa perbedaan 暑い dan 熱い (sama-sama "atsui")?','["Tidak ada beda", "暑い=udara, 熱い=benda", "暑い=benda, 熱い=udara", "暑い lebih panas"]'::jsonb,1,'暑い dipakai untuk cuaca/suhu udara yang panas (seperti musim panas), sedangkan 熱い dipakai untuk benda yang panas seperti makanan atau air. Meski pelafalannya sama, penulisan kanji-nya berbeda sesuai konteks.','medium',NULL,'{"vocabulary"}',950153637);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Cuaca-Musim.html','vocabulary','梅雨 (tsuyu) adalah?','["Musim salju", "Musim hujan panjang di awal musim panas", "Musim gugur", "Topan"]'::jsonb,1,'梅雨 = periode hujan panjang sekitar Juni, bukan musim resmi tapi penting.','medium',NULL,'{"vocabulary"}',1822532787);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Cuaca-Musim.html','vocabulary','Kata kerja yang dipakai untuk hujan/salju "turun" adalah?','["行く", "降る", "来る", "出る"]'::jsonb,1,'降る (furu) berarti turun, dipakai khusus untuk fenomena alam seperti hujan dan salju: 雨が降る (hujan turun), 雪が降る (salju turun). Kata kerja ini tidak dipakai untuk benda turun biasa.','medium',NULL,'{"vocabulary"}',1173591320);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Cuaca-Musim.html','vocabulary','"寒い" (samui) artinya?','["Panas", "Dingin (udara)", "Hangat", "Sejuk"]'::jsonb,1,'寒い berarti dingin, khusus untuk cuaca/suhu udara. Untuk benda yang dingin (seperti air atau makanan), digunakan kata berbeda yaitu 冷たい — perbedaan ini sering menjadi jebakan pembelajar.','medium',NULL,'{"vocabulary"}',715036527);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Cuaca-Musim.html','vocabulary','Apa arti 台風 (taifuu)?','["Angin sepoi", "Topan/taifun", "Petir", "Kabut"]'::jsonb,1,'台風 (taifuu) berarti topan/badai tropis, fenomena cuaca yang sering melanda Jepang terutama pada musim panas hingga awal musim gugur, kadang menyebabkan gangguan transportasi dan sekolah.','medium',NULL,'{"vocabulary"}',1670864004);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Cuaca-Musim.html','vocabulary','Untuk mengatakan "airnya dingin", kata yang tepat:','["お水が寒い", "お水が冷たい", "お水が涼しい", "お水が暑い"]'::jsonb,1,'冷たい dipakai untuk benda yang dingin seperti air (冷たい水). 寒い hanya dipakai untuk cuaca/suhu udara, bukan untuk benda — perbedaan penting yang sering tertukar oleh pembelajar pemula.','medium',NULL,'{"vocabulary"}',388249785);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Cuaca-Musim.html','vocabulary','"蒸し暑い" (mushiatsui) artinya?','["Dingin kering", "Panas lembap/gerah", "Sejuk", "Berangin"]'::jsonb,1,'蒸し暑い berarti panas dan lembap, ciri khas cuaca musim panas di Jepang terutama setelah musim hujan (梅雨) berakhir. Kondisi ini membuat udara terasa berat dan menyesakkan.','medium',NULL,'{"vocabulary"}',592909968);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Cuaca-Musim.html','vocabulary','Musim 秋 (aki) terkenal dengan?','["Bunga sakura", "Daun merah", "Salju", "Hujan terus"]'::jsonb,1,'秋 (aki) adalah musim gugur, terkenal dengan daun momiji yang berubah warna menjadi merah dan kuning keemasan. Musim ini biasanya berlangsung dari September hingga November dengan udara sejuk.','medium',NULL,'{"vocabulary"}',820718966);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Emosi.html','vocabulary','「悔しい」の意味は？','["嬉しい", "負けたり失敗した時の悔しさ・くやしさ", "悲しい", "怖い"]'::jsonb,1,'悔しい(くやしい)=menyesal; kesal gemas karena kalah/gagal. 「くやし涙」=air mata kesal. 怒りと悲しみが混じった感情。','medium',NULL,'{"vocabulary"}',1749740629);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Emosi.html','vocabulary','「切ない」の説明として正しいのは？','["楽しい", "悲しくて美しい・胸が締め付けられる複雑な感情", "怖い", "怒り"]'::jsonb,1,'切ない(せつない)=pilu; mengharukan secara menyedihkan. 別れや懐かしさで胸が痛む感情。英語のbittersweet に近い。','medium',NULL,'{"vocabulary"}',2031148478);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Emosi.html','vocabulary','「安堵」の意味は？','["不安", "心配が消えてほっとした感覚", "怒り", "驚き"]'::jsonb,1,'安堵(あんど)=lega setelah cemas. 無事だとわかり安堵した=merasa lega setelah tahu selamat. 安心 と似るが安堵の方が文語的。','medium',NULL,'{"vocabulary"}',716077243);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Emosi.html','vocabulary','「もどかしい」の意味は？','["満足", "うまくいかなくてイライラする・フラストレーション", "楽しい", "怖い"]'::jsonb,1,'もどかしい=frustrasi; tidak bisa mengungkapkan/melakukan seperti yang diinginkan. 言葉がうまく出てこなくてもどかしい=frustrasi tidak bisa berkata-kata.','medium',NULL,'{"vocabulary"}',1048276014);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Emosi.html','vocabulary','「羨ましい」と「妬ましい」の違いは？','["同じ", "羨ましい=iri positif(あの人みたいになりたい)、妬ましい=iri negatif(あの人が憎い)", "どちらも怒り", "どちらも悲しみ"]'::jsonb,1,'羨ましい=iri yang lebih positif(ingin seperti orang itu). 妬ましい(ねたましい)=iri yang lebih negatif/dengki. ニュアンスの差が重要。','medium',NULL,'{"vocabulary"}',251029024);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Emosi.html','vocabulary','「戸惑い」の意味は？','["喜び", "どうすべきか分からず困惑している状態", "確信", "安堵"]'::jsonb,1,'戸惑い(とまどい)=bingung tidak tahu harus berbuat apa. 急な変化に戸惑う=bingung menghadapi perubahan mendadak。','medium',NULL,'{"vocabulary"}',240417629);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Kaigo-N3.html','vocabulary','「申し送り」の意味は？','["報告書を書く", "シフト交代時に情報を次のスタッフに引き継ぐこと", "申請する", "送料を計算する"]'::jsonb,1,'申し送り(もうしおくり)=laporan serah terima shift. 前のシフトから次のシフトへの重要情報の引き継ぎ。','medium','N3','{"vocabulary", "n3"}',2070779458);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Kaigo-N3.html','vocabulary','「ケアカンファレンス」の目的は？','["家族への報告", "多職種が集まりケア方針を話し合う会議", "薬の管理", "給料の決定"]'::jsonb,1,'ケアカンファレンス=rapat multi-profesi untuk mendiskusikan rencana perawatan. 医師・看護師・介護士・PT/OT等が集まる。','medium','N3','{"vocabulary", "n3"}',1452121108);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Kaigo-N3.html','vocabulary','「廃用症候群」を引き起こす主な原因は？','["運動しすぎ", "長期臥床・不活動", "食事不足", "薬の副作用"]'::jsonb,1,'廃用症候群=disuse syndrome. 長期の不活動・臥床による筋力低下・関節拘縮・認知機能低下など。予防が最重要。','medium','N3','{"vocabulary", "n3"}',1603164871);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Kaigo-N3.html','vocabulary','「レスパイトケア」とは？','["最期のケア", "家族介護者の休息のための一時的なケア代替", "リハビリ", "感染対策"]'::jsonb,1,'レスパイトケア(respite care)=家族介護者の息抜き・休息のために一時的にケアを提供するサービス。ショートステイなど。','medium','N3','{"vocabulary", "n3"}',387172533);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Kaigo-N3.html','vocabulary','「褥瘡のDESIGN-R分類」の「D」は？','["Date(日付)", "Depth(深さ)", "Direction(方向)", "Diagnosis(診断)"]'::jsonb,1,'DESIGN-R=褥瘡の重症度評価ツール. D=Depth(深さ), E=Exudate(滲出液), S=Size(大きさ), I=Infection(感染), G=Granulation(肉芽), N=Necrotic(壊死組織), R=Recurrence(再発)。','medium','N3','{"vocabulary", "n3"}',1289219501);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Keluarga.html','vocabulary','Untuk menyebut ayah SENDIRI kepada orang lain, kata yang tepat:','["お父さん", "父", "パパ", "親父"]'::jsonb,1,'父 (chichi) dipakai untuk merendahkan/menyebut ayah sendiri saat berbicara dengan orang lain. Ini berbeda dari お父さん yang dipakai untuk menyebut ayah orang lain atau memanggil ayah sendiri langsung.','medium',NULL,'{"vocabulary"}',1037206314);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Keluarga.html','vocabulary','Untuk menanyakan ayah ORANG LAIN:','["父", "お父さん", "おじいさん", "息子"]'::jsonb,1,'お父さん (otousan) adalah bentuk hormat untuk menanyakan atau menyebut ayah orang lain. Bahasa Jepang punya dua set istilah keluarga: satu untuk keluarga sendiri (merendah), satu untuk keluarga orang lain (menghormat).','medium',NULL,'{"vocabulary"}',1728148545);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Keluarga.html','vocabulary','"母" (haha) artinya?','["Ibu saya", "Ibu Anda", "Nenek", "Kakak perempuan"]'::jsonb,0,'母 berarti ibu saya, digunakan dengan nada merendah saat bicara dengan orang lain tentang ibu sendiri. Untuk ibu orang lain, digunakan bentuk hormat お母さん (okaasan).','medium',NULL,'{"vocabulary"}',356814631);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Keluarga.html','vocabulary','Kakak laki-laki (keluarga sendiri) adalah?','["お兄さん", "兄", "弟", "父"]'::jsonb,1,'兄 (ani) berarti kakak laki-laki saya, dipakai saat membicarakan kakak sendiri kepada orang lain. Untuk kakak laki-laki orang lain, digunakan bentuk hormat お兄さん (oniisan).','medium',NULL,'{"vocabulary"}',1566191601);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Keluarga.html','vocabulary','Mengapa ada dua set kata keluarga?','["Formal vs kasual", "Merendah (sendiri) vs hormat (orang lain)", "Lama vs baru", "Tulis vs lisan"]'::jsonb,1,'Satu set kata dipakai untuk merendahkan anggota keluarga sendiri (父・母・兄・姉, dst) saat bicara dengan orang luar, sementara set lain dipakai untuk menghormati keluarga orang lain (お父さん・お母さん, dst) — mencerminkan budaya sopan santun (uchi-soto) dalam bahasa Jepang.','medium',NULL,'{"vocabulary"}',426107067);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Keluarga.html','vocabulary','"お姉さん" artinya?','["Adik perempuan", "Kakak perempuan (orang lain)", "Ibu", "Nenek"]'::jsonb,1,'お姉さん (oneesan) berarti kakak perempuan, dalam bentuk hormat. Bentuk ini dipakai untuk menyebut kakak perempuan orang lain, atau untuk memanggil kakak perempuan sendiri secara langsung.','medium',NULL,'{"vocabulary"}',1531961429);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Keluarga.html','vocabulary','Kata untuk "orang tua" (sendiri) adalah?','["ご両親", "両親", "家族", "兄弟"]'::jsonb,1,'両親 (ryoushin) berarti orang tua saya (kedua-duanya, ayah dan ibu). Untuk orang tua orang lain, digunakan bentuk hormat ご両親 (goryoushin) dengan tambahan awalan ご.','medium',NULL,'{"vocabulary"}',414158098);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Keluarga.html','vocabulary','"祖父" (sofu) artinya?','["Kakek saya", "Kakek Anda", "Ayah saya", "Paman"]'::jsonb,0,'祖父 berarti kakek saya, dipakai dengan nada merendah saat bicara dengan orang lain. Untuk kakek orang lain atau memanggil kakek sendiri, digunakan bentuk hormat おじいさん (ojiisan).','medium',NULL,'{"vocabulary"}',1693374502);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Keluarga.html','vocabulary','Saat MEMANGGIL ibu sendiri secara langsung, biasanya pakai:','["母", "お母さん", "ご家族", "両親"]'::jsonb,1,'Saat memanggil langsung, tetap pakai お母さん. 母 hanya untuk menyebut kepada orang lain.','medium',NULL,'{"vocabulary"}',2122711722);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Keluarga.html','vocabulary','"娘" (musume) artinya?','["Anak laki-laki", "Anak perempuan", "Adik", "Istri"]'::jsonb,1,'娘 berarti anak perempuan saya, sedangkan 息子 (musuko) berarti anak laki-laki saya. Kedua istilah ini dipakai dengan nada netral/merendah saat membicarakan anak sendiri kepada orang lain.','medium',NULL,'{"vocabulary"}',762390342);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Makanan.html','vocabulary','Apa arti ご飯 (gohan)?','["Roti", "Nasi/makanan", "Mi", "Sup"]'::jsonb,1,'ご飯 berarti nasi, tetapi juga sering dipakai secara umum untuk berarti ''makanan/santapan''. Contoh: ご飯を食べる bisa berarti ''makan nasi'' atau lebih luas ''makan (secara umum)''.','medium',NULL,'{"vocabulary"}',707213623);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Makanan.html','vocabulary','豚肉 (butaniku) adalah?','["Daging ayam", "Daging sapi", "Daging babi", "Ikan"]'::jsonb,2,'豚肉 berarti daging babi. Penting dikenali bagi pembelajar dengan pantangan makanan tertentu, karena sering muncul di menu restoran Jepang bersama 牛肉 (daging sapi) dan 鶏肉 (daging ayam).','medium',NULL,'{"vocabulary"}',1935380526);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Makanan.html','vocabulary','Apa arti 魚 (sakana)?','["Daging", "Ikan", "Telur", "Sayur"]'::jsonb,1,'魚 berarti ikan, salah satu bahan makanan pokok dalam masakan Jepang, terutama untuk sushi dan sashimi. Kata ini sering muncul bersama kata kerja 食べる (makan) dan 釣る (memancing).','medium',NULL,'{"vocabulary"}',712082228);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Makanan.html','vocabulary','Kata untuk "enak" adalah?','["まずい", "美味しい", "甘い", "辛い"]'::jsonb,1,'美味しい (oishii) berarti enak, kata sifat-i paling umum untuk memuji rasa makanan. Lawan katanya adalah まずい (tidak enak), meski jarang diucapkan langsung karena terkesan kasar.','medium',NULL,'{"vocabulary"}',1418970181);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Makanan.html','vocabulary','辛い (karai) artinya?','["Manis", "Asin", "Pedas", "Asam"]'::jsonb,2,'辛い berarti pedas. Lawan katanya adalah 甘い (amai, manis). Kedua kata sifat-i ini adalah pasangan dasar yang sering dipakai untuk mendeskripsikan rasa makanan di Jepang.','medium',NULL,'{"vocabulary"}',703137350);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Makanan.html','vocabulary','Kata kerja "minum" adalah?','["食べる", "飲む", "見る", "行く"]'::jsonb,1,'飲む (nomu) berarti minum, sedangkan 食べる (taberu) berarti makan. Kedua kata kerja dasar ini penting dibedakan karena termasuk kelompok kata kerja yang berbeda (Grup 1 dan Grup 2).','medium',NULL,'{"vocabulary"}',1748628018);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Makanan.html','vocabulary','お茶 (ocha) adalah?','["Kopi", "Teh", "Susu", "Air"]'::jsonb,1,'お茶 berarti teh, biasanya merujuk pada teh hijau (green tea) yang umum diminum di Jepang. Awalan お menunjukkan kesopanan dan kelaziman kata ini dalam percakapan sehari-hari.','medium',NULL,'{"vocabulary"}',368733567);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Makanan.html','vocabulary','Apa arti 野菜 (yasai)?','["Buah", "Sayuran", "Daging", "Bumbu"]'::jsonb,1,'野菜 berarti sayuran, sedangkan 果物 (kudamono) berarti buah-buahan. Kedua kategori makanan ini sering muncul bersama dalam percakapan tentang pola makan sehat.','medium',NULL,'{"vocabulary"}',665448700);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Makanan.html','vocabulary','鶏肉 (toriniku) adalah?','["Daging ayam", "Daging sapi", "Daging babi", "Telur"]'::jsonb,0,'鶏肉 berarti daging ayam, sedangkan 鶏 (tori) sendiri berarti ayam (hewannya). Perbedaan ini penting: kanji 肉 (niku) menunjukkan bahwa yang dimaksud adalah dagingnya, bukan hewannya secara utuh.','medium',NULL,'{"vocabulary"}',1667855925);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Makanan.html','vocabulary','Kata untuk "susu" adalah?','["水", "お茶", "牛乳", "コーヒー"]'::jsonb,2,'牛乳 (gyuunyuu) berarti susu sapi, kata paling umum untuk menyebut susu dalam bahasa Jepang sehari-hari. Kanji 牛 (sapi) dan 乳 (susu) menyusun kata majemuk ini.','medium',NULL,'{"vocabulary"}',1746507314);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N1-Review.html','vocabulary','「凌駕する」の意味は？','["下回る", "上回る・超える", "同じ", "失う"]'::jsonb,1,'凌駕(りょうが)=melampaui; menandingi. 先輩を凌駕する実力=kemampuan yang melampaui senior. 実力・成績について使う。','hard','N1','{"vocabulary", "n1"}',1388282581);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N1-Review.html','vocabulary','「払拭する」の意味は？','["増やす", "完全に取り除く・消し去る", "確認する", "批判する"]'::jsonb,1,'払拭(ふっしょく)=menghapus tuntas. 不安を払拭する=menghilangkan kekhawatiran sepenuhnya. ネガティブなものを完全に除去する。','hard','N1','{"vocabulary", "n1"}',326153423);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N1-Review.html','vocabulary','「蓋然性」の意味は？','["確実性", "ある事が起こる可能性・確からしさ", "重要性", "複雑さ"]'::jsonb,1,'蓋然性(がいぜんせい)=probabilitas; kemungkinan (akademis). 蓋然性が高い=probabilitasnya tinggi. 論文・公式文書での「可能性」の格式的表現。','hard','N1','{"vocabulary", "n1"}',2032371714);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N1-Review.html','vocabulary','「潜在的」と「顕在的」の違いは？','["同じ", "潜在的=隠れた・表面に出ていない、顕在的=すでに表れている", "どちらも同じ", "関係ない"]'::jsonb,1,'潜在(せんざい)=tersembunyi; laten(見えない). 顕在(けんざい)=nyata; tampak(見える). 潜在的な力=kemampuan tersembunyi. 顕在化する=menjadi nyata/terlihat。','hard','N1','{"vocabulary", "n1"}',1959957638);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N1-Tambahan.html','vocabulary','「忖度」の意味は？','["無視する", "上位者の意向・気持ちを推し量ること", "批判する", "提案する"]'::jsonb,1,'忖度(そんたく)=menebak keinginan/perasaan atasan. 日本の組織文化で重要な概念。','hard','N1','{"vocabulary", "n1"}',666430960);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N1-Tambahan.html','vocabulary','「齟齬が生じる」の意味は？','["一致する", "認識・理解にズレが生まれる", "解決する", "改善する"]'::jsonb,1,'齟齬(そご)=ketidaksesuaian; miskomunikasi. 両者の認識に齟齬が生じた=terjadi miskomunikasi antara keduanya。','hard','N1','{"vocabulary", "n1"}',1555258087);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N1-Tambahan.html','vocabulary','「俯瞰する」の意味は？','["細部を見る", "高い視点から全体を見渡す", "批判する", "比較する"]'::jsonb,1,'俯瞰(ふかん)=bird''s eye view; melihat dari atas. 全体を俯瞰して判断する=menilai dengan melihat gambaran besar.','hard','N1','{"vocabulary", "n1"}',27253179);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Bisnis.html','vocabulary','「根回し」とは何ですか？','["会議を開く", "正式決定前の非公式な事前調整・根固め", "報告する", "断る"]'::jsonb,1,'根回し(ねまわし)=lobi informal sebelum keputusan resmi. 日本のビジネス文化で非常に重要. 会議での驚きを避けるための準備。','hard','N2','{"vocabulary", "n2"}',254610286);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Lanjut.html','vocabulary','「必ずしも」の使い方は？','["必ずそうだ", "〜とは限らない(否定と一緒に)", "たまにそう", "常にそう"]'::jsonb,1,'必ずしも=belum tentu. 必ず+しも(強調)→否定文と一緒に使う. 必ずしも正しいとは限らない=belum tentu benar。','hard','N2','{"vocabulary", "n2"}',921343095);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Lanjut.html','vocabulary','「かえって」の意味は？','["同じ結果", "期待と反対の結果・むしろ逆", "いつも", "すぐに"]'::jsonb,1,'かえって=malah; justru. 助けようとしてかえって邪魔になった=mencoba membantu malah jadi penghalang. 逆の結果。','hard','N2','{"vocabulary", "n2"}',651557343);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Lanjut.html','vocabulary','「到底」の使い方は？','["〜できる", "〜できない(否定文必須)", "たぶん", "すぐに"]'::jsonb,1,'到底=sama sekali tidak(必ず否定文). 到底理解できない=sama sekali tidak mengerti. 到底〜できない/無理だ。','hard','N2','{"vocabulary", "n2"}',1094574737);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Lanjut.html','vocabulary','「あいにく」の意味は？','["幸いなことに", "残念ながら・タイミングが悪く", "すぐに", "必ず"]'::jsonb,1,'あいにく=sayangnya; malang. あいにく本日は休業です=sayangnya hari ini tutup. 相手の期待に応えられない残念な状況。','hard','N2','{"vocabulary", "n2"}',1748640788);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Lanjut.html','vocabulary','「著しく」の意味は？','["少し", "目立って大きく・劇的に", "普通に", "ゆっくり"]'::jsonb,1,'著しく(いちじるしく)=secara menonjol; sangat signifikan. 成績が著しく改善した=nilai meningkat secara signifikan.','hard','N2','{"vocabulary", "n2"}',978997093);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Lanjut.html','vocabulary','「さも」の使い方は？','["本当にそう", "まるで〜かのように(比喩的)", "少し", "たまに"]'::jsonb,1,'さも=seolah-olah; tampak sangat. さも知っているかのように話した=bicara seolah-olah tahu. 実際はそうでない場合が多い。','hard','N2','{"vocabulary", "n2"}',553667740);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Review.html','vocabulary','「曖昧」の意味は？','["明確", "はっきりしない・不明瞭", "简单", "複雑"]'::jsonb,1,'曖昧(あいまい)=ambigu; tidak jelas. 曖昧な返事=jawaban yang tidak jelas. 反対: 明確(めいかく)=jelas。','hard','N2','{"vocabulary", "n2"}',1693900919);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Tambahan.html','vocabulary','「懸念」の意味は？','["希望", "心配・気がかり", "計画", "結果"]'::jsonb,1,'懸念(けねん)=kekhawatiran; kecemasan. 懸念が高まる=kekhawatiran meningkat. 懸念を示す=menunjukkan kekhawatiran.','hard','N2','{"vocabulary", "n2"}',1225677616);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Tambahan.html','vocabulary','「把握する」の意味は？','["無視する", "よく理解して掌握する", "批判する", "推測する"]'::jsonb,1,'把握(はあく)=pemahaman; penguasaan. 状況を把握する=memahami situasi. 全体像を把握する=memahami gambaran keseluruhan.','hard','N2','{"vocabulary", "n2"}',1395032288);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Tambahan.html','vocabulary','「顕著」の意味は？','["目立たない", "はっきり目立つ・著しい", "普通", "少し"]'::jsonb,1,'顕著(けんちょ)=menonjol; nyata; jelas. 顕著な成果=hasil yang menonjol. 顕著な差=perbedaan yang jelas.','hard','N2','{"vocabulary", "n2"}',1583550413);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Tambahan.html','vocabulary','「端的に」の意味は？','["長々と", "ずばり・簡潔に要点を言う", "慎重に", "遠回しに"]'::jsonb,1,'端的に(たんてきに)=secara langsung; singkat dan jelas. 端的に言えば=singkatnya; langsung saja. 遠回し表現の反対。','hard','N2','{"vocabulary", "n2"}',666325504);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Tambahan.html','vocabulary','「徹底した」の意味は？','["不完全な", "完全で妥協のない", "簡単な", "少しの"]'::jsonb,1,'徹底した(てってい)=menyeluruh; tanpa kompromi. 徹底した調査=investigasi menyeluruh. 徹底的に=secara menyeluruh.','hard','N2','{"vocabulary", "n2"}',2057497908);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Tambahan.html','vocabulary','「模索する」の意味は？','["見つけた", "探し求める・試行錯誤する", "あきらめる", "確認する"]'::jsonb,1,'模索(もさく)=mencari-cari; menjajaki. 解決策を模索する=menjajaki solusi. まだ答えが見えない状態で探すニュアンス。','hard','N2','{"vocabulary", "n2"}',1534143676);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N2-Tambahan.html','vocabulary','「包括的」の意味は？','["部分的", "全てを含む・網羅的", "具体的", "個別の"]'::jsonb,1,'包括的(ほうかつてき)=komprehensif; mencakup semua. 包括的な対策=langkah komprehensif. 反意: 部分的=parsial.','hard','N2','{"vocabulary", "n2"}',1941459077);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N3-Review.html','vocabulary','「当然」の意味は？','["たぶん", "あたりまえ・もちろん", "もしかしたら", "まれに"]'::jsonb,1,'当然(とうぜん)=sewajarnya; tentu saja; sudah semestinya. 当然の結果=hasil yang wajar. 当然だ=sudah seharusnya begitu。','medium','N3','{"vocabulary", "n3"}',132723122);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N3-Review.html','vocabulary','「原因」と「結果」の関係は？','["同じ", "原因がなければ結果もない(因果関係)", "関係ない", "どちらも同じ"]'::jsonb,1,'原因(げんいん)=sebab. 結果(けっか)=akibat. 原因→結果 の順番. 「〜が原因で〜という結果になった」。','medium','N3','{"vocabulary", "n3"}',1091729335);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N3-Review.html','vocabulary','「機会」の意味は？','["機械", "チャンス・タイミング", "問題", "原因"]'::jsonb,1,'機会(きかい)=kesempatan; peluang. 機会を活かす=memanfaatkan kesempatan. 機械(きかい)=mesin — 発音同じだが漢字と意味が違う!','medium','N3','{"vocabulary", "n3"}',1807969587);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N3-Review.html','vocabulary','「影響を与える」の意味は？','["影を作る", "何かに作用・変化をもたらす", "光を当てる", "助ける"]'::jsonb,1,'影響を与える(えいきょうをあたえる)=memberikan pengaruh/dampak. 悪影響=dampak negatif. 良い影響=dampak positif。','medium','N3','{"vocabulary", "n3"}',717748191);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N3-Review.html','vocabulary','「将来」と「未来」の違いは？','["同じ", "将来=より現実的な近い未来、未来=広く遠い未来", "将来は過去", "未来は現在"]'::jsonb,1,'将来=masa depan yang realistis/dekat(将来の夢・将来の計画). 未来=masa depan yang lebih jauh/konseptual(未来の技術). ニュアンスの差。','medium','N3','{"vocabulary", "n3"}',1517936428);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N3-Tambahan.html','vocabulary','「影響」の読み方と意味は？','["えいきょう=pengaruh/dampak", "かんけい=hubungan", "じょうきょう=situasi", "げんいん=sebab"]'::jsonb,0,'影響(えいきょう)=pengaruh; dampak. 環境が健康に影響する=lingkungan mempengaruhi kesehatan.','medium','N3','{"vocabulary", "n3"}',651355043);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N3-Tambahan.html','vocabulary','「手段」の意味は？','["目的", "方法・やり方", "結果", "原因"]'::jsonb,1,'手段(しゅだん)=cara; metode; sarana. 目的のための手段=sarana untuk tujuan. 例:最善の手段を選ぶ=pilih cara terbaik.','medium','N3','{"vocabulary", "n3"}',1539846605);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N3-Tambahan.html','vocabulary','「判断」の意味は？','["実行する", "決めて評価すること", "質問する", "知る"]'::jsonb,1,'判断(はんだん)=penilaian; keputusan. 自分で判断する=memutuskan sendiri. 正しい判断=keputusan yang tepat.','medium','N3','{"vocabulary", "n3"}',1870475954);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N3-Tambahan.html','vocabulary','「禁止」の意味は？','["許可", "してはいけないこと", "要求", "規則"]'::jsonb,1,'禁止(きんし)=larangan; dilarang. 喫煙禁止=larangan merokok. 禁止する=melarang. 反対: 許可(きょか)=izin.','medium','N3','{"vocabulary", "n3"}',1708510870);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N3-Tambahan.html','vocabulary','「解決」の意味は？','["問題を複雑にする", "問題を解くこと・終わらせること", "問題を見つける", "問題を増やす"]'::jsonb,1,'解決(かいけつ)=penyelesaian; solusi. 問題を解決する=menyelesaikan masalah. 解決策=solusi. 未解決=belum terpecahkan.','medium','N3','{"vocabulary", "n3"}',1291615443);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N4-Review.html','vocabulary','「状況」の意味は？','["問題", "今の様子・状態", "結果", "原因"]'::jsonb,1,'状況(じょうきょう)=situasi; keadaan. 状況を確認する=memastikan situasi. 状況に応じて=sesuai situasi。','easy','N4','{"vocabulary", "n4"}',1874504749);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N4-Review.html','vocabulary','「経験」と「技術」の違いは？','["同じ", "経験=過去に体験したこと、技術=習得した能力・スキル", "どちらも同じ", "技術が先"]'::jsonb,1,'経験(けいけん)=pengalaman(体験). 技術(ぎじゅつ)=keahlian/skill(能力). 経験を積んで技術を身につける=dari pengalaman, skill berkembang。','easy','N4','{"vocabulary", "n4"}',984698684);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N4-Review.html','vocabulary','「成功」と「失敗」の反対は？','["同じ", "成功↔失敗(反対の意味)", "どちらも良い", "どちらも悪い"]'::jsonb,1,'成功(せいこう)=sukses ↔ 失敗(しっぱい)=gagal. 成功を祝う=merayakan keberhasilan. 失敗を糧にする=belajar dari kegagalan。','easy','N4','{"vocabulary", "n4"}',641535029);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N4-Review.html','vocabulary','「目標」の意味は？','["現在の状況", "将来達成したいゴール", "過去のこと", "問題"]'::jsonb,1,'目標(もくひょう)=target; sasaran. 目標を設定する=menetapkan target. 目標に向かって努力する=berusaha menuju target。','easy','N4','{"vocabulary", "n4"}',1850875839);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N5-Review.html','vocabulary','「明日」の読み方は？','["みょうにち", "あした", "あす", "明日"]'::jsonb,1,'明日(あした)=besok. 丁寧な場面では「あす」や「みょうにち」も使う. あした が最も一般的な口語表現。','easy','N5','{"vocabulary", "n5"}',1459814768);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N5-Review.html','vocabulary','「午前」と「午後」の違いは？','["同じ", "午前=AM(0-12時)、午後=PM(12-24時)", "午前=夜", "午後=朝"]'::jsonb,1,'午前(ごぜん)=AM(12時前). 午後(ごご)=PM(12時以降). 12時=正午(しょうご). 2時間後=2時間後(にじかんご)。','easy','N5','{"vocabulary", "n5"}',1026929595);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N5-Review.html','vocabulary','「高い」はどんな意味がある？','["安い", "値段が高い・位置が高い(2つの意味)", "低い", "小さい"]'::jsonb,1,'高い(たかい)=2つの意味: ①値段が高い=mahal ②位置・高さが高い=tinggi. 文脈で判断する. 反対: 安い(やすい)・低い(ひくい)。','easy','N5','{"vocabulary", "n5"}',394235316);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-N5-Review.html','vocabulary','「先週」の意味は？','["来週", "この週", "先週=지난 주=minggu lalu", "先々週"]'::jsonb,2,'先週(せんしゅう)=minggu lalu. 今週(こんしゅう)=minggu ini. 来週(らいしゅう)=minggu depan. 先=前/過去 のイメージ。','easy','N5','{"vocabulary", "n5"}',1467093387);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Profesi.html','vocabulary','会社員 (kaishain) artinya?','["Pelajar", "Karyawan perusahaan", "Guru", "Dokter"]'::jsonb,1,'会社員 berarti karyawan perusahaan, salah satu jawaban paling umum saat ditanya pekerjaan di Jepang. 会社 berarti perusahaan, dan 員 menunjukkan anggota/pegawai dari suatu organisasi.','medium',NULL,'{"vocabulary"}',503412108);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Profesi.html','vocabulary','Perbedaan 看護師 dan 介護士?','["Sama saja", "看護師=perawat medis, 介護士=careworker", "看護師=dokter", "介護士=pelajar"]'::jsonb,1,'看護師 (kangoshi) adalah perawat medis yang bekerja di rumah sakit dan menangani perawatan kesehatan, sedangkan 介護士 (kaigoshi) adalah pekerja perawatan lansia yang fokus pada bantuan hidup sehari-hari, bukan tindakan medis.','medium',NULL,'{"vocabulary"}',1293463148);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Profesi.html','vocabulary','先生 (sensei) artinya?','["Pelajar", "Guru/dosen", "Dokter", "Sopir"]'::jsonb,1,'先生 = guru/dosen. Juga dipakai untuk dokter dan profesi terhormat lain.','medium',NULL,'{"vocabulary"}',1308546790);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Profesi.html','vocabulary','Bagaimana menanyakan "Apa pekerjaan Anda?"','["お名前は何ですか", "お仕事は何ですか", "お国はどこですか", "お歳はいくつですか"]'::jsonb,1,'お仕事は何ですか berarti ''apa pekerjaan Anda?''. 仕事 berarti pekerjaan, dan menambahkan お di depannya membuat pertanyaan terdengar lebih sopan dibanding hanya 仕事は何ですか.','medium',NULL,'{"vocabulary"}',1196687690);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Profesi.html','vocabulary','"銀行で働いています" artinya?','["Saya pergi ke bank", "Saya bekerja di bank", "Saya punya bank", "Saya di depan bank"]'::jsonb,1,'[tempat]で働いています berarti ''bekerja di [tempat]''. Kalimat ini berarti ''saya bekerja di bank''. Partikel で menunjukkan lokasi tempat aktivitas bekerja berlangsung.','medium',NULL,'{"vocabulary"}',1944702841);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Profesi.html','vocabulary','医者 (isha) adalah?','["Perawat", "Dokter", "Apoteker", "Pasien"]'::jsonb,1,'医者 berarti dokter. Kata ini sering dipakai bersama 先生 sebagai sebutan hormat: お医者さん, terutama saat berbicara langsung dengan atau tentang seorang dokter.','medium',NULL,'{"vocabulary"}',267559470);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Profesi.html','vocabulary','学生 (gakusei) artinya?','["Guru", "Pelajar/mahasiswa", "Karyawan", "Pegawai negeri"]'::jsonb,1,'学生 berarti pelajar/mahasiswa, istilah umum untuk siapa saja yang sedang menempuh pendidikan formal, baik di sekolah menengah maupun perguruan tinggi.','medium',NULL,'{"vocabulary"}',1667913669);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Profesi.html','vocabulary','運転手 (untenshu) adalah?','["Koki", "Sopir", "Polisi", "Petani"]'::jsonb,1,'運転手 berarti sopir/pengemudi. 運転する berarti mengemudi (kata kerja), sedangkan 運転手 adalah orang yang melakukan pekerjaan tersebut sebagai profesi.','medium',NULL,'{"vocabulary"}',129437407);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Profesi.html','vocabulary','Kata kerja "bekerja" adalah?','["勉強する", "働く", "行く", "食べる"]'::jsonb,1,'働く (hataraku) berarti bekerja, kata kerja Grup 1 (godan) yang paling umum dipakai untuk menyatakan aktivitas bekerja dalam konteks profesi maupun pekerjaan sehari-hari.','medium',NULL,'{"vocabulary"}',1898239479);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Profesi.html','vocabulary','公務員 (koumuin) artinya?','["Pegawai negeri", "Karyawan swasta", "Pengusaha", "Pengangguran"]'::jsonb,0,'公務員 berarti pegawai negeri/PNS, orang yang bekerja untuk instansi pemerintah. Profesi ini di Jepang dianggap stabil dan sering menjadi pilihan populer karena jaminan kerja jangka panjang.','medium',NULL,'{"vocabulary"}',1451301902);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Tubuh-Kesehatan.html','vocabulary','Apa arti 頭 (atama)?','["Tangan", "Kepala", "Kaki", "Mata"]'::jsonb,1,'頭 (atama) berarti kepala. Kata ini sering muncul dalam keluhan kesehatan seperti 頭が痛い (kepala sakit/pusing), salah satu keluhan paling umum dalam percakapan medis dasar.','medium',NULL,'{"vocabulary"}',31799164);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Tubuh-Kesehatan.html','vocabulary','Bagaimana mengatakan ''perut saya sakit''?','["頭が痛いです", "お腹が痛いです", "足が痛いです", "目が痛いです"]'::jsonb,1,'お腹が痛いです (onaka ga itai desu) berarti ''perut saya sakit''. Pola ini [bagian tubuh] + が痛いです adalah struktur dasar untuk menyatakan rasa sakit di bagian tubuh tertentu.','medium',NULL,'{"vocabulary"}',1371961431);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Tubuh-Kesehatan.html','vocabulary','''熱があります'' artinya?','["Saya batuk", "Saya demam", "Saya pusing", "Saya lelah"]'::jsonb,1,'熱があります berarti ''saya demam''. 熱 berarti panas/demam, dan pola ～があります dipakai untuk menyatakan keberadaan suatu gejala atau kondisi pada tubuh.','medium',NULL,'{"vocabulary"}',446274396);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Tubuh-Kesehatan.html','vocabulary','Apa arti 手 (te)?','["Kaki", "Tangan", "Telinga", "Leher"]'::jsonb,1,'手 (te) berarti tangan, sedangkan 足 (ashi) berarti kaki. Kedua kata dasar anggota tubuh ini sering muncul bersama dalam percakapan tentang cedera atau pemeriksaan kesehatan.','medium',NULL,'{"vocabulary"}',868358841);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Tubuh-Kesehatan.html','vocabulary','''看護師'' (kangoshi) artinya?','["Dokter", "Perawat", "Pasien", "Apoteker"]'::jsonb,1,'看護師 berarti perawat medis yang bekerja merawat pasien di fasilitas kesehatan, sedangkan 医者 berarti dokter yang mendiagnosis dan menentukan pengobatan.','medium',NULL,'{"vocabulary"}',329419105);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Tubuh-Kesehatan.html','vocabulary','Ungkapan ''めまいがします'' berarti?','["Saya mual", "Saya pusing (berputar)", "Saya batuk", "Saya demam"]'::jsonb,1,'めまいがします berarti ''pusing/kepala berputar''. Ungkapan ini penting dikenali dalam konteks perawatan karena bisa menjadi tanda berbagai kondisi kesehatan yang perlu diperhatikan.','medium',NULL,'{"vocabulary"}',1934504209);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Tubuh-Kesehatan.html','vocabulary','Kata 痛い (itai) berarti?','["Lelah", "Sakit/nyeri", "Sehat", "Dingin"]'::jsonb,1,'痛い (itai) berarti sakit/nyeri, kata sifat-i dasar untuk menyatakan rasa sakit. Dipakai dengan pola [bagian tubuh]+が痛い, contoh: 頭が痛い (kepala sakit), 歯が痛い (gigi sakit).','medium',NULL,'{"vocabulary"}',976177258);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Tubuh-Kesehatan.html','vocabulary','Bagaimana menanyakan ''ada apa/kenapa?'' ke pasien?','["どうしましたか", "いくらですか", "どこですか", "なんですか"]'::jsonb,0,'どうしましたか (dou shimashita ka) berarti ''ada apa/kenapa?'', pertanyaan standar yang diucapkan tenaga medis/perawat untuk menanyakan keluhan awal pasien.','medium',NULL,'{"vocabulary"}',447393791);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Tubuh-Kesehatan.html','vocabulary','Apa arti 薬 (kusuri)?','["Rumah sakit", "Obat", "Dokter", "Sakit"]'::jsonb,1,'薬 (kusuri) berarti obat. Kata kerja yang sering menyertainya adalah 飲む: 薬を飲む berarti ''minum obat'', meski dalam bahasa Indonesia biasanya dikatakan ''makan obat''.','medium',NULL,'{"vocabulary"}',1070959905);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Tubuh-Kesehatan.html','vocabulary','''ゆっくり休んでください'' artinya?','["Minum obat", "Istirahatlah pelan-pelan", "Pergi ke dokter", "Makan yang banyak"]'::jsonb,1,'ゆっくり休んでください berarti ''istirahatlah pelan-pelan/dengan tenang''. Ungkapan ini sering diucapkan sebagai bentuk perhatian kepada seseorang yang sedang sakit atau kelelahan.','medium',NULL,'{"vocabulary"}',2099901911);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Warna.html','vocabulary','Apa arti 赤い (akai)?','["Biru", "Merah", "Kuning", "Hitam"]'::jsonb,1,'赤い berarti merah, salah satu kata sifat-i dasar untuk warna. Sebagian besar nama warna dalam bahasa Jepang bisa berakhiran -i dan berfungsi sebagai kata sifat-i langsung.','medium',NULL,'{"vocabulary"}',405412511);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Warna.html','vocabulary','Manakah yang BENAR untuk "mobil hijau"?','["緑い車", "緑の車", "緑車", "緑な車"]'::jsonb,1,'緑の車 adalah bentuk yang benar. Karena 緑 (hijau) adalah kata benda (bukan kata sifat-i), diperlukan partikel の untuk menghubungkannya dengan kata benda lain yang diterangkan.','medium',NULL,'{"vocabulary"}',1870866689);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Warna.html','vocabulary','Mengapa 緑い SALAH?','["Ejaannya keliru", "緑 kata benda, tak punya bentuk-い", "Terlalu formal", "Hanya untuk benda"]'::jsonb,1,'緑 hanya berfungsi sebagai kata benda, bukan kata sifat-i, sehingga tidak bisa langsung ditambah い untuk menerangkan benda. Warna yang berbentuk kata sifat-i sejati misalnya 赤い, 青い, 黒い, 白い.','medium',NULL,'{"vocabulary"}',681248759);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Warna.html','vocabulary','青信号 (aoshingou) sebenarnya berwarna?','["Biru", "Hijau", "Merah", "Kuning"]'::jsonb,1,'Lampu hijau lalu lintas di Jepang disebut 青信号 (secara harfiah ''sinyal biru''), meski warnanya sebenarnya hijau. Ini adalah kekhasan budaya bahasa Jepang yang mengelompokkan sebagian warna hijau ke dalam kategori 青 (biru).','medium',NULL,'{"vocabulary"}',1006005162);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Warna.html','vocabulary','Bentuk kata benda dari 白い adalah?','["白", "白の", "白い", "白色"]'::jsonb,0,'白 (shiro). Untuk mengubah kata sifat-i warna menjadi kata benda, cukup buang akhiran い: 白い (putih, sifat) → 白 (putih, benda), dipakai misalnya dalam 白のシャツ (kemeja putih).','medium',NULL,'{"vocabulary"}',1022505254);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Warna.html','vocabulary','Apa arti 紫 (murasaki)?','["Cokelat", "Ungu", "Abu-abu", "Oranye"]'::jsonb,1,'紫 berarti ungu, dan merupakan kata benda (bukan kata sifat-i), sehingga memerlukan partikel の saat menerangkan benda lain, contoh: 紫の花 (bunga ungu).','medium',NULL,'{"vocabulary"}',2123576971);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Warna.html','vocabulary','Warna yang BISA jadi kata sifat-i adalah?','["緑", "ピンク", "黒い", "オレンジ"]'::jsonb,2,'黒い (hitam) adalah kata sifat-i sejati yang bisa langsung menerangkan benda tanpa partikel tambahan. Sebaliknya, 緑 (hijau), ピンク (pink), dan オレンジ (oranye) adalah kata benda yang memerlukan partikel の.','medium',NULL,'{"vocabulary"}',1537205239);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Warna.html','vocabulary','Apa arti 茶色い (chairoi)?','["Hitam", "Cokelat", "Abu-abu", "Hijau"]'::jsonb,1,'茶色い berarti cokelat, secara harfiah berasal dari 茶 (teh) + 色 (warna) + い (akhiran sifat-i). Kata ini adalah salah satu warna yang meski merupakan kata majemuk, tetap berfungsi sebagai kata sifat-i.','medium',NULL,'{"vocabulary"}',535422738);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Warna.html','vocabulary','青りんご artinya?','["Apel biru", "Apel hijau", "Apel merah", "Apel busuk"]'::jsonb,1,'青りんご berarti apel hijau. Ini adalah contoh lain di mana kata 青 (yang secara harfiah berarti biru) dipakai untuk beberapa hal berwarna hijau dalam bahasa Jepang, mirip dengan 青信号.','medium',NULL,'{"vocabulary"}',969652623);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Kosakata-Warna.html','vocabulary','Bagaimana mengatakan "bunga ungu"?','["紫い花", "紫の花", "紫花", "紫な花"]'::jsonb,1,'紫の花 adalah bentuk yang benar. Karena 紫 (ungu) adalah kata benda, diperlukan partikel の untuk menghubungkannya dengan kata benda lain yang diterangkan, dalam hal ini 花 (bunga).','medium',NULL,'{"vocabulary"}',1057387109);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-Advanced.html','listening','N2 Listeningで「でも、やっぱり〜」の後は？','["無視してよい", "正解になることが多い(最初の発言が変更される)", "また変わる", "関係ない"]'::jsonb,1,'でも・やっぱり・いや・実は=perubahan pendapat. 日本語会話では最初の発言を後で修正することが多い。この後が正解の場合が多い。','medium',NULL,'{"listening"}',1047430297);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-Advanced.html','listening','「ただし」が出たらどうする？','["無視する", "条件・例外が来るのでメモする", "話題が変わる", "強調される"]'::jsonb,1,'ただし=namun; tapi(条件・例外). この後に重要な例外情報が来る。メモに「例外」などと記録する。','medium',NULL,'{"listening"}',915011630);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-Advanced.html','listening','「この後どうしますか」の問題の攻略法は？','["最初の発言に注目", "最後の行動指示・決定事項に注目", "感情を重視", "全部の発言を覚える"]'::jsonb,1,'次の行動=最後の決定・指示. 「〜してから〜する」の順序を正確に把握する。途中で変更される場合は最終決定を。','medium',NULL,'{"listening"}',1714992526);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-Advanced.html','listening','シャドーイングの主な目的は？','["記憶力向上", "発音・リズム・速度を身体で覚える", "文法の習得", "単語の暗記"]'::jsonb,1,'シャドーイング=音声の直後に繰り返す練習. 発音・イントネーション・速度が自然に身につく最も効果的なリスニング練習法。','medium',NULL,'{"listening"}',1165743734);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-Advanced.html','listening','概要理解問題で最重要なのは？','["全ての単語を理解する", "テーマ・主張・結論を把握する", "細かい数字を覚える", "全部訳す"]'::jsonb,1,'概要理解=main idea. 全部理解しようとせず、テーマ・話者の主張・結論にフォーカスする。','medium',NULL,'{"listening"}',1994260142);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N1.html','listening','「ちょっと難しいかもしれません」の本当の意味は？','["まだ検討中", "実質的に断っている", "了解した", "賛成している"]'::jsonb,1,'N1頻出の婉曲表現。「難しい」は日本語のビジネス会話で「できない・やりたくない」の遠回しな言い方。直接的なNoを避ける文化的配慮。','hard','N1','{"listening", "n1"}',2105657358);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N1.html','listening','統合理解問題で最も重要なことは？','["一人の意見だけ覚える", "誰がどの立場で何を主張しているか整理する", "音声を一度だけ聞く", "結論だけ聞く"]'::jsonb,1,'統合理解=複数の話者の意見を比較する問題。誰が(who)・何を(what)主張しているかをメモしながら聞くのが鉄則。','hard','N1','{"listening", "n1"}',1218890728);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N1.html','listening','Bさんが「ありがたいお話なんですが…」と言った後の展開は？','["喜んで引き受ける", "やんわりと断る前置き", "怒っている", "質問している"]'::jsonb,1,'「ありがたいお話ですが」は感謝を示しつつ断る定番の前置き表現。N1では文の途中で意図を予測する力が求められる。','hard','N1','{"listening", "n1"}',937520098);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N1.html','listening','「行けたら行きます」という返答が示すニュアンスは？','["必ず行く", "曖昧で、実際には行かない可能性もある", "絶対に行かない", "今すぐ決める"]'::jsonb,1,'条件付きの曖昧な返事は、日本語コミュニケーションにおいて婉曲な拒否や消極的な態度を示すことが多い。文脈で判断が必要。','hard','N1','{"listening", "n1"}',1014444426);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N1.html','listening','N1聴解で「間（ま）」（沈黙・ためらい）が示すことは？','["何も意味しない", "話者が同意していない、または迷っているサイン", "音声トラブル", "次の話題への移行"]'::jsonb,1,'日本語コミュニケーションでは沈黙自体が意味を持つ。即答しない「間」は、躊躇・不同意・遠慮を示唆することが多い。','hard','N1','{"listening", "n1"}',1670306745);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N1.html','listening','N1聴解攻略で最も効果的な学習法は？','["スクリプトだけ読む", "ニュース・討論番組をディクテーションしながら聞く", "単語帳だけ覚える", "字幕付きアニメだけ見る"]'::jsonb,1,'N1は自然な速度・婉曲表現への対応力が必要。NHKニュースや討論番組を使ったディクテーション（書き取り）練習が最も効果的。','hard','N1','{"listening", "n1"}',1512001317);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N2.html','listening','N2聴解「即時応答」のコツは？','["全文を聞いてから考える", "文末の表現に注目し最も自然な返答を素早く選ぶ", "選択肢を先に読む", "最初の単語だけ聞く"]'::jsonb,1,'即時応答: 文末(〜ませんか/〜てください/〜でしょうか)が鍵. 状況を即座に判断. 選択肢はない(直接答える)ので、聞きながら頭の中で準備。','hard','N2','{"listening", "n2"}',1961284390);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N2.html','listening','「ただし」「ただ」が聞こえた後に来るのは？','["まとめ", "例外・条件・制限", "追加情報", "本音"]'::jsonb,1,'ただし/ただ=tapi; kecuali(例外・条件). ただし予約が必要=tapi perlu reservasi. 聞こえたら「制限・条件」が来ると予測して集中!','hard','N2','{"listening", "n2"}',1545680100);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N2.html','listening','「実を言うと」が聞こえた後に注意すべき理由は？','["文法的に重要", "本音・重要情報・予想外の事実が来ることが多い", "まとめが来る", "終わりに近い"]'::jsonb,1,'実を言うと/実は=本音が来るサイン. 今まで言わなかった重要情報が来る. ポイント理解では特に重要な答えの手がかりになることが多い。','hard','N2','{"listening", "n2"}',1845976245);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N2.html','listening','N2聴解「課題理解」で最も重要なことは？','["最初に答えを決める", "最後に何をするかに集中し、途中で答えを決めない", "全部の詳細を記憶する", "選択肢を無視する"]'::jsonb,1,'課題理解: 会話の中で予定が変わることが多い. 最終的に何をするかが答え. 途中で決めると間違える. 「じゃ〜しよう」「そうしましょう」が最終決定のサイン。','hard','N2','{"listening", "n2"}',918138108);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N2.html','listening','「やはり/やっぱり」が聞こえた時に注意すべきことは？','["無視してよい", "意見・行動が最終的な判断に変わるサイン", "最初の決定が確定", "別の話題になる"]'::jsonb,1,'やはり/やっぱり=akhirnya; ternyata. 最初の意見から最終判断への変化を示す. ポイント理解・課題理解で答えが変わるタイミングに頻出。','hard','N2','{"listening", "n2"}',1823146181);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N3.html','listening','N3聴解「課題理解」では何を聞き取る？','["主人公の感情", "この後、誰が何をするか(行動・タスク)", "場所の名前", "時代背景"]'::jsonb,1,'課題理解=pemahaman tugas. 誰が・何を・いつ・どのように行動するかを正確に聞き取る。特に最後の指示や決定に注目。','medium','N3','{"listening", "n3"}',839242244);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N3.html','listening','N3聴解で選択肢を先に読む理由は？','["時間を節約するため", "聞くべきポイントが事前に分かるため", "記憶力を使うため", "なんとなく"]'::jsonb,1,'選択肢先読み=聞くべきことが分かる. ポイント理解問題では特に有効。音声前に選択肢を読んで、重要情報にフォーカスできる。','medium','N3','{"listening", "n3"}',483836246);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N3.html','listening','「概要理解」問題で最重要なのは？','["全ての単語を理解する", "話の主テーマや話者の主張", "細かい数字", "固有名詞"]'::jsonb,1,'概要理解=garis besar. 詳細ではなく全体のテーマ・話者の気持ち・主張を把握する。全部分からなくても概要が掴めれば正解できる。','medium','N3','{"listening", "n3"}',2020779975);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N3.html','listening','「発話表現」問題の攻略法は？','["丁寧な言葉を選ぶ", "状況・関係性に合った自然な反応を選ぶ", "一番長い選択肢を選ぶ", "最初の選択肢を選ぶ"]'::jsonb,1,'発話表現=respons natural. 状況(フォーマル/カジュアル)・関係性(上下/友人)に合った自然な反応を選ぶ。不自然な表現は×。','medium','N3','{"listening", "n3"}',197188198);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N3.html','listening','N3聴解で最も効果的な練習方法は？','["テキストを読む", "毎日少しずつ実際の音声を聞く", "単語を暗記する", "文法だけ勉強する"]'::jsonb,1,'リスニングは積み重ね。毎日NHK Web Easy・日本語ドラマ・アニメなどを聴く習慣が最重要。シャドーイングも効果的。','medium','N3','{"listening", "n3"}',1940380664);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N4.html','listening','Dialog 1で、二人は最終的に何時に会いますか？','["10時", "11時", "12時", "9時"]'::jsonb,1,'最初10時が提案されたが「ちょっと早い」と言われ、最終的に11時に変更された。最後の合意内容を聞き取るのがポイント。','easy','N4','{"listening", "n4"}',348233137);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N4.html','listening','Dialog 2で、客が注文した飲み物は？','["ホットコーヒー", "アイスコーヒー", "紅茶", "ジュース"]'::jsonb,1,'「アイスでお願いします」と答えている。ホットかアイスか、という選択肢への返答を正確に聞き取る。','easy','N4','{"listening", "n4"}',1916973661);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N4.html','listening','Dialog 3で、傘売り場は何階にありますか？','["1階", "2階", "3階", "4階"]'::jsonb,2,'「傘は3階にございます」と店員が案内している。「ございます」は「あります」の丁寧形。','easy','N4','{"listening", "n4"}',1553882390);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N4.html','listening','先生に質問したいとき、適切な言い方は？','["質問する？", "質問してもいいですか", "質問しろ", "質問しなさい"]'::jsonb,1,'「〜てもいいですか」=bolehkah saya~. 目上の人には丁寧な許可求め表現を使う。タメ口は失礼にあたる。','easy','N4','{"listening", "n4"}',59682457);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N4.html','listening','「〜ませんか」の使い方として正しいのは？','["命令するとき", "相手を誘うとき", "謝るとき", "質問に答えるとき"]'::jsonb,1,'〜ませんか=ajakan sopan. 「会いませんか」「行きませんか」など、相手を何かに誘う時に使う丁寧な表現。','easy','N4','{"listening", "n4"}',197624535);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Listening-N4.html','listening','N4聴解で「即時応答」問題のコツは？','["長く考えてから答える", "瞬時にパターンで反応する練習をする", "全部メモする", "無視する"]'::jsonb,1,'即時応答=respons cepat. 質問パターン（誰・いつ・どこ・なぜ）への自然な返答を瞬時に判断する練習が重要。','easy','N4','{"listening", "n4"}',1443414101);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Na-Adjective.html','general','「静かな部屋」の「な」の役割は？','["助詞", "形容動詞が名詞を修飾する時の接続形", "動詞", "副詞"]'::jsonb,1,'〜な+N=na-adjective modifying a noun. 静かな部屋=kamar yang tenang. I-adjective: 大きい部屋(なは不要).','medium',NULL,'{"general"}',1360200789);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Na-Adjective.html','general','「きれい」はna形容動詞？i形容詞？','["i形容詞(きれい+い)", "na形容動詞(きれいな)", "どちらでもない", "両方"]'::jsonb,1,'きれい=na形容動詞! 見た目はiで終わるが語幹なので注意。きれいな=修飾, きれいに=副詞, きれいで=て形.','medium',NULL,'{"general"}',2034594082);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Na-Adjective.html','general','Na-adjectiveのte-form(〜て)は？','["〜くて", "〜で", "〜にて", "〜だて"]'::jsonb,1,'Na-adjective te-form=〜で. 静かで気持ちがいい=tenang dan nyaman. I-adj te-form=〜くて: 広くて明るい。','medium',NULL,'{"general"}',696114169);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Na-Adjective.html','general','「好きじゃない」の文体は？','["フォーマル", "カジュアル/口語", "書き言葉", "文語"]'::jsonb,1,'じゃない=口語的否定. 好きではない=より丁寧. 好きじゃない=casual. 試験・フォーマルでは「では」が適切。','medium',NULL,'{"general"}',893025877);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Na-Adjective.html','general','「親切にしてください」の「親切に」は？','["名詞", "形容動詞の副詞形(〜に)", "動詞", "接続詞"]'::jsonb,1,'親切に=na-adjective adverbial form. 〜にする=make it ~; act ~. 親切にする=berlaku baik; berbuat baik.','medium',NULL,'{"general"}',163274912);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-Bisnis.html','general','「てきぱき」の意味は？','["ゆっくり丁寧に", "効率よく素早く", "ためらいながら", "大声で"]'::jsonb,1,'てきぱき=cekatan; efisien; gesit. てきぱきと仕事をこなす=menyelesaikan pekerjaan dengan cekatan. ビジネスで高く評価される態度。','medium',NULL,'{"general"}',792210593);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-Bisnis.html','general','「きちんと」と「ちゃんと」の違いは？','["同じ意味", "きちんと=より丁寧・書き言葉的、ちゃんと=口語的", "ちゃんと=より丁寧", "全く違う意味"]'::jsonb,1,'きちんと=formal/丁寧. ちゃんと=casual/口語. 例:きちんとご報告します(フォーマル) vs ちゃんとやって(カジュアル).','medium',NULL,'{"general"}',330525519);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-Bisnis.html','general','「はきはき」した話し方とは？','["小声でゆっくり", "大きな声で明瞭に答える", "早口で話す", "敬語を使う"]'::jsonb,1,'はきはき menggambarkan cara bicara yang jelas, tegas, dan tidak ragu-ragu. Dalam konteks bisnis, はきはきとした受け答え (menjawab dengan tegas dan jelas) dianggap penting karena menunjukkan kepercayaan diri dan profesionalisme saat berkomunikasi dengan atasan atau klien.','medium',NULL,'{"general"}',1986898030);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-Bisnis.html','general','「こつこつ」はどんな態度？','["やる気がない", "諦めずに地道に続ける", "急いで仕上げる", "他人まかせにする"]'::jsonb,1,'こつこつ=tekun; ulet; tidak menyerah. こつこつと努力する=berusaha dengan tekun tanpa menyerah.','medium',NULL,'{"general"}',1229461347);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-Bisnis.html','general','「そつなくこなす」の意味は？','["失敗することなく上手に処理する", "そつを作って仕事をする", "ゆっくり仕事をする", "適当にやる"]'::jsonb,0,'そつなく=tanpa kesalahan; tanpa cacat. そつなくこなす=menangani dengan mulus tanpa kesalahan. N1レベルの表現。','medium',NULL,'{"general"}',618826737);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-Bisnis.html','general','「てんてこ舞い」の状況は？','["暇で困っている", "とても忙しくて大変", "楽しく踊っている", "のんびりしている"]'::jsonb,1,'てんてこ舞い=sangat sibuk; pontang-panting. 例:年末はてんてこ舞いです=akhir tahun sibuk sekali.','medium',NULL,'{"general"}',186048463);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-Bisnis.html','general','「つつがなく」の意味は？','["問題が起きた", "トラブルなく順調に", "ゆっくりと", "急いで"]'::jsonb,1,'つつがなく=tanpa hambatan; dengan selamat; lancar. 式がつつがなく終わる=upacara selesai dengan lancar. フォーマルな表現。','medium',NULL,'{"general"}',174859593);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-Bisnis.html','general','「ぬかりなく」の意味は？','["準備を怠りなく完璧に", "適当に", "慌てて", "遅れずに"]'::jsonb,0,'ぬかりなく=tanpa kelengahan; dengan teliti. ぬかりなく準備する=mempersiapkan dengan sangat teliti. 抜かり(ぬかり)=kelengahan/kecerobohan。','medium',NULL,'{"general"}',1568849229);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-N1.html','general','「うやうやしく」の意味は？','["乱暴に", "非常に丁寧に・恭しく", "急いで", "悲しんで"]'::jsonb,1,'うやうやしく=dengan sangat hormat; penuh kesopanan. うやうやしく頭を下げた=membungkuk dengan sangat hormat.','hard','N1','{"general", "n1"}',1982296520);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-N1.html','general','「おずおず」の意味は？','["勢いよく", "ためらいながら・恐る恐る", "怒りながら", "楽しみながら"]'::jsonb,1,'おずおず=dengan ragu-ragu; maju mundur karena takut/malu. おずおずと手を挙げた=mengangkat tangan dengan ragu.','hard','N1','{"general", "n1"}',564158560);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-N1.html','general','「ぐっすり」とはどんな状態？','["少し眠い", "ぐっすり=熟睡している", "眠れない", "夢を見ている"]'::jsonb,1,'ぐっすり=tidur nyenyak/pulas. ぐっすり眠れた=bisa tidur nyenyak. Berlawanan: うとうと=setengah tidur.','hard','N1','{"general", "n1"}',85171264);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-N1.html','general','「くたくた」の意味は？','["元気いっぱい", "疲れ果てている", "眠い", "空腹だ"]'::jsonb,1,'くたくた=kelelahan total; exhausted. 仕事でくたくたになった=kelelahan total karena pekerjaan. cf.へとへと=bahkan lebih lelah.','hard','N1','{"general", "n1"}',298766040);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-N1.html','general','「ぽかん」とはどんな表情？','["怒った顔", "理解できずに口が開いた顔", "笑顔", "悲しい顔"]'::jsonb,1,'ぽかん=terbengong; mulut terbuka terkejut atau tidak mengerti. ぽかんと口を開けた=mulut ternganga.','hard','N1','{"general", "n1"}',2045722502);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-N1.html','general','「ひそひそ」の使い方は？','["大声で話す", "小声でこっそり話す", "急いで話す", "正式に話す"]'::jsonb,1,'ひそひそ=bisik-bisik; suara pelan pelan. ひそひそ話す=berbisik. cf.ぼそぼそ=bergumam tidak jelas.','hard','N1','{"general", "n1"}',1297030973);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-N1.html','general','「じっと」の意味は？','["素早く動く", "動かずに静かにいる・視線を固定する", "慌てて", "繰り返し"]'::jsonb,1,'じっと=diam tak bergerak; menatap tanpa berkedip. じっと見る=menatap terus. じっとしている=tidak bergerak.','hard','N1','{"general", "n1"}',1316370651);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Onomatopoeia-N1.html','general','「うっとり」の意味は？','["怖い", "美しいものや感動で心が引き込まれる", "怒っている", "急いでいる"]'::jsonb,1,'うっとり=terpesona; terhanyut oleh keindahan. うっとりするほど美しい=begitu indah sampai terpesona.','hard','N1','{"general", "n1"}',779117491);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Particle-Guide-Advanced.html','general','「私にとって」の意味は？','["私の代わりに", "私の立場から見ると・私にとっては", "私によって", "私のために"]'::jsonb,1,'にとって=bagi ~; dari sudut pandang ~. 私にとって日本語は夢の言語=Bagi saya, bahasa Jepang adalah bahasa impian.','medium',NULL,'{"general"}',204007736);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Particle-Guide-Advanced.html','general','「において」と「で」の違いは？','["同じ", "において=フォーマル・書き言葉、で=日常的", "どちらも書き言葉", "どちらも日常的"]'::jsonb,1,'において=フォーマル. ビジネスにおいて=dalam bisnis(文章語). ビジネスで=di bisnis(日常語). 文体で使い分ける。','medium',NULL,'{"general"}',312904351);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Particle-Guide-Advanced.html','general','「30年にわたって研究した」の「にわたって」の意味は？','["30年の間に", "30年という長い期間全体を通じて", "30年前に", "30年後に"]'::jsonb,1,'にわたって=sepanjang ~; meliputi(広い範囲・期間全体). 30年にわたる研究=penelitian yang berlangsung 30 tahun penuh.','medium',NULL,'{"general"}',1893684561);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Particle-Guide-Advanced.html','general','「年齢に関わらず」の意味は？','["年齢によって変わる", "年齢に関係なく", "年齢のために", "年齢と一緒に"]'::jsonb,1,'に関わらず=terlepas dari ~; tidak peduli ~. 年齢に関わらず参加できる=bisa berpartisipasi terlepas dari usia.','medium',NULL,'{"general"}',1735552754);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Passive-Causative.html','general','「書く」の受身形は？','["書れる", "書かれる", "書きれる", "書けれる"]'::jsonb,1,'書く(Grup 1)の受身=書か+れる=書かれる. Grup 1: ない形の語幹+れる. 書く→書かない→書か+れる。','medium',NULL,'{"general"}',1633641615);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Passive-Causative.html','general','「食べる」の使役形は？','["食べれる", "食べらせる", "食べさせる", "食べせる"]'::jsonb,2,'食べる(Grup 2)の使役=食べ+させる=食べさせる. Grup 2: 語幹+させる. 見る→見させる。','medium',NULL,'{"general"}',1380526122);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Passive-Causative.html','general','「私は先生にほめられた」の文の種類は？','["直接受身", "間接受身", "持ち主受身", "使役"]'::jsonb,0,'直接受身=pasif langsung. 田中さんは先生にほめられた=Tanaka dipuji guru. 受ける人が主語に。','medium',NULL,'{"general"}',519386073);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Passive-Causative.html','general','「私は雨に降られた」の意味と種類は？','["直接受身(私が雨を降らせた)", "間接受身(私は雨が降って迷惑した)", "持ち主受身", "非情受身"]'::jsonb,1,'間接受身=pasif tidak langsung. 雨が降る=tidak ada objek, tapi私は被害を受けた. 被害・迷惑の受身。','medium',NULL,'{"general"}',1319162985);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Passive-Causative.html','general','「子供にご飯を食べさせた」の「に」の用法は？','["強制的に食べさせた", "許可して/自由に食べさせた", "禁止した", "頼んだ"]'::jsonb,1,'に+使役=許可. 子供に食べさせた=membiarkan anak makan. を+使役=強制. 子供を食べさせた=paksa anak makan.','medium',NULL,'{"general"}',770627906);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Passive-Causative.html','general','「使役受身」の意味は？','["自分でする", "させる+される=やりたくないのにさせられる", "させてもらう", "やってあげる"]'::jsonb,1,'使役受身=dipaksa melakukan ~. 残業させられた=dipaksa lembur. N2重要文法! 食べさせられる=dipaksa makan.','medium',NULL,'{"general"}',1864156656);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Passive-Causative.html','general','「非情受身」の特徴は？','["被害・迷惑を表す", "無生物が主語で書き言葉・フォーマルに使う", "強制を表す", "許可を表す"]'::jsonb,1,'非情受身=pasif non-personal. この本は多くの人に読まれている=buku ini dibaca banyak orang. 学術・文語的。','medium',NULL,'{"general"}',1275624601);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Passive-Causative.html','general','「する」の使役形は？','["しれる", "しさせる", "させる", "せられる"]'::jsonb,2,'する→させる(Grup 3). 勉強させる=menyuruh belajar. させていただきます=keigo umum(させていただく=謙譲語).','medium',NULL,'{"general"}',1834198461);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Pola-Kalimat-N1.html','general','「〜ずにはおかない」は？','["しなくてもいい", "強い必然・感情的圧力で〜せずにはいられない", "したい", "普通にする"]'::jsonb,1,'ずにはおかない=pasti akan ~; tidak bisa tidak ~. 感動させずにはおかない=pasti mengharukan. 強い必然性の表現。','hard','N1','{"general", "n1"}',1560751564);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Pola-N1-Lanjut.html','general','「結果いかんによらず」の意味は？','["結果によって変わる", "結果に関係なく", "結果が良ければ", "結果が悪ければ"]'::jsonb,1,'いかんによらず=terlepas dari ~. 結果いかんによらず=terlepas dari hasilnya. フォーマルな表現。','hard','N1','{"general", "n1"}',1119317420);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Pola-N1-Lanjut.html','general','「彼女をおいて他にない」の意味は？','["彼女を除いた", "彼女以外に適任者はいない", "彼女が去った", "彼女と一緒に"]'::jsonb,1,'をおいて(他に〜ない)=selain ~ tidak ada yang lain. 唯一性を強調する文語的表現。','hard','N1','{"general", "n1"}',420882501);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Pola-N1-Lanjut.html','general','「努力なくして成功はない」の「なくして」は？','["努力なしに(なければ成功できない)", "努力がなくなって", "努力せずに失敗した", "努力がいらない"]'::jsonb,0,'なくして(は)=tanpa ~. 必要条件を示す。努力なくして成功はない=tanpa usaha, tidak ada keberhasilan.','hard','N1','{"general", "n1"}',1074611368);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Pola-N1-Lanjut.html','general','「専門家といえども」の意味は？','["専門家だから当然", "専門家であっても(〜でさえ)", "専門家のようだ", "専門家になれば"]'::jsonb,1,'といえども=meskipun ~; bahkan ~ sekalipun. 逆接的な書き言葉表現。専門家でも間違える=bahkan ahli pun bisa salah.','hard','N1','{"general", "n1"}',922909021);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Pola-N1-Lanjut.html','general','「技術もさることながら」はどんな意味？','["技術は重要でない", "技術はもちろん(として、さらに)", "技術だけが大切", "技術を除いて"]'::jsonb,1,'もさることながら=tidak hanya ~ (yang sudah jelas), bahkan ~. A当然だが、さらにBも強調する。','hard','N1','{"general", "n1"}',1215104677);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Pola-N1-Lanjut.html','general','「信頼に足る人物」の「に足る」は？','["信頼するには不十分", "信頼するに値する(worthy)", "信頼できない", "信頼が足りない"]'::jsonb,1,'に足る=layak; worthy of ~. 信頼に足る=dapat dipercaya; layak dipercaya. 客観的な評価を示す。','hard','N1','{"general", "n1"}',358358346);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Pola-N1-Lanjut.html','general','「ともなると」の使い方は？','["N+ともなると=低い地位では", "N+ともなると=その立場・レベルになると", "V+ともなると", "Adj+ともなると"]'::jsonb,1,'N+ともなると=kalau sudah menjadi ~; begitu ~ (maka tanggung jawab pun berbeda). 部長ともなると=kalau sudah jadi manajer.','hard','N1','{"general", "n1"}',1275484684);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Pola-N1-Lanjut.html','general','「失礼極まりない」の「極まりない」は？','["少し失礼", "極めて(非常に)失礼", "失礼でない", "失礼に慣れた"]'::jsonb,1,'極まりない=sangat ~; luar biasa ~ (ekstrem). 主にネガティブな形容詞に使う。失礼極まりない=sangat tidak sopan.','hard','N1','{"general", "n1"}',2004924648);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Potential-Form.html','general','「書く」の可能形は？','["書かれる", "書ける", "書れる", "書きれる"]'::jsonb,1,'書く(Grup 1)の可能形=書け+る=書ける. Grup 1: え段+る. 飲む→飲める、話す→話せる、聞く→聞ける。','medium',NULL,'{"general"}',624767868);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Potential-Form.html','general','「食べる」の可能形は？','["食べれる", "食べれられる", "食べられる", "食べける"]'::jsonb,2,'食べる(Grup 2)の可能形=食べ+られる=食べられる. Grup 2: 語幹+られる. 見る→見られる。','medium',NULL,'{"general"}',958843811);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Potential-Form.html','general','「日本語を話す」の可能形は？','["日本語を話せる", "日本語が話せる", "日本語に話せる", "日本語で話せる"]'::jsonb,1,'可能形では「を→が」が基本. 日本語が話せる=bisa berbicara bahasa Jepang. をも使えるが(口語的), がの方が正式。','medium',NULL,'{"general"}',1577306080);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Potential-Form.html','general','「ら抜き言葉」とは？','["正式な文体", "食べられる→食べれるのように「ら」を省略した若者言葉", "難しい敬語", "古い表現"]'::jsonb,1,'ら抜き=省略「ら」. 食べられる→食べれる, 見られる→見れる. 口語では広まっているが試験・フォーマルでは「ら」を入れる形が正しい。','medium',NULL,'{"general"}',215014807);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Potential-Form.html','general','「〜得る(うる)」の意味は？','["〜したい", "〜する可能性がある・〜できる(N2文語)", "〜した", "〜しない"]'::jsonb,1,'〜得る(うる/える)=bisa ~; ada kemungkinan ~. そんなことも起こり得る=hal seperti itu bisa saja terjadi. フォーマル・書き言葉的。','medium',NULL,'{"general"}',534744408);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Potential-Form.html','general','「できるようになった」の意味は？','["ずっとできる", "以前はできなかったが今はできる(変化)", "できなくなった", "やめた"]'::jsonb,1,'可能形+ようになった=menjadi bisa ~(変化の結果). 日本語が話せるようになった=sudah bisa berbicara bahasa Jepang.','medium',NULL,'{"general"}',1859190870);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Potential-Form.html','general','「する」の可能形は？','["しれる", "しられる", "できる", "しえる"]'::jsonb,2,'する→できる(Grup 3, 不規則). 勉強する→勉強できる. できる単独でも使う. ×「しれる」は間違い。','medium',NULL,'{"general"}',1851231918);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N1.html','reading','上のテキストで「AIの恩恵を享受できるのは〜一部の層」という指摘は何を示している？','["AIは素晴らしい", "格差拡大への懸念", "AIを反対する", "全員が恩恵を受ける"]'::jsonb,1,'「〜のではないかという懸念も根強い」=kekhawatiran yang kuat. 筆者は格差拡大の可能性を懸念している。','hard','N1','{"reading", "n1"}',1580924732);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N1.html','reading','N1読解「統合理解」とは？','["一つの長い文章を読む", "二つのテキストを比較・関連付けて理解する", "表や図を読む", "音声を聞く"]'::jsonb,1,'統合理解=N1専用セクション. 2つのテキスト(対立する意見など)を読み、共通点・相違点・関係性を問われる。','hard','N1','{"reading", "n1"}',1021650136);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N1.html','reading','文中の「不可欠」の意味は？','["あればいい", "なくてはならない・必須", "少し必要", "あまり重要でない"]'::jsonb,1,'不可欠(ふかけつ)=sangat diperlukan; tidak bisa tanpa. AIリテラシーの普及は不可欠だ=penyebaran literasi AI sangat diperlukan.','hard','N1','{"reading", "n1"}',296635141);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N1.html','reading','N1読解で「のみならず」は何を示す？','["〜だけ", "〜だけでなく・さらに(累加)", "〜だから", "〜に反して"]'::jsonb,1,'のみならず=tidak hanya. 単純作業のみならず知的作業でも=tidak hanya pekerjaan sederhana, tapi juga pekerjaan intelektual.','hard','N1','{"reading", "n1"}',228276380);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N1.html','reading','「懸念も根強い」の「根強い」の意味は？','["弱い", "根深く強固にある", "少しある", "なくなりつつある"]'::jsonb,1,'根強い(ねづよい)=kuat berakar; mengakar kuat; tidak mudah hilang. 懸念が根強い=kekhawatiran yang mengakar kuat.','hard','N1','{"reading", "n1"}',217149900);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N2.html','reading','上のエッセイで「一方で」の後に何が述べられている？','["テクノロジーの便利さ", "対面コミュニケーション能力低下の懸念", "AIの発展", "SNSの歴史"]'::jsonb,1,'逆接「一方で」=di sisi lain. テクノロジーの便利さを認めた後、対面コミュニケーション低下の懸念が述べられている。これが筆者の主な関心。','hard','N2','{"reading", "n2"}',1355519520);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N2.html','reading','市民講座の申込締切はいつ？','["3月15日", "3月10日", "3月1日", "2月末"]'::jsonb,1,'申込締切=3月10日(月). 情報検索問題は質問に関連する情報を素早く見つけることが重要。テキスト全体を読まず必要部分を検索。','hard','N2','{"reading", "n2"}',664941970);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N2.html','reading','「依存しすぎる」の筆者のスタンスは？','["全面的に賛成", "問題があると考えている", "どちらでもない", "依存を勧めている"]'::jsonb,1,'「〜ことで失われるものもあるのではないだろうか」=筆者の懸念・疑問. 「ではないか」=婉曲的な否定/懸念表現.','hard','N2','{"reading", "n2"}',1635648443);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N2.html','reading','市民講座で駐車場はある？','["ある", "ない(※駐車場はございません)", "不明", "有料で使える"]'::jsonb,1,'情報検索: 「※駐車場はございません」= tidak ada parkir. 注記(※)も重要な情報源。正確に探して答える。','hard','N2','{"reading", "n2"}',408376177);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N2.html','reading','N2読解で最重要なスキルは？','["全部暗記する", "main ideaと詳細情報の素早い検索", "日本語→翻訳", "長い時間をかける"]'::jsonb,1,'N2読解の核心: main idea(筆者の主張)を素早く見つける + 設問に関連する詳細情報を検索するスキル. 時間管理も重要。','hard','N2','{"reading", "n2"}',1200556448);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N3.html','reading','図書館の土曜日の開館時間はどう変わる？','["変わらない", "短くなる(10:00〜17:00)", "長くなる", "休館になる"]'::jsonb,1,'情報検索: 土曜=10:00〜17:00(従来：9:00〜19:00). 1時間遅く開いて、2時間早く閉まる→開館時間が短くなる。','medium','N3','{"reading", "n3"}',915937481);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N3.html','reading','「継続は力なり」の意味に最も近いのは？','["力があれば何でもできる", "継続的な努力が大きな成果につながる", "勉強より休憩が大切", "集中して短期間学習するべき"]'::jsonb,1,'継続は力なり=konsistensi adalah kekuatan. 毎日続けることで大きな成果につながる=konsistensi kecil menghasilkan hasil besar.','medium','N3','{"reading", "n3"}',432220109);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N3.html','reading','上の文章で筆者が最も言いたいことは？','["1日180時間勉強すべき", "短期集中勉強が効果的", "少量でも毎日継続する学習法が効果的", "語学は1年で習得できる"]'::jsonb,2,'筆者の主張=少しずつ長期間続ける方が記憶の定着率が高い。最後の文に結論が来る典型的な短文構造。','medium','N3','{"reading", "n3"}',1221808810);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N3.html','reading','N3読解で「逆接」の後には何が来る？','["例示", "筆者の本当の主張や意見", "背景情報", "定義"]'::jsonb,1,'逆接(しかし・でも・ところが)の後=筆者の核心的な主張. N3読解で最も重要なマーカーの一つ。','medium','N3','{"reading", "n3"}',1004003071);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N3.html','reading','N3読解の情報検索問題の攻略法は？','["テキスト全部を読む", "設問を先に読んでから必要情報を探す", "選択肢から推測する", "全部暗記する"]'::jsonb,1,'情報検索=scan. お知らせ・広告・時刻表は設問先読みが必須。全部読む必要なし — 必要な情報だけ探す。','medium','N3','{"reading", "n3"}',1152798752);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N4.html','reading','ミーティングの場所はどう変わりましたか？','["会議室からカフェに変わった", "カフェから会議室に変わった", "変わらない", "中止になった"]'::jsonb,0,'「会議室が使えなくなったので、カフェ『さくら』に変更します」とある。場所が変更された。','easy','N4','{"reading", "n4"}',432206650);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N4.html','reading','ミーティングの時間はどうなりましたか？','["午前から午後に変わった", "時間は変わらず午後2時から", "1時間早くなった", "わからない"]'::jsonb,1,'「時間は変わらず午後2時からです」と明記されている。場所だけが変更された。','easy','N4','{"reading", "n4"}',543600721);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N4.html','reading','木村さんは明日何を持ってくる必要がありますか？','["パソコン", "資料", "お弁当", "何も持ってこなくていい"]'::jsonb,1,'「資料は持ってきてください」と依頼されている。〜てください=tolong lakukan~。','easy','N4','{"reading", "n4"}',176016319);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N4.html','reading','道路工事は何時から何時まで行われますか？','["朝7時から夕方6時まで", "朝9時から夕方5時まで", "24時間", "夜だけ"]'::jsonb,0,'「工事は朝7時から夕方6時まで行われる予定です」とある。','easy','N4','{"reading", "n4"}',1278689043);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N4.html','reading','工事中、気をつけるべきことは何ですか？','["駅を使わないこと", "自転車や車の運転", "音がうるさいこと", "工事現場に入ること"]'::jsonb,1,'「自転車や車を運転する方は気をつけてください」とある。道が狭くなるため。','easy','N4','{"reading", "n4"}',1873947190);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N4.html','reading','工事はどのくらい続く予定ですか？','["1週間", "1ヶ月くらい", "半年", "1年"]'::jsonb,1,'「工事は1ヶ月くらい続く見込みです」とある。見込み=perkiraan/estimasi。','easy','N4','{"reading", "n4"}',606169508);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N5.html','reading','アニさんは何人ですか？','["日本人", "インドネシア人", "アメリカ人", "中国人"]'::jsonb,1,'「インドネシア人です」と書いてある。アニさんの国籍はインドネシア。','easy','N5','{"reading", "n5"}',644200561);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N5.html','reading','アニさんの趣味は何ですか？','["勉強すること", "音楽を聞くこと", "本を読むこと", "料理をすること"]'::jsonb,1,'「趣味は音楽を聞くことです」とある。趣味=hobi。','easy','N5','{"reading", "n5"}',1630933092);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N5.html','reading','会議は何時から何時までですか？','["2時から3時", "3時から4時", "4時から5時", "1時から2時"]'::jsonb,1,'「会議が3時から4時まで」とメモに書いてある。〜から〜まで=dari~sampai~。','easy','N5','{"reading", "n5"}',1852215037);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N5.html','reading','会議室はどこですか？','["1階の101号室", "2階の201号室", "3階の301号室", "1階の会議室"]'::jsonb,1,'「会議室は2階の201号室」と書いてある。場所を表す数字に注目。','easy','N5','{"reading", "n5"}',704721547);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N5.html','reading','スーパーやまだは何曜日が休みですか？','["土曜日", "日曜日", "月曜日", "休みはない"]'::jsonb,1,'「日曜日は休みです」とある。休み=libur/tutup。','easy','N5','{"reading", "n5"}',243743682);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Reading-N5.html','reading','今、何が安いですか？','["パンとお米", "牛乳とパン", "野菜と果物", "肉と魚"]'::jsonb,1,'「牛乳とパンが安いです」とある。20％引き=diskon 20 persen。','easy','N5','{"reading", "n5"}',1995880704);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Salam-Sapaan-Jepang.html','general','Bagaimana mengucapkan ''Selamat pagi'' secara sopan?','["こんにちは", "おはようございます", "こんばんは", "おやすみなさい"]'::jsonb,1,'おはようございます (ohayou gozaimasu) adalah bentuk sopan dari salam pagi. Bentuk kasualnya (おはよう saja) dipakai dengan teman dekat atau keluarga, bukan dengan atasan atau orang yang baru dikenal.','medium',NULL,'{"general"}',1192232938);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Salam-Sapaan-Jepang.html','general','Kapan こんばんは digunakan?','["Pagi hari", "Siang hari", "Sore/malam hari", "Saat tidur"]'::jsonb,2,'こんばんは (konbanwa) dipakai sore hingga malam hari, berbeda dari こんにちは yang dipakai siang hari. Kedua salam ini tidak memiliki bentuk sopan tambahan seperti ございます.','medium',NULL,'{"general"}',401583423);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Salam-Sapaan-Jepang.html','general','Apa arti すみません?','["Terima kasih saja", "Maaf/permisi (multifungsi)", "Selamat pagi", "Selamat tinggal"]'::jsonb,1,'すみません (sumimasen) bersifat multifungsi: bisa berarti maaf, permisi (untuk memanggil perhatian), atau bahkan terima kasih dalam konteks tertentu. Kata ini adalah salah satu ungkapan paling serbaguna dalam bahasa Jepang.','medium',NULL,'{"general"}',1749098870);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Salam-Sapaan-Jepang.html','general','Ungkapan yang tepat saat pertama kali bertemu seseorang?','["さようなら", "はじめまして", "ただいま", "おかえりなさい"]'::jsonb,1,'はじめまして berarti ''salam kenal'', diucapkan khusus saat pertemuan pertama kali dan selalu diikuti dengan penyebutan nama diri dalam rangkaian perkenalan.','medium',NULL,'{"general"}',1607052630);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Salam-Sapaan-Jepang.html','general','Apa yang diucapkan saat pulang dan tiba di rumah?','["いってきます", "ただいま", "おはよう", "またね"]'::jsonb,1,'ただいま (tadaima) diucapkan saat tiba di rumah, secara harfiah berarti ''saya baru saja pulang''. Anggota keluarga di rumah biasanya menjawab dengan おかえりなさい (selamat datang kembali).','medium',NULL,'{"general"}',1206534741);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Salam-Sapaan-Jepang.html','general','Balasan untuk ありがとう adalah?','["すみません", "どういたしまして", "ごめんなさい", "さようなら"]'::jsonb,1,'どういたしまして berarti ''sama-sama/terima kasih kembali'', balasan standar untuk ucapan terima kasih. Dalam percakapan santai, terkadang cukup dibalas dengan いいえ atau senyuman.','medium',NULL,'{"general"}',1134406171);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Salam-Sapaan-Jepang.html','general','よろしくお願いします artinya?','["Selamat tidur", "Mohon kerja samanya/senang berkenalan", "Terima kasih banyak", "Maaf sekali"]'::jsonb,1,'よろしくお願いします dipakai saat berkenalan atau memulai kerja sama, mengandung harapan akan hubungan baik ke depannya. Maknanya mendekati ''mohon bantuannya/kerja samanya''.','medium',NULL,'{"general"}',1566134605);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Salam-Sapaan-Jepang.html','general','Manakah salam perpisahan yang KASUAL?','["さようなら", "またね", "おはようございます", "はじめまして"]'::jsonb,1,'またね (mata ne) berarti ''sampai jumpa'', bentuk kasual yang dipakai dengan teman dekat. Bentuk lebih formal untuk perpisahan adalah さようなら, meski jarang dipakai dalam percakapan sehari-hari modern.','medium',NULL,'{"general"}',1391545516);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Salam-Sapaan-Jepang.html','general','Apa yang diucapkan saat KELUAR dari rumah?','["ただいま", "いってきます", "おかえりなさい", "おやすみ"]'::jsonb,1,'いってきます (ittekimasu) berarti ''saya berangkat (dan akan kembali)'', diucapkan saat keluar rumah. Anggota keluarga yang tinggal biasanya menjawab dengan いってらっしゃい (hati-hati di jalan).','medium',NULL,'{"general"}',237747736);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Salam-Sapaan-Jepang.html','general','Mengapa は pada こんにちは dibaca ''wa''?','["Kesalahan penulisan", "Karena は adalah partikel", "Karena dialek", "Tidak ada alasan"]'::jsonb,1,'は dibaca ''wa'' ketika berfungsi sebagai partikel topik dalam kalimat, meskipun ditulis dengan huruf hiragana は (biasanya dibaca ''ha''). Ini adalah salah satu aturan pengecualian pelafalan penting dalam bahasa Jepang.','medium',NULL,'{"general"}',1374413095);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-Daily.html','general','食事介助の声かけで大切なのは？','["早く食べさせる", "名前を呼び、何を食べるか説明して楽しみを作る", "黙って介助する", "時間だけ伝える"]'::jsonb,1,'Poin penting dalam menyapa saat bantuan makan: memanggil nama (menghargai individu), menyampaikan isi menu (menimbulkan antisipasi), dan mengajak makan bersama secara hangat — bukan sekadar menyodorkan makanan tanpa kata-kata.','medium',NULL,'{"general"}',631948195);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-Daily.html','general','「いかがですか？」の代わりに使える丁寧な表現は？','["どうですか？", "〜はいかがでしょうか？(より丁寧)", "OK?", "何？"]'::jsonb,1,'いかがでしょうか lebih sopan dibanding いかがですか. Contoh penggunaan: ご気分はいかがでしょうか (bagaimana perasaan Anda?), sering dipakai dalam konteks perawatan untuk menanyakan kondisi dengan lebih halus.','medium',NULL,'{"general"}',89110605);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-Daily.html','general','就寝前の声かけで必ず伝えることは？','["何も言わない", "感謝・労い(お疲れさまでした)とおやすみの挨拶", "次の予定", "天気"]'::jsonb,1,'Sebelum tidur, ucapan yang wajib disampaikan: お疲れさまでした (mengapresiasi usaha hari itu) + おやすみなさい (selamat tidur) + tawaran bantuan jika ada yang dibutuhkan di malam hari — kombinasi ini menunjukkan perhatian menyeluruh.','medium',NULL,'{"general"}',132400163);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-Daily.html','general','利用者が「腰が痛い」と言った時の適切な対応は？','["無視する", "詳しく痛みを聞いて看護師に報告し記録する", "痛み止めを渡す", "運動させる"]'::jsonb,1,'Menanggapi keluhan nyeri: pertama dengarkan dengan empati, lalu tanyakan detail (sejak kapan, seberapa parah, jenis nyerinya) sebelum melaporkan ke tenaga medis — jangan langsung mengabaikan atau menyimpulkan sendiri tanpa konfirmasi lebih lanjut.','medium',NULL,'{"general"}',278990320);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-N2-N1.html','general','「グローバル化が進む中」の意味は？','["グローバル化が終わった", "グローバル化が進んでいる状況の中で", "グローバル化を進める", "グローバル化に反対する"]'::jsonb,1,'〜が進む中=di tengah ~ yang sedang berkembang. グローバル化が進む中=di tengah kemajuan globalisasi. 〜中(なか)=状況・背景を示す。','hard','N2','{"general", "n2"}',722307451);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-N2-N1.html','general','「不可欠(ふかけつ)」の意味は？','["少し大切", "欠かすことができない(必須)", "あまり重要でない", "将来必要"]'::jsonb,1,'不可欠=sangat penting; tidak bisa tanpa. 例:教育は不可欠だ=pendidikan sangat diperlukan. 不=否定+可欠=bisa dikurangi.','hard','N2','{"general", "n2"}',240613413);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-N2-N1.html','general','「実現する(じつげんする)」の意味は？','["夢を見る", "現実のものにする", "諦める", "計画する"]'::jsonb,1,'実現する=mewujudkan; membuat menjadi nyata. 例:夢を実現する=mewujudkan impian. 反対:断念する=諦める。','hard','N2','{"general", "n2"}',1262705469);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-N2-N1.html','general','「〜に寄り添う(よりそう)」の意味は？','["距離を置く", "相手の側に立ち支える", "批判する", "無視する"]'::jsonb,1,'寄り添う=mendampingi; bersimpati. 感情的サポートを示す表現。介護では「利用者に寄り添う」がよく使われる。','hard','N2','{"general", "n2"}',1564838329);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-N2-N1.html','general','「尊厳(そんげん)を守る」の意味は？','["身体を守る", "人としての価値・誇りを守る", "財産を守る", "秘密を守る"]'::jsonb,1,'尊厳=martabat; harga diri sebagai manusia. 介護の根本原則。尊厳のある生活=kehidupan yang bermartabat.','hard','N2','{"general", "n2"}',2102351019);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-Practice.html','general','Speaking Practice menggunakan teknologi apa untuk menilai pengucapan?','["Keyboard input", "Web Speech API (Speech Recognition)", "Upload file audio", "Pilihan ganda saja"]'::jsonb,1,'Speaking Practice menggunakan Web Speech API yang tersedia di browser modern (Chrome/Edge). Browser mendengarkan ucapan pengguna dan membandingkan dengan target kalimat Jepang.','medium',NULL,'{"general"}',1146336026);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-Practice.html','general','Apa yang dimaksud dengan ''shadow speaking'' dalam latihan berbicara Jepang?','["Berbicara di tempat gelap", "Meniru dan mengucapkan bersamaan dengan audio asli (native speaker)", "Hanya membaca teks", "Menulis ulang kalimat"]'::jsonb,1,'Shadowing=teknik latihan di mana pelajar meniru ucapan penutur asli secara hampir bersamaan. Melatih ritme, intonasi, dan pitch accent secara natural.','medium',NULL,'{"general"}',375578819);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-Practice.html','general','Mengapa latihan berbicara (speaking) penting bahkan untuk persiapan JLPT?','["JLPT ada tes speaking", "Melatih Speaking memperkuat pemahaman grammar dan intonasi yang mendukung tes Listening", "Speaking tidak ada hubungannya dengan JLPT", "Hanya untuk kelas conversation"]'::jsonb,1,'JLPT tidak memiliki tes speaking, tapi latihan berbicara memperkuat pemrosesan bahasa secara aktif, meningkatkan pemahaman Listening, dan mempercepat internalisasi grammar.','medium',NULL,'{"general"}',2003302002);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-Practice.html','general','Pitch accent (高低アクセント) paling berpengaruh di dialek mana?','["Osaka/Kansai", "Tokyo/Standard Japanese", "Okinawa", "Hokkaido"]'::jsonb,1,'Tokyo/Standar Jepang (hyōjungo) paling sering dijadikan referensi pitch accent untuk JLPT dan komunikasi formal. Kansai memiliki sistem pitch accent yang berbeda dari Tokyo.','medium',NULL,'{"general"}',1892047154);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Speaking-Practice.html','general','Untuk Speaking Practice berbasis Speech Recognition, browser apa yang direkomendasikan?','["Internet Explorer", "Firefox", "Chrome atau Edge versi terbaru", "Safari versi lama"]'::jsonb,2,'Web Speech API paling baik didukung oleh Chrome dan Edge versi terbaru. Firefox dan Safari memiliki dukungan terbatas atau tidak mendukung Speech Recognition API secara penuh.','medium',NULL,'{"general"}',882004927);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Surat-Formal.html','general','「拝啓」に対応する結語は？','["謹言", "草々", "敬具", "敬白"]'::jsonb,2,'拝啓(はいけい)→敬具(けいぐ)がセット。謹啓→謹言、前略→草々。頭語と結語は必ず対応するペアを使う。','medium',NULL,'{"general"}',381205932);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Surat-Formal.html','general','時候の挨拶の目的は？','["天気を報告する", "季節に合わせた礼儀正しい書き出しをする", "価格を説明する", "要件を伝える"]'::jsonb,1,'時候の挨拶=salam yang sesuai musim. 日本の手紙文化では季節の挨拶が礼儀の基本。フォーマルさを示す。','medium',NULL,'{"general"}',757515570);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Surat-Formal.html','general','「さて、」で始まる文の役割は？','["挨拶を続ける", "本文(本題)に入る転換", "結語に入る", "日付を書く"]'::jsonb,1,'さて=nah; ところで. 前文(挨拶)から本文(要件)に移行する時に使う。本題への転換マーカー。','medium',NULL,'{"general"}',1258591469);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Surat-Formal.html','general','「謹啓」を使うのはどんな場面？','["友人への手紙", "上司・重要な取引先へのより丁寧な手紙", "簡単な連絡", "メール"]'::jsonb,1,'謹啓(きんけい)=より丁寧な頭語. 拝啓より格式高い。社長・重要顧客・公的機関への手紙に使う。','medium',NULL,'{"general"}',1928404586);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Surat-Formal.html','general','「まずはご連絡まで」はどこに書く？','["頭語", "時候の挨拶", "本文", "末文(本文を締める)"]'::jsonb,3,'末文=本文の締め. まずはご連絡まで / まずは取り急ぎ〜 は末文で使う。その後に結語(敬具等)が来る。','medium',NULL,'{"general"}',919663980);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Surat-Formal.html','general','「拝復」はどんな時に使う？','["最初の手紙", "返信の手紙", "お礼の手紙", "お詫びの手紙"]'::jsonb,1,'拝復(はいふく)=お返事(ご返信)の頭語. 相手からの手紙への返信の際に使う。拝復→敬具のセット。','medium',NULL,'{"general"}',2049330124);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Suru-Verbs-List.html','general','「発展する」の意味は？','["後退する", "進歩・成長する", "変わらない", "終わる"]'::jsonb,1,'発展する berarti berkembang/maju. Contoh: 経済が発展する berarti ''ekonomi berkembang''. Kata kerja ini sering dipakai dalam konteks pembahasan sosial, ekonomi, atau teknologi.','medium',NULL,'{"general"}',2072819296);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Suru-Verbs-List.html','general','「妥協する」の意味は？','["全面的に勝つ", "お互いに譲り合う", "全面的に負ける", "無視する"]'::jsonb,1,'妥協する berarti berkompromi. Dalam negosiasi, 妥協 dipakai untuk menggambarkan proses mencari titik temu antara pihak-pihak yang memiliki kepentingan berbeda.','medium',NULL,'{"general"}',1668070643);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Te-Form-Guide.html','general','「書く」のて形は？','["書いて", "書いで", "書きて", "書って"]'::jsonb,0,'書く(〜く→いて)=書いて. 〜く ending: く→いて. 例外: 行く→行って(促音化, NOT 行いて)。','medium',NULL,'{"general"}',910649603);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Te-Form-Guide.html','general','「飲む」のて形は？','["飲みて", "飲んで", "飲いて", "飲って"]'::jsonb,1,'飲む(〜む→んで)=飲んで. 〜む・ぬ・ぶ ending → んで/んだ. 遊ぶ→遊んで、死ぬ→死んで。','medium',NULL,'{"general"}',1070819993);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Te-Form-Guide.html','general','「食べる」のて形は？','["食べって", "食べいて", "食べて", "食べんで"]'::jsonb,2,'食べる(Grup 2)=食べて. Grup 2: る取ってて. 見る→見て、起きる→起きて。','medium',NULL,'{"general"}',1847100768);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Te-Form-Guide.html','general','「行く」のて形は？(注意!)','["行いて", "行って(例外)", "行きて", "行んで"]'::jsonb,1,'行く=例外! 行く→行って(促音化). 通常くはいてだが行くだけはって。必ず暗記する。','medium',NULL,'{"general"}',1028665825);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Te-Form-Guide.html','general','「〜ている」の2つの用法は？','["進行中のみ", "進行中(食べている) + 結果の状態(結婚している)", "完了のみ", "意図の準備のみ"]'::jsonb,1,'〜ている: ①進行=今〜している ②状態=〜した結果が続く. 食べている(進行) vs 結婚している(状態).','medium',NULL,'{"general"}',1746944156);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Te-Form-Guide.html','general','「〜てある」を使えるのは？','["自動詞のみ", "他動詞のみ+意図的行為の結果", "どちらでも", "不規則動詞のみ"]'::jsonb,1,'てある=他動詞+意図的結果. 窓が開けてある=jendela sudah (sengaja) dibuka. ×窓が開いてある(NG).','medium',NULL,'{"general"}',2105892617);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Te-Form-Guide.html','general','「〜てしまう」のニュアンスは？','["喜んで", "完了+後悔や残念な気持ち", "まだやっていない", "これからする"]'::jsonb,1,'てしまう=terlanjur; selesai (sering ada nuansa penyesalan). お金を使ってしまった=terlanjur habiskan uang.','medium',NULL,'{"general"}',603394907);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Te-Form-Guide.html','general','「〜てくる」の意味の一つは？','["〜して去る", "変化が話し手に向かってくる(〜になってきた)", "〜してあげる", "〜してもらう"]'::jsonb,1,'〜てくる=perubahan yang mendekat ke pembicara/sekarang. 暖かくなってきた=sudah mulai hangat (dari dulu sampai sekarang).','medium',NULL,'{"general"}',738576566);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Te-Form-Guide.html','general','「話す」のて形は？','["話いて", "話して", "話って", "話んで"]'::jsonb,1,'話す(〜す→して)=話して. 〜す ending: す→して/した. 貸す→貸して、返す→返して。','medium',NULL,'{"general"}',270859710);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Compound-Guide.html','general','「〜込む」が付く複合動詞の特徴は？','["外に出る", "中に入る・深まる・集中する", "上に上がる", "横に動く"]'::jsonb,1,'〜込む=masuk ke dalam; mendalam; intens. 飛び込む(terjun masuk)・落ち込む(terpuruk)・思い込む(yakin kuat).','medium',NULL,'{"general"}',2137205652);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Compound-Guide.html','general','「思い込む」の意味は？','["思い出す", "根拠があるかどうかに関わらず強く信じる", "忘れる", "考えやめる"]'::jsonb,1,'思い込む=meyakini kuat meski mungkin salah. 自分が正しいと思い込む=yakin kuat bahwa dirinya benar.','medium',NULL,'{"general"}',1231018486);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Compound-Guide.html','general','「やり切る」の意味は？','["途中でやめる", "最後まで完全にやり遂げる", "やり直す", "失敗する"]'::jsonb,1,'〜切る=menyelesaikan sepenuhnya; tuntas. やり切る=menyelesaikan sampai habis/tuntas. 言い切る=menyatakan dengan tegas.','medium',NULL,'{"general"}',273370351);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Compound-Guide.html','general','「〜直す」の意味は？','["初めてする", "一度したことをもう一度する・修正する", "やめる", "速くする"]'::jsonb,1,'〜直す=melakukan ulang; memperbaiki. 書き直す=menulis ulang. やり直す=mengulang dari awal. 読み直す=membaca ulang.','medium',NULL,'{"general"}',30384568);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Compound-Guide.html','general','「申し込む」の意味は？','["断る", "登録・申請する", "取り消す", "変更する"]'::jsonb,1,'申し込む=mendaftar; mengajukan permohonan. コースに申し込む=mendaftar kursus. 申し込み=pendaftaran.','medium',NULL,'{"general"}',1759935904);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Compound-Guide.html','general','「〜合う」が付く動詞の特徴は？','["一人でする", "お互いに〜する・共同で", "競争する", "終わらせる"]'::jsonb,1,'〜合う=saling ~; bersama. 話し合う=berdiskusi bersama. 助け合う=saling membantu. 支え合う=saling mendukung.','medium',NULL,'{"general"}',1201030920);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Intransitif-Guide.html','general','「窓を（　）」に入る他動詞は？','["開く", "開ける", "開まる", "開かる"]'::jsonb,1,'開ける (akeru) adalah 他動詞 (transitif) yang memerlukan partikel を, seperti dalam 窓を開ける (membuka jendela). Kata kerja transitif menunjukkan subjek yang secara sengaja melakukan tindakan pada objek.','medium',NULL,'{"general"}',1383759508);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Intransitif-Guide.html','general','「ドアが（　）」に入る自動詞は？','["閉める", "閉まる", "閉めさせる", "閉められる"]'::jsonb,1,'閉まる (shimaru) adalah 自動詞 (intransitif), dipakai dalam ドアが閉まる (pintu tertutup dengan sendirinya). Kata kerja intransitif menunjukkan perubahan keadaan tanpa menyebutkan pelaku yang menyebabkannya.','medium',NULL,'{"general"}',1716397622);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Intransitif-Guide.html','general','「〜てある」は他動詞・自動詞どちら？','["自動詞のみ", "他動詞のみ", "どちらでも", "どちらでもない"]'::jsonb,1,'てある hanya dipakai dengan kata kerja 他動詞 (transitif) untuk menunjukkan hasil suatu tindakan yang disengaja: 窓が開けてある (jendela sengaja dibuka/dalam keadaan terbuka karena seseorang membukanya) adalah benar, sedangkan ×窓が開いてある salah karena 開く adalah intransitif.','medium',NULL,'{"general"}',2013168725);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Intransitif-Guide.html','general','「増やす」の自動詞ペアは？','["増す", "増える", "増させる", "増られる"]'::jsonb,1,'増える (fueru) adalah pasangan intransitif dari 増やす (fuyasu, menambah). 収入が増える berarti ''penghasilan bertambah (dengan sendirinya)'', berbeda dari 収入を増やす yang berarti ''menambah penghasilan (secara sengaja)''.','medium',NULL,'{"general"}',536092193);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Intransitif-Guide.html','general','「電気が（　）」自動詞は？','["付ける", "消える", "付く", "点ける"]'::jsonb,2,'付く (tsuku) adalah kata kerja intransitif, dipakai dalam 電気が付く (lampu menyala). Pasangan transitifnya adalah 付ける (tsukeru), dipakai dalam 電気を付ける (menyalakan lampu).','medium',NULL,'{"general"}',293246605);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Intransitif-Guide.html','general','「変える」の自動詞ペアは？','["変わらない", "変わる", "変えられる", "変えさせる"]'::jsonb,1,'変わる (kawaru) adalah pasangan intransitif dari 変える (kaeru, mengubah). 状況が変わる berarti ''situasi berubah (dengan sendirinya)'', berbeda dari 状況を変える yang berarti ''mengubah situasi (secara sengaja)''.','medium',NULL,'{"general"}',480228752);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Intransitif-Guide.html','general','「〜ている」で他動詞と自動詞の違いは？','["同じ", "他動詞+ている=行為中、自動詞+ている=結果の状態", "自動詞のみ", "他動詞のみ"]'::jsonb,1,'窓を開けている berarti ''sedang membuka jendela'' (aksi sedang berlangsung, memakai kata kerja transitif), sedangkan 窓が開いている berarti ''jendela sudah dalam keadaan terbuka'' (hasil keadaan, memakai kata kerja intransitif).','medium',NULL,'{"general"}',118793905);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Intransitif-Guide.html','general','「壊す」の自動詞ペアは？','["壊れる", "壊まる", "壊られる", "壊させる"]'::jsonb,0,'壊れる (kowareru) adalah pasangan intransitif dari 壊す (kowasu, merusak). 機械が壊れる berarti ''mesin rusak (dengan sendirinya)'', berbeda dari 機械を壊す yang berarti ''merusak mesin (secara sengaja)''.','medium',NULL,'{"general"}',1811492551);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Suru-Advanced.html','general','「遂行する」と「実施する」の違いは？','["同じ", "遂行=最後までやり遂げる(完遂)、実施=実行に移す(開始)", "どちらも同じ意味", "違う分野に使う"]'::jsonb,1,'遂行(すいこう)=melaksanakan sampai selesai/tuntas. 実施(じっし)=melaksanakan/mengimplementasikan(始める). 遂行の方が完遂のニュアンスが強い。','medium',NULL,'{"general"}',1677805192);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Suru-Advanced.html','general','「促進する」の意味は？','["妨害する", "速度や発展を加速・後押しする", "評価する", "分析する"]'::jsonb,1,'促進(そくしん)する=mempercepat; mendorong. 発展を促進する=mendorong perkembangan. 促=急かす. 経済促進・健康促進など幅広く使う。','medium',NULL,'{"general"}',1252461798);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Suru-Advanced.html','general','「構築する」はどんな時に使う？','["物を壊す時", "システム・関係・仕組みなど抽象的なものを作る時", "食べ物を作る時", "旅行の時"]'::jsonb,1,'構築(こうちく)する=membangun(システム・関係など). 信頼関係を構築する=membangun hubungan kepercayaan. 建設物より抽象的なものに使う。','medium',NULL,'{"general"}',1372727851);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Suru-Advanced.html','general','「共有する」の意味は？','["独り占めする", "情報・意見・場所などを皆で持ち合う", "批判する", "評価する"]'::jsonb,1,'共有(きょうゆう)する=berbagi; share. 情報を共有する=berbagi informasi. SNSでのシェアもこれ。「共有します」はビジネスでほぼ毎日使う。','medium',NULL,'{"general"}',362371827);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Suru.html','general','「する」のて形は？','["しれて", "して", "すて", "さて"]'::jsonb,1,'する(Grup 3不規則)のて形=して. 勉強する→勉強して. 料理する→料理して。','medium',NULL,'{"general"}',1405984960);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Suru.html','general','「コーヒーにします」の「にする」は？','["場所", "選択・決定をする", "方向", "比較"]'::jsonb,1,'〜にする=memilih/memutuskan ~. コーヒーにします=saya pilih kopi. 注文・選択の場面でよく使う。','medium',NULL,'{"general"}',1241333832);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Suru.html','general','「させていただきます」の意味は？','["させる+いただく=謙遜して許可を得てする(最も丁寧)", "させる+いただく=相手に何かさせる", "命令する", "断る"]'::jsonb,0,'させていただく=melakukan dengan mohon izin (keigo sangat sopan). ビジネスで常用: ご説明させていただきます。','medium',NULL,'{"general"}',63830139);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Suru.html','general','「いい匂いがする」の「がする」は？','["行為をする", "感覚・においなどの感知(〜がする=ada ~)", "好む", "決める"]'::jsonb,1,'〜がする=ada sensasi/perasaan ~. 音がする=ada bunyi. においがする=ada bau. 気がする=rasanya/merasa.','medium',NULL,'{"general"}',1858674337);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Suru.html','general','「する」の使役受身形は？','["させれる", "させられる", "されさせる", "しさせられる"]'::jsonb,1,'する→させる(使役)→させられる(使役受身). 残業させられた=dipaksa lembur. 使役受身は「仕方なくやらされた」感覚。','medium',NULL,'{"general"}',1971855998);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Verb-Suru.html','general','「もっと練習するようにします」の意味は？','["もう練習しない", "これからは練習するよう意識する(決意)", "練習した", "練習させる"]'::jsonb,1,'〜するようにする=berusaha agar ~ (継続的な意識・努力). 毎日運動するようにする=berusaha olahraga tiap hari.','medium',NULL,'{"general"}',22698616);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Wacana-Formal.html','general','論文で使うべき文体は？','["です・ます体", "である体(だ・である)", "どちらでも", "話し言葉"]'::jsonb,1,'学術論文・レポートはである体(文語体)を使う。です・ます体は口語的でレポートには不適切。','medium',NULL,'{"general"}',2073031071);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Wacana-Formal.html','general','「したがって」は接続詞としてどんな役割？','["逆接", "原因→結論(順接)", "例示", "定義"]'::jsonb,1,'したがって=oleh karena itu. 原因・理由から結論へ順接でつなぐ。ゆえに・よって・それゆえも同義。','medium',NULL,'{"general"}',1367695159);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Wacana-Formal.html','general','序論(じょろん)で最初にすべきことは？','["結論を述べる", "背景と問題提起", "証拠を示す", "まとめ"]'::jsonb,1,'序論=pendahuluan. 背景(背景情報)→問題提起(問題の提示)→本稿の目的・主張の順。','medium',NULL,'{"general"}',1627442124);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Wacana-Formal.html','general','「〜によれば」の役割は？','["自分の意見", "引用・出典の明示", "例示", "定義"]'::jsonb,1,'によれば・によると=menurut ~. 出典・権威を示す引用表現。「〜が指摘するように」「〜の研究では」も同様。','medium',NULL,'{"general"}',1848338273);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Wacana-Formal.html','general','「以上を踏まえると」はどこで使う？','["序論", "本論の最初", "結論・まとめへの移行", "タイトル"]'::jsonb,2,'以上を踏まえると=berdasarkan hal di atas. 本論をまとめて結論に移行する時に使う典型的な接続表現。','medium',NULL,'{"general"}',586926610);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Wacana-Formal.html','general','「一方」の役割は？','["例を示す", "対比・別の視点を示す", "結論", "定義"]'::jsonb,1,'一方(いっぽう)=di sisi lain. 2つの異なる側面・立場を対比する接続詞。一方では〜、他方では〜。','medium',NULL,'{"general"}',2120909643);
INSERT INTO jlpt_questions (source_module,category,question,choices,correct_index,explanation,difficulty,jlpt_level,tags,seed) VALUES ('Wacana-Formal.html','general','論文で「具体的には」の後には？','["抽象的な主張", "具体的な例・データ・証拠", "結論", "反論"]'::jsonb,1,'具体的には・例えば・たとえば=例示. 抽象的な主張の後に具体的な事例・データで裏付ける。','medium',NULL,'{"general"}',1948822153);
